QW.lxloaded(26,{"هدي":{"mf":"الهداية دلالة بلطف، ومنه: الهديّة، وهوادي الوحش. أي: متقدّماتها الهادية لغيرها، وخصّ ما كان دلالة بهديت، وما كان إعطاء بأهديت.<br>نحو: أهديت الهديّة، وهديت إلى البيت. إن قيل: كيف جعلت الهداية دلالة بلطف وقد قال الله تعالى: فَاهْدُوهُمْ إِلى صِراطِ الْجَحِيمِ<br>[الصافات/ ٢٣]، وَيَهْدِيهِ إِلى عَذابِ السَّعِيرِ<br>[الحج/ ٤]. قيل: ذلك استعمل فيه استعمال اللّفظ على التّهكّم مبالغة في المعنى كقوله: فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ [آل عمران/ ٢١] وقول الشاعر:<br><span class=\"num\">٤٥٧-</span><br>تحيّة بينهم ضرب وجيع<br><strong>«٢»</strong> وهداية الله تعالى للإنسان على أربعة أوجه:<br>الأوّل: الهداية التي عمّ بجنسها كلّ مكلّف من العقل، والفطنة، والمعارف الضّروريّة التي أعمّ منها كلّ شيء بقدر فيه حسب احتماله كما قال: رَبُّنَا الَّذِي أَعْطى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدى<br>[طه/ ٥٠].<br>الثاني: الهداية التي جعل للناس بدعائه إيّاهم على ألسنة الأنبياء، وإنزال القرآن ونحو ذلك، وهو المقصود بقوله تعالى: وَجَعَلْنا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنا<br>[الأنبياء/ ٧٣].<br>الثالث: التّوفيق الذي يختصّ به من اهتدى، وهو المعنيّ بقوله تعالى: وَالَّذِينَ اهْتَدَوْا زادَهُمْ هُدىً [محمد/ ١٧]، وقوله: وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن/ ١١]، وقوله: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمانِهِمْ [يونس/ ٩]، وقوله: وَالَّذِينَ جاهَدُوا فِينا لَنَهْدِيَنَّهُمْ سُبُلَنا [العنكبوت/ ٦٩]، وَيَزِيدُ اللَّهُ الَّذِينَ اهْتَدَوْا هُدىً [مريم/ ٧٦]، فَهَدَى اللَّهُ الَّذِينَ آمَنُوا [البقرة/ ٢١٣]، وَاللَّهُ يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ<br><br>[البقرة/ ٢١٣].<br>الرّابع: الهداية في الآخرة إلى الجنّة المعنيّ بقوله: سَيَهْدِيهِمْ وَيُصْلِحُ بالَهُمْ [محمد/ ٥]، وَنَزَعْنا ما فِي صُدُورِهِمْ مِنْ غِلٍّ [الأعراف/ ٤٣] إلى قوله: الْحَمْدُ لِلَّهِ الَّذِي هَدانا لِهذا <strong>«١»</strong>.<br>وهذه الهدايات الأربع مترتّبة، فإنّ من لم تحصل له الأولى لا تحصل له الثّانية بل لا يصحّ تكليفه، ومن لم تحصل له الثّانية لا تحصل له الثّالثة والرّابعة، ومن حصل له الرّابع فقد حصل له الثلاث التي قبلها، ومن حصل له الثالث فقد حصل له اللّذان قبله <strong>«٢»</strong>. ثمّ ينعكس، فقد تحصل الأولى ولا يحصل له الثاني ولا يحصل الثالث، والإنسان لا يقدر أن يهدي أحدا إلّا بالدّعاء وتعريف الطّرق دون سائر أنواع الهدايات، وإلى الأوّل أشار بقوله: وَإِنَّكَ لَتَهْدِي إِلى صِراطٍ مُسْتَقِيمٍ [الشورى/ ٥٢]، يَهْدُونَ بِأَمْرِنا [السجدة/ ٢٤]، وَلِكُلِّ قَوْمٍ هادٍ [الرعد/ ٧] أي: داع، وإلى سائر الهدايات أشار بقوله تعالى: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ [القصص/ ٥٦] وكلّ هداية ذكر الله عزّ وجلّ أنه منع الظالمين والكافرين فهي الهداية الثالثة، وهي التّوفيق الذي يختصّ به المهتدون، والرّابعة التي هي الثّواب في الآخرة، وإدخال الجنّة. نحو قوله عزّ وجلّ: كَيْفَ يَهْدِي اللَّهُ قَوْماً إلى قوله: وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ <strong>«٣»</strong> [آل عمران/ ٨٦] وكقوله: ذلِكَ بِأَنَّهُمُ اسْتَحَبُّوا الْحَياةَ الدُّنْيا عَلَى الْآخِرَةِ وَأَنَّ اللَّهَ لا يَهْدِي الْقَوْمَ الْكافِرِينَ [النحل/ ١٠٧] وكلّ هداية نفاها الله عن النبيّ صلّى الله عليه وسلم وعن البشر، وذكر أنهم غير قادرين عليها فهي ما عدا المختصّ من الدّعاء وتعريف الطريق، وذلك كإعطاء العقل، والتّوفيق، وإدخال الجنة، كقوله عزّ ذكره:<br>لَيْسَ عَلَيْكَ هُداهُمْ وَلكِنَّ اللَّهَ يَهْدِي مَنْ يَشاءُ [البقرة/ ٢٧٢]، وَلَوْ شاءَ اللَّهُ لَجَمَعَهُمْ عَلَى الْهُدى [الأنعام/ ٣٥]، وَما أَنْتَ بِهادِ الْعُمْيِ عَنْ ضَلالَتِهِمْ [النمل/ ٨١]، إِنْ تَحْرِصْ عَلى هُداهُمْ فَإِنَّ اللَّهَ لا يَهْدِي مَنْ يُضِلُّ [النحل/ ٣٧]، وَمَنْ يُضْلِلِ اللَّهُ فَما لَهُ مِنْ هادٍ [الزمر/ ٣٦]، وَمَنْ يَهْدِ اللَّهُ فَما لَهُ مِنْ مُضِلٍّ [الزمر/ ٣٧]، إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلكِنَّ اللَّهَ يَهْدِي مَنْ يَشاءُ [القصص/ ٥٦] وإلى هذا المعنى أشار بقوله تعالى: أَفَأَنْتَ تُكْرِهُ النَّاسَ حَتَّى يَكُونُوا مُؤْمِنِينَ<br><br>[يونس/ ٩٩]، وقوله: مَنْ يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ<br>[الإسراء/ ٩٧]، أي: طالب الهدى ومتحرّيه هو الذي يوفّقه ويَهْدِيهِ إلى طريق الجنّة لا من ضادّه، فيتحرّى طريق الضّلال والكفر كقوله: وَاللَّهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ<br>[التوبة/ ٣٧]، وفي أخرى الظَّالِمِينَ [التوبة/ ١٠٩]، وقوله: إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كاذِبٌ كَفَّارٌ [الزمر/ ٣] الكاذب الكفّار: هو الذي لا يقبل هدايته، فإنّ ذلك راجع إلى هذا وإن لم يكن لفظه موضوعا لذلك، ومن لم يقبل هِدَايَتَهُ لم يهده، كقولك: من لم يقبل هَدِيَّتِي لم أهد له، ومن لم يقبل عطيّتي لم أعطه، ومن رغب عنّي لم أرغب فيه، وعلى هذا النحو:<br>وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ [التوبة/ ١٠٩] وفي أخرى: الْفاسِقِينَ [التوبة/ ٨٠] وقوله: أَفَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ أَمَّنْ لا يَهِدِّي إِلَّا أَنْ يُهْدى<br>[يونس/ ٣٥]، وقد قرئ: يَهِدِّي إِلَّا أَنْ يُهْدى <strong>«١»</strong> أي: لا يهدي غيره ولكن يهدى. أي: لا يعلم شيئا ولا يعرف أي لا هداية له، ولو هدي أيضا لم يهتد، لأنها موات من حجارة ونحوها، وظاهر اللّفظ أنه إذا هدي اهْتَدَى لإخراج الكلام أنها أمثالكم كما قال تعالى: إِنَّ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللَّهِ عِبادٌ أَمْثالُكُمْ [الأعراف/ ١٩٤] وإنّما هي أموات، وقال في موضع آخر:<br>وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ ما لا يَمْلِكُ لَهُمْ رِزْقاً مِنَ السَّماواتِ وَالْأَرْضِ شَيْئاً وَلا يَسْتَطِيعُونَ [النحل/ ٧٣]، وقوله عزّ وجلّ: إِنَّا هَدَيْناهُ السَّبِيلَ [الإنسان/ ٣]، وَهَدَيْناهُ النَّجْدَيْنِ [البلد/ ١٠]، وَهَدَيْناهُمَا الصِّراطَ الْمُسْتَقِيمَ [الصافات/ ١١٨] فذلك إشارة إلى ما عرّف من طريق الخير والشّرّ <strong>«٢»</strong>، وطريق الثواب والعقاب بالعقل والشرع وكذا قوله: فَرِيقاً هَدى وَفَرِيقاً حَقَّ عَلَيْهِمُ الضَّلالَةُ<br>[الأعراف/ ٣٠]، إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلكِنَّ اللَّهَ يَهْدِي مَنْ يَشاءُ [القصص/ ٥٦]، وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن/ ١١] فهو إشارة إلى التّوفيق الملقى في الرّوع فيما يتحرّاه الإنسان وإياه عنى بقوله عزّ وجلّ: وَالَّذِينَ اهْتَدَوْا زادَهُمْ هُدىً [محمد/ ١٧] وعدّي الهِدَايَةُ في مواضع بنفسه، وفي مواضع باللام، وفي مواضع بإلى، قال تعالى:<br>وَمَنْ يَعْتَصِمْ بِاللَّهِ فَقَدْ هُدِيَ إِلى صِراطٍ مُسْتَقِيمٍ<br>[آل عمران/ ١٠١]، وَاجْتَبَيْناهُمْ وَهَدَيْناهُمْ إِلى صِراطٍ مُسْتَقِيمٍ [الأنعام/ ٨٧] وقال: أَفَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ<br>[يونس/ ٣٥] وقال: هَلْ لَكَ إِلى أَنْ تَزَكَّى وَأَهْدِيَكَ إِلى رَبِّكَ فَتَخْشى [النازعات/ ١٨- ١٩].<br>وما عدّي بنفسه نحو: وَلَهَدَيْناهُمْ صِراطاً مُسْتَقِيماً<br><br>[النساء/ ٦٨]، وَهَدَيْناهُمَا الصِّراطَ الْمُسْتَقِيمَ [الصافات/ ١١٨]، اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ [الفاتحة/ ٦]، أَتُرِيدُونَ أَنْ تَهْدُوا مَنْ أَضَلَّ اللَّهُ [النساء/ ٨٨]، وَلا لِيَهْدِيَهُمْ طَرِيقاً [النساء/ ١٦٨]، أَفَأَنْتَ تَهْدِي الْعُمْيَ [يونس/ ٤٣]، وَيَهْدِيهِمْ إِلَيْهِ صِراطاً مُسْتَقِيماً [النساء/ ١٧٥].<br>ولمّا كانت الهِدَايَةُ والتّعليم يقتضي شيئين:<br>تعريفا من المعرّف، وتعرّفا من المعرّف، وبهما تمّ الهداية والتّعليم فإنه متى حصل البذل من الهَادِي والمعلم ولم يحصل القبول صحّ أن يقال: لم يَهْدِ ولم يعلّم اعتبارا بعدم القبول، وصحّ أن يقال: هَدَى وعلّم اعتبارا ببذله، فإذا كان كذلك صحّ أن يقال: إنّ الله تعالى لم يهد الكافرين والفاسقين من حيث إنه لم يحصل القبول الذي هو تمام الهداية والتّعليم، وصحّ أن يقال: هَدَاهُمْ وعلّمهم من حيث إنه حصل البذل الذي هو مبدأ الْهِدَايَةِ. فعلى الاعتبار بالأول يصحّ أن يحمل قوله تعالى: وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ [التوبة/ ١٠٩]، وَالْكافِرِينَ [التوبة/ ٣٧] وعلى الثاني قوله عزّ وجلّ: وَأَمَّا ثَمُودُ فَهَدَيْناهُمْ فَاسْتَحَبُّوا الْعَمى عَلَى الْهُدى<br>[فصلت/ ١٧] والأولى حيث لم يحصل القبول المفيد فيقال: هداه الله فلم يهتد، كقوله: وَأَمَّا ثَمُودُ الآية، وقوله: لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشاءُ إلى قوله: وَإِنْ كانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ <strong>«١»</strong> [البقرة/ ١٤٢- ١٤٣] فهم الّذين قبلوا هداه واهتدوا به، وقوله تعالى: اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ [الفاتحة/ ٦]، وَلَهَدَيْناهُمْ صِراطاً مُسْتَقِيماً [النساء/ ٦٨] فقد قيل: عني به الهِدَايَةُ العامّة التي هي العقل، وسنّة الأنبياء، وأمرنا أن نقول ذلك بألسنتنا وإن كان قد فعل ليعطينا بذلك ثوابا كما أمرنا أن نقول: اللهمّ صلّ على محمد وإن كان قد صلّى عليه بقوله: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ [الأحزاب/ ٥٦] وقيل: إن ذلك دعاء بحفظنا عن استغواء الغواة واستهواء الشّهوات، وقيل: هو سؤال للتّوفيق الموعود به في قوله: وَالَّذِينَ اهْتَدَوْا زادَهُمْ هُدىً<br>[محمد/ ١٧] وقيل: سؤال للهداية إلى الجنّة في الآخرة، وقوله عزّ وجلّ: وَإِنْ كانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ [البقرة/ ١٤٣] فإنه يعني به من هداه بالتّوفيق المذكور في قوله عزّ وجلّ: وَالَّذِينَ اهْتَدَوْا زادَهُمْ هُدىً.<br>والهُدَى والهِدَايَةُ في موضوع اللّغة واحد لكن قد خصّ الله عزّ وجلّ لفظة الهدى بما تولّاه<br><br>وأعطاه، واختصّ هو به دون ما هو إلى الإنسان نحو: هُدىً لِلْمُتَّقِينَ [البقرة/ ٢]، أُولئِكَ عَلى هُدىً مِنْ رَبِّهِمْ [البقرة/ ٥]، هُدىً لِلنَّاسِ [البقرة/ ١٨٥]، فَإِمَّا يَأْتِيَنَّكُمْ مِنِّي هُدىً فَمَنْ تَبِعَ هُدايَ [البقرة/ ٣٨]، قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدى [الأنعام/ ٧١]، وَهُدىً وَمَوْعِظَةٌ لِلْمُتَّقِينَ [آل عمران/ ١٣٨]، وَلَوْ شاءَ اللَّهُ لَجَمَعَهُمْ عَلَى الْهُدى [الأنعام/ ٣٥]، إِنْ تَحْرِصْ عَلى هُداهُمْ فَإِنَّ اللَّهَ لا يَهْدِي مَنْ يُضِلُّ [النحل/ ٣٧]، أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى [البقرة/ ١٦].<br>والاهْتِدَاءُ يختصّ بما يتحرّاه الإنسان على طريق الاختيار، إمّا في الأمور الدّنيويّة، أو الأخرويّة قال تعالى: وَهُوَ الَّذِي جَعَلَ لَكُمُ النُّجُومَ لِتَهْتَدُوا بِها [الأنعام/ ٩٧]، وقال: إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجالِ وَالنِّساءِ وَالْوِلْدانِ لا يَسْتَطِيعُونَ حِيلَةً وَلا يَهْتَدُونَ سَبِيلًا<br>[النساء/ ٩٨] ويقال ذلك لطلب الهداية نحو: وَإِذْ آتَيْنا مُوسَى الْكِتابَ وَالْفُرْقانَ لَعَلَّكُمْ تَهْتَدُونَ<br>[البقرة/ ٥٣]، وقال: فَلا تَخْشَوْهُمْ وَاخْشَوْنِي وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ [البقرة/ ١٥٠]، فَإِنْ أَسْلَمُوا فَقَدِ اهْتَدَوْا [آل عمران/ ٢٠]، فَإِنْ آمَنُوا بِمِثْلِ ما آمَنْتُمْ بِهِ فَقَدِ اهْتَدَوْا [البقرة/ ١٣٧].<br><strong>ويقال المُهْتَدِي لمن يقتدي بعالم نحو:</strong><br>أَوَلَوْ كانَ آباؤُهُمْ لا يَعْلَمُونَ شَيْئاً وَلا يَهْتَدُونَ [المائدة/ ١٠٤] تنبيها أنهم لا يعلمون بأنفسهم ولا يقتدون بعالم، وقوله: فَمَنِ اهْتَدى فَإِنَّما يَهْتَدِي لِنَفْسِهِ وَمَنْ ضَلَّ فَقُلْ إِنَّما أَنَا مِنَ الْمُنْذِرِينَ [النمل/ ٩٢] فإن الِاهْتِدَاءَ هاهنا يتناول وجوه الاهتداء من طلب الهداية، ومن الاقتداء، ومن تحرّيها، وكذا قوله: وَزَيَّنَ لَهُمُ الشَّيْطانُ أَعْمالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ فَهُمْ لا يَهْتَدُونَ [النمل/ ٢٤] وقوله: وَإِنِّي لَغَفَّارٌ لِمَنْ تابَ وَآمَنَ وَعَمِلَ صالِحاً ثُمَّ اهْتَدى [طه/ ٨٢] فمعناه: ثم أدام طلب الهداية، ولم يفترّ عن تحرّيه، ولم يرجع إلى المعصية. وقوله:<br>الَّذِينَ إِذا أَصابَتْهُمْ مُصِيبَةٌ إلى قوله:<br>وَأُولئِكَ هُمُ الْمُهْتَدُونَ<br><strong><strong>«١»</strong> [البقرة/ ١٥٧] أي:</strong><br>الذين تحرّوا هدايته وقبلوها وعملوا بها، وقال مخبرا عنهم: وَقالُوا يا أَيُّهَا السَّاحِرُ ادْعُ لَنا رَبَّكَ بِما عَهِدَ عِنْدَكَ إِنَّنا لَمُهْتَدُونَ<br>[الزخرف/ ٤٩].<br>والهَدْيُ مختصّ بما يُهْدَى إلى البيت. قال الأخفش <strong>«٢»</strong> : والواحدة هَدْيَةٌ، قال: ويقال للأنثى هَدْيٌ كأنه مصدر وصف به، قال الله تعالى:<br>فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ<br><br>[البقرة/ ١٩٦]، هَدْياً بالِغَ الْكَعْبَةِ<br>[المائدة/ ٩٥]، وَلَا الْهَدْيَ وَلَا الْقَلائِدَ [المائدة/ ٢]، وَالْهَدْيَ مَعْكُوفاً [الفتح/ ٢٥].<br>والهَدِيَّةُ مختصّة باللُّطَف الذي يُهْدِي بعضنا إلى بعضٍ. قال تعالى: وَإِنِّي مُرْسِلَةٌ إِلَيْهِمْ بِهَدِيَّةٍ [النمل/ ٣٥]، بَلْ أَنْتُمْ بِهَدِيَّتِكُمْ تَفْرَحُونَ [النمل/ ٣٦] والمِهْدَى الطّبق الذي يهدى عليه، والْمِهْدَاءُ: من يكثر إِهْدَاءَ الهديّة، قال الشاعر:<br><span class=\"num\">٤٦٧-</span><br>وإنّك مهداء الخنا نطف الحشا<br><strong>«١»</strong> والْهَدِيُّ يقال في الهدي، وفي العروس يقال:<br>هَدَيْتُ العروسَ إلى زوجها، وما أحسن هَدِيَّةَ فلان وهَدْيَهُ، أي: طريقته، وفلان يُهَادِي بين اثنين: إذا مشى بينهما معتمدا عليهما، وتَهَادَتِ المرأة: إذا مشت مشي الهدي.","mq":[[],"الهاء والدال والحرف المعتلّ: أصلانِ [أحدهما] التقدُّمُ للإرشاد، والآخر بَعثة لَطَفٍ (٣)<br>.<br>فالأوَّل قولُهم: هدَيتُه الطَّريق هِدايةً، أى تقدّمتُه لأرشدَه. وكلُّ متقدِّمٍ لذلك هادٍ. قال:<br>إذا كان هادى الفتَى فى البلا … دِ صدر القَناةِ أطاعَ * الأميرا (٤)<br>وينشعب هذا فيقال: الهُدَى: خِلافُ الضَّلالة. تقو"],"ln":"<p><b>1.</b> <b class=\"ar\">هَدَاهُ</b> <i>He directed him,</i> or <i>guided him,</i> to the way; (K, * TA;) <i>directed him aright;</i> or <i>caused him to take,</i> or <i>follow, a right way</i> or <i>course</i> or <i>direction.</i> (K, TA.) See 8. -b2- <span class=\"ar\">هَدَى العَرُوسَ</span> <i>He sent</i> [or <i>conducted</i>] <i>the bride</i> (MA, KL) to her husband, (MA,) or to the house of her husband: (KL;) <i>i. q.</i> <span class=\"ar\">زَفَّهَا</span>, (K in art. <span class=\"ar\">زف</span>,) and so <span class=\"ar\"> <span class=\"ar\">أَهْدَاهَا</span></span>. (Msb in that art.) -b3- <span class=\"ar\">يَهْدِى</span> meaning <span class=\"ar\">يُؤَدِّى</span>: see an ex. in a verse cited voce <span class=\"ar\">طَبَعٌ</span>.</p><p><b>4.</b> <b class=\"ar\">أَهْدَىَ</b> see 1.</p><p><b>6.</b> <b class=\"ar\">تَهَادَنَا</b> <i>They</i> (two parties who had been at war) <i>made a truce, each with the other.</i> (T, art. <span class=\"ar\">نبذ</span>.)</p><p><b>8.</b> <b class=\"ar\">اِهْتَدَى</b> <i>He became rightly directed; followed a right direction;</i> (K;) <i>went aright;</i> as also <span class=\"ar\"> <span class=\"ar\">هَدَى</span></span>. (S.) -b2- <i>He guided himself.</i> -b3- <i>He went a right way: went aright.</i> -b4- <span class=\"ar\">لَا</span> <span class=\"ar\">يَهْتَدِى إِلَى جِهَةٍ</span> <i>He cannot go aright: or knows not the way that he would pursue; or knows not in what direction to go:</i> sometimes said of a drunken man. -b5- <span class=\"ar\">لَا يَهْتَدِى لِأَمْرِهِ</span> means <i>He does not,</i> or <i>cannot, find the way to accomplish,</i> or <i>perform, his affair.</i> -b6- <span class=\"ar\">اِهْتَدَى</span> <i>He found,</i> (MA,) or <i>took</i> (KL,) <i>the right way</i> or <i>road.</i> (MA, KL.) -b7- <span class=\"ar\">دَاهِيَةُ لاَ يُهْتَدَى لَهَا</span>, by which <span class=\"ar\">دَاهِيَةُ الغَبَرِ</span> is expl. in the S and O, means <span class=\"ar\">لَا يُهْتَدَى للَّنَّجَآءِ</span> <span class=\"ar\">مِنْهَا</span>, by which the same phrase is expl. in the JK: or it may be well rendered <i>A calamity in relation to which one knows not the right course to pursue.</i> -b8- <span class=\"ar\">اِهْتَدَى</span> also signifies <i>He continued to be rightly directed,</i> or <i>to follow a right dirertion:</i> and <i>he sought to be rightly directed,</i> or <i>to follow a right direction.</i> (TA.) -b9- <span class=\"ar\">اِهَدَّى</span> and <span class=\"ar\">اِهِدِّى</span>, for <span class=\"ar\">اِهْتَدَى</span>; like <span class=\"ar\">اِعَذَّرَ</span> and <span class=\"ar\">اِعِذِّرَ</span>, for <span class=\"ar\">اِعْتَذَرَ</span>.</p><p><b class=\"ar\">هَدْىٌ</b> <i>A way, course, method, mode,</i> or <i>manner, of acting,</i> or <i>conduct,</i> or <i>proceeding,</i> or <i>the like;</i> (Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">هِدْيَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">هَدْيَةٌ</span></span>: (K:) or to the second and third: and the first is pl. [or coll. gen. n.] of the last: (S:) and <i>a god way,</i> &amp;c.: and <i>calm,</i> or <i>placid, deportment;</i> or <i>calmness,</i> or <i>placidity, of deportment:</i> (TA:) see also <span class=\"ar\">دَلٌ</span>. -b2- <span class=\"ar\">هَدْىٌ</span> [<i>Conduct, mode of life; manners</i>]. -A2- See <span class=\"ar\">هَدِىٌّ</span>.</p><p><b class=\"ar\">هُوَ عَلَى هُدًى</b> <i>He is following,</i> or <i>he follows, a right direction.</i> -b2- <span class=\"ar\">الهُدَى</span> <i>The Kur-án.</i> (Bd, Jel in lxxii. 13, &amp;c.)</p><p><b class=\"ar\">هِدْيَةٌ</b> and <span class=\"ar\">هَدْيَةٌ</span>: see <span class=\"ar\">هَدْيٌ</span>.</p><p><b class=\"ar\">هَدِيَّةٌ</b> [n. un. of <span class=\"ar\">هَدِىٌّ</span>] <i>A present;</i> i. e. <i>a thing sent to another in token of courtesy</i> or <i>honour:</i> (Msb;) such as is termed <span class=\"ar\">طَرِيفٌ</span> and <span class=\"ar\">لَطَفٌ</span>. (JK.) -b2- <span class=\"ar\"> <span class=\"ar\">هَدْىٌ</span></span> and <span class=\"ar\">هَدِىٌّ</span> [coll. gen. ns.] <i>What one brings as an offering to Mekkeh,</i> (K,) <i>or to the Kaabeh,</i> (Beyd, v. 2,) <i>or to the Haram,</i> (S, Mgh,) <i>consisting of camels</i> (Lth, S, Mgh, Msb) <i>or other beasts,</i> (Lth,) namely <i>kine or sheep or goats,</i> (Mgh,) <i>to be sacrificed,</i> (TA,) <i>and of goods or commodities:</i> (Lth:) n. un. with <span class=\"ar\">ة</span>. (S, &amp;c.) -b3- Also, <i>Camels,</i> absolutely. (TA.) -b4- <span class=\"ar\">هَدِىٌّ</span> also <i>One who is entitled to respect,</i> or <i>honour,</i> or <i>protection:</i> so in a verse cited voce <span class=\"ar\">اِسْتَبَآءَ</span>. (ISk in T in art. <span class=\"ar\">بوأ</span>.)</p><p><b class=\"ar\">هَادٍ</b> : see an ex. of its pl. <span class=\"ar\">هَوَادِى</span> meaning <i>Necks</i> of horses, voce <span class=\"ar\">تَالٍ</span>. -b2- <span class=\"ar\">هَادِيَةٌ</span> The <i>fore part of the neck of a horse.</i> (K in art. <span class=\"ar\">سلف</span>.) -b3- <span class=\"ar\">أَخَذَ هَادِىَ الرَّحَى فَجَعَلَ يُدِيرُهَا</span> [<i>He took the handle of the mill, and begun to turn it</i>]. (K, art. <span class=\"ar\">خبز</span>.)</p><p><b class=\"ar\">أَهْدَى مِنْ دُعَيْمِيصِ الرَّمْلِ</b> <i>More expert,</i> &amp;c: see art. <span class=\"ar\">دعمص</span>.</p><p><b class=\"ar\">المَهْدِىُّ</b> , meaning <i>The directed</i> by God to the truth, is a proper name, and the name of him of whose coming at the end of time the happy tidings have been announced. (TA.) [It is always so pronounced by the Arabs in the present day: not <span class=\"ar\">المُهْدِى</span>.]</p>"},"هلك":{"mf":"الْهَلَاكُ على ثلاثة <strong>«٢»</strong> أوجه:<br><br>افتقاد الشيء عنك، وهو عند غيرك موجود كقوله تعالى: هَلَكَ عَنِّي سُلْطانِيَهْ<br>[الحاقة/ ٢٩].<br><strong>- وهَلَاكِ الشيء باستحالة وفساد كقوله:</strong><br>وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ<br>[البقرة/ ٢٠٥] ويقال: هَلَكَ الطعام.<br>والثالث: الموت كقوله: إِنِ امْرُؤٌ هَلَكَ<br>[النساء/ ١٧٦] وقال تعالى مخبرا عن الكفّار:<br>وَما يُهْلِكُنا إِلَّا الدَّهْرُ<br>[الجاثية/ ٢٤].<br>ولم يذكر الله الموت بلفظ الهلاك حيث لم يقصد الذّمّ إلّا في هذا الموضع، وفي قوله:<br>وَلَقَدْ جاءَكُمْ يُوسُفُ مِنْ قَبْلُ بِالْبَيِّناتِ فَما زِلْتُمْ فِي شَكٍّ مِمَّا جاءَكُمْ بِهِ حَتَّى إِذا هَلَكَ قُلْتُمْ لَنْ يَبْعَثَ اللَّهُ مِنْ بَعْدِهِ رَسُولًا<br>[غافر/ ٣٤]، وذلك لفائدة يختصّ ذكرها بما بعد هذا الكتاب.<br>والرابع: بطلان الشيء من العالم وعدمه رأسا، وذلك المسمّى فناء المشار إليه بقوله:<br>كُلُّ شَيْءٍ هالِكٌ إِلَّا وَجْهَهُ<br>[القصص/ ٨٨] ويقال للعذاب والخوف والفقر: الهَلَاكُ، وعلى هذا قوله: وَإِنْ يُهْلِكُونَ إِلَّا أَنْفُسَهُمْ وَما يَشْعُرُونَ<br>[الأنعام/ ٢٦]، وَكَمْ أَهْلَكْنا قَبْلَهُمْ مِنْ قَرْنٍ<br>[مريم/ ٧٤]، وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْناها<br>[الأعراف/ ٤]، فَكَأَيِّنْ مِنْ قَرْيَةٍ أَهْلَكْناها [الحج/ ٤٥]، أَفَتُهْلِكُنا بِما فَعَلَ الْمُبْطِلُونَ<br>[الأعراف/ ١٧٣]، أَتُهْلِكُنا بِما فَعَلَ السُّفَهاءُ مِنَّا [الأعراف/ ١٥٥]. وقوله:<br>فَهَلْ يُهْلَكُ إِلَّا الْقَوْمُ الْفاسِقُونَ [الأحقاف/ ٣٥] هو الهلاك الأكبر الذي دلّ النبيّ صلّى الله عليه وسلم بقوله:<br><strong>«لا شرّ كشرّ بعده النّار»</strong> <strong>«١»</strong>، وقوله تعالى: ما شَهِدْنا مَهْلِكَ أَهْلِهِ<br>[النمل/ ٤٩]. والْهُلْكُ بالضّمّ: الْإِهْلَاكُ، وَالتَّهْلُكَةُ: ما يؤدّي إلى الهلاك، قال تعالى: وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة/ ١٩٥] وامرأة هَلُوكٌ: كأنها تَتَهَالَكُ في مشيها كما قال الشاعر:<br><span class=\"num\">٤٦٩-</span><table class=\"poem\"><tr><td>مريضات أو بات التّهادي كأنّما </td><td> تخاف على أحشائها أن تقطّعا</td></tr></table><strong>«٢»</strong> وكنّي بِالْهَلُوكِ عن الفاجرة لتمايلها، والهَالِكِيُّ: كان حدّادا من قبيلة هَالِكٍ، فسمّي كلّ حدّاد هالكيّا، والْهُلْكُ: الشيء الهالك.","mq":[["كسر وسقوط"],"الهاء واللام والكاف: يدلُّ على كَسْرٍ وسُقوط. منه الهلاكُ:<br>السُّقوط، ولذلك يقال للميت هَلَكَ. واهتَلكت القَطاةُ خَوْفَ البازِى: رمَتْ بنَفْسها على المهالك. فأمَّا قول الهذلىّ (٣)<br>:<br>* ولا هُلُكِ المفارِشِ عُزَّل (٤) *<br>فيقول: ليس أمَّهاتُهم أمَّهاتِ سَوء. وامرأةٌ هَلوكٌ، إذا تَهالكت فى غُنْجِها متكسِّ"],"ln":"<p><b>1.</b> <b class=\"ar\">هَلَكَ</b> , inf. n. <span class=\"ar\">هَلَاكٌ</span> &amp;c., (S, K, &amp;c.,) <i>He,</i> or <i>it, perished, came to nought, came to an end, passed away, was not, was no more,</i> or <i>became non-existent</i> or <i>annihilated:</i> (KL, PS in explanation of <span class=\"ar\">هَلاَكٌ</span>, &amp;c.:) or <i>fell:</i> or <i>became in a bad,</i> or <i>corrupt, state; became corrupted, vitiated, marred,</i> or <i>spoiled:</i> or <i>went away, no one knew whither:</i> (Mgh in explanation of <span class=\"ar\">هَلاَكٌ</span>:) <i>he died.</i> (K.) -b2- <span class=\"ar\">هَلَكَتْ أَرْضُهُ</span> <i>His land had its herbage dried up by drought:</i> see <span class=\"ar\">جَرِبَ</span>.</p><p><b>2.</b> <b class=\"ar\">وَادِى تُهُلِّكَ</b> <i>I. q.</i> <span class=\"ar\">تُضُلِّل</span></p><p><b>4.</b> <b class=\"ar\">أَهْلَكَهُ</b> <i>He destroyed, made an end of,</i> or <i>caused to perish</i> or <i>come to an end, made away, did away with,</i> or <i>brought to nought, him,</i> or <i>it; took away his life.</i></p><p><b>6.</b> <b class=\"ar\">تَهَالَكَ غَمًّا</b> [app. <i>He perished gradually by reason of grief.</i>] (A, art. <span class=\"ar\">سوس</span>: see 1 in that art.) -b2- <span class=\"ar\">تَهَالَكَ عَلَيْهِ</span> <i>He was vehemently eager for it.</i> (TA.) -b3- <span class=\"ar\">تَهَالَكَ فِيهِ</span> <i>He strove, laboured, toiled,</i> or <i>exerted himself, in it,</i> namely in running; as also <span class=\"ar\"> <span class=\"ar\">اِهْتَلَكَ</span></span>. (TA.) <i>He strove, laboured, toiled,</i> or <i>exerted himself, and hastened, in it,</i> namely an affair; as also <span class=\"ar\">استهلك <span class=\"ar\">فيه</span></span>. (TA.) -b4- <span class=\"ar\">تَهَالَكَتْ</span> said of a she-camel, <i>i. q.</i> <span class=\"ar\">عَشِقَتْ</span> [<i>She vehemently desired the stallion</i>]. (AA, TA in art. <span class=\"ar\">عشق</span>.)</p><p><b>8.</b> <b class=\"ar\">إِهْتَلَكَ</b> see 6.</p><p><b>10.</b> <b class=\"ar\">اِسْتَهْلَكَ</b> properly signifies <i>He sought, or courted, destruction;</i> like <span class=\"ar\">اِسْتَمَاتَ</span>: see <span class=\"ar\">مُسْتَمِيتَ</span>: and see an ex. voce <span class=\"ar\">شَرْشَرَةٌ</span>. -b2- <span class=\"ar\">اِسْتَهْلَكَ فِى كَذَا</span> <i>He</i> (a man) <i>distressed, troubled,</i> or <i>fatigued, himself in,</i> or <i>respecting, such a thing.</i> (TA.) See also 6.</p><p><b class=\"ar\">هَلَكَةٌ</b> <i>The drying up of the plants,</i> or <i>herbage.</i> (AHn, TA.) See <span class=\"ar\">هَلاَكٌ</span>.</p><p><b class=\"ar\">هَلاَكٌ</b> [<i>Perdition; destruction; a state of perdition</i> or <i>destruction: a lost state;</i>] <i>death.</i> (K.) -b2- <span class=\"ar\">هَلاَكٌ</span> and <span class=\"ar\"> <span class=\"ar\">هَلَكَةٌ</span></span> are syn. (S, Msb, K.) -b3- <span class=\"ar\">اِرْتَبَكَ فِى اِنْهَلَكَاتِ</span> <i>He stuck fast in cases of perdition:</i> see art. <span class=\"ar\">ربك</span>.</p><p><b class=\"ar\">هَالِكٌ</b> <i>Dead;</i> or <i>dying.</i> (Bd, Jel in xii. 85) -b2- <span class=\"ar\">هَالِكٌ</span> sometimes means <i>Subject to perish;</i> as in the Kur, xxviii. last verse.</p><p><b class=\"ar\">مَهْلُكٌ</b> : see <span class=\"ar\">أَلُوكٌ</span>.</p><p><b class=\"ar\">مَهْلِكٌ</b> <i>Death:</i> see a verse cited voce <span class=\"ar\">سَهُوٌ</span>.</p><p><b class=\"ar\">مَهْلَِكَةٌ</b> <i>A cause of perdition,</i> or <i>of death.</i> (TA in art. <span class=\"ar\">بخل</span>.) -b2- (tropical:) <i>A place of perdition</i> or <i>death:</i> and <i>a desert:</i> (KL:) or <i>a</i> [<i>desert,</i> or <i>such as is termed</i>] <span class=\"ar\">مَفَازَة</span>; (S, K, TA;) because persons perish therein; (Z, TA;) or because it urges [or leads] to perdition. (TA.) See <span class=\"ar\">جَادَّةٌ</span>.</p><p><b class=\"ar\">هُوَ مُسْتَهْلِكٌ إِلَى كَذَا</b> <i>i. q.</i> <span class=\"ar\">مُسْتَمِيتٌ</span> [q. v.]. (TA, art. <span class=\"ar\">موت</span>, from the A.) -b2- <span class=\"ar\">مُسْتَهْلِكُ الوِرْدِ</span> A road <i>that destroys him who seeks water, by reason of its far extent.</i> (O.)</p>"},"هزأ":{"mf":"الهُزْءُ: مزح في خفية، وقد يقال لما هو كالمزح، فممّا قصد به المزح قوله: اتَّخَذُوها هُزُواً وَلَعِباً<br>[المائدة/ ٥٨]، وَإِذا عَلِمَ مِنْ آياتِنا شَيْئاً اتَّخَذَها هُزُواً [الجاثية/ ٩]، وَإِذا رَأَوْكَ إِنْ يَتَّخِذُونَكَ إِلَّا هُزُواً [الفرقان/ ٤١]، وَإِذا رَآكَ الَّذِينَ كَفَرُوا إِنْ يَتَّخِذُونَكَ إِلَّا هُزُواً [الأنبياء/ ٣٦]، أَتَتَّخِذُنا هُزُواً [البقرة/ ٦٧]، وَلا تَتَّخِذُوا آياتِ اللَّهِ هُزُواً [البقرة/ ٢٣١]، فقد عظّم تبكيتهم، ونبّه على خبثهم من حيث إنه وصفهم بعد العلم بها، والوقوف على صحّتها بأنهم يَهْزَءُونَ بها، يقال: هَزِئْتُ به، واسْتَهْزَأْتُ، والاسْتِهْزَاءُ: ارتياد الْهُزُؤِ وإن كان قد يعبّر به عن تعاطي الهزؤ، كالاستجابة في كونها ارتيادا للإجابة، وإن كان قد يجري مجرى الإجابة. قال تعالى: قُلْ أَبِاللَّهِ وَآياتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِؤُنَ<br>[التوبة/ ٦٥]، وَحاقَ بِهِمْ ما كانُوا بِهِ يَسْتَهْزِؤُنَ [هود/ ٨]، ما يَأْتِيهِمْ مِنْ رَسُولٍ إِلَّا كانُوا بِهِ يَسْتَهْزِؤُنَ [الحجر/ ١١]، إِذا سَمِعْتُمْ آياتِ اللَّهِ يُكْفَرُ بِها وَيُسْتَهْزَأُ بِها<br>[النساء/ ١٤٠]، وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ<br>[الأنعام/ ١٠] والِاسْتِهْزَاءُ من الله في الحقيقة لا يصحّ، كما لا يصحّ من الله اللهو واللّعب، تعالى الله عنه. وقوله: اللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِي طُغْيانِهِمْ يَعْمَهُونَ [البقرة/ ١٥] أي: يجازيهم جزاء الهزؤ.<br>ومعناه: أنه أمهلهم مدّة ثمّ أخذهم مغافصة <strong>«١»</strong>، فسمّى إمهاله إيّاهم استهزاء من حيث إنهم اغترّوا به اغترارهم بالهزؤ، فيكون ذلك كالاستدراج من حيث لا يعلمون، أو لأنهم استهزءوا فعرف ذلك منهم، فصار كأنه يهزأ بهم كما قيل: من خدعك وفطنت له ولم تعرّفه فاحترزت منه فقد خدعته. وقد روي: [أنّ الْمُسْتَهْزِئِينَ في الدّنيا يفتح لهم باب من الجنّة فيسرعون نحوه فإذا انتهوا إليه سدّ عليهم فذلك قوله: فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ [المطففين/ ٣٤] <strong>«٢»</strong> وعلى هذه<br><br>الوجوه قوله عزّ وجلّ: سَخِرَ اللَّهُ مِنْهُمْ وَلَهُمْ عَذابٌ أَلِيمٌ [التوبة/ ٧٩].","mq":[[],"الهاء والزاء والهمزة كلمة واحدة. يقال: هَزِئَ واستهزَأَ، إذا سَخِرَ.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَزَأَ مِنْهُ</b> , (K,) and <span class=\"ar\">بِهِ</span>; (S, K;) and <span class=\"ar\">هَزِئَ</span> (S, K) followed by <span class=\"ar\">منه</span> and <span class=\"ar\">به</span>; (Akh, S;) but accord. to Yoo, we should say <span class=\"ar\">هزئ به</span> only; not <span class=\"ar\">منه</span>; (TA;) aor. <b class=\"ar\">هَزَاَ</b> , inf. n. <span class=\"ar\">هُزْءٌ</span> and <span class=\"ar\">هُزُؤٌ</span> (S, K) and <span class=\"ar\">هُزُوْءٌ</span> (TA) and <span class=\"ar\">مَهْزَأَةٌ</span>; (S, K;) and <span class=\"ar\"> <span class=\"ar\">تهزّأ</span>به</span>, (AZ, S, K,) and <span class=\"ar\"> <span class=\"ar\">استهزأ</span>به</span>; (S, K;) <i>He mocked at, scoffed at, laughed at, derided,</i> or <i>ridiculed, him.</i> (S, K.) -b2- The most approved reading of <span class=\"ar\"> <span class=\"ar\">مُسْتَهْزِئُونَ</span></span> in the Kur, ii. 13, is with the <span class=\"ar\">ء</span> fully pronounced: some alleviate it: and some read <span class=\"ar\">مُسْتَهْزِيُرنَ</span>: and some <span class=\"ar\">مُسْتَهْزُونَ</span>; (but this pronunciation is of weak authority;) and say <span class=\"ar\">إِسْتَهْزَيْتُ</span> for <span class=\"ar\">إِسْتَهْزَأْتُ</span>. (Zj.) -b3- <span class=\"ar\">السَّرَابُ يَهْزَأُ</span> <span class=\"ar\">بِالرَّكْبِ</span> (tropical:) [<i>The mirage mocks the company of riders</i>]. (A.) -A2- <span class=\"ar\">هَزَأَ</span>, (K,) inf. n. <span class=\"ar\">هَزْءٌ</span>, (TA,) <i>He,</i> or <i>it, broke</i> a thing. (K.) -b2- A poet says, describing a coat of mail, <span class=\"ar\">لَهَا عُكَنْ تَرُدُّ النَّبْلَ خَنْسًا</span> <span class=\"ar\">وَتَهْزَأُ بِالْمَعَابِلِ وَالقِطَاعِ</span> [<i>It has creases that repel the arrows, making them to recede, and break the broad and long arrow-heads, and those which are small and broad</i>]. The <span class=\"ar\">ب</span> in <span class=\"ar\">بالمعابل</span> is redundant. This is the opinion of the lexicologists, except ISd, who thinks that this is an error, and that <span class=\"ar\">تهزأ</span> here means “ mocks. ” (TA.) -A3- <span class=\"ar\">هَزَأَ إِبِلَهُ</span> (K; but it is thought that this may be a mistake for <span class=\"ar\">هَرَأَ</span>, TA,) inf. n. <span class=\"ar\">هَزْءٌ</span>; (TA;) and <span class=\"ar\">اهزأ <span class=\"ar\">ها</span></span>; (K;) <i>He killed his camels with cold.</i> IAar says, that <span class=\"ar\">اهزأهُ البَرْدُ</span> and <span class=\"ar\">اهرأهُ</span> both signify <i>The cold killed him.</i> (TA.) -A4- <span class=\"ar\">هَزَأَ</span> <i>He put in motion,</i> [or <i>excited,</i>) the beast on which he rode. (As, K.) -A5- <span class=\"ar\">هَزَأَ</span> and <span class=\"ar\">هَزِئَ</span> <i>He died</i> (K) <i>in his place,</i> or <i>on the spot;</i> i. e. <i>unexpectedly,</i> or <i>suddenly:</i> (Z:) improperly objected against by Ibn-Es-Sáïgh. ('Ináyeh, MF.)</p><p><b>4.</b> <b class=\"ar\">اهزأ</b> <i>He entered upon the time of severe cold.</i> (K.) See also <span class=\"ar\">اهرأ</span>, which is the word commonly known. (TA.) -b2- See 1. -A2- <span class=\"ar\">اهزأتْ بِهِ نَاقَتُهُ</span> <i>His she-camel hastened with him.</i> (K.)</p><p><b>5.</b> <b class=\"ar\">تَهَزَّاَ</b> see 1.</p><p><b>10.</b> <b class=\"ar\">إِسْتَهْزَاَ</b> see 1.</p><p><b class=\"ar\">هُزْأَةٌ</b> One <i>who is mocked at, scoffed at, laughed at, derided;</i> a <i>ridiculous</i> person. (S, K.)</p><p><b class=\"ar\">هُزَأَةٌ</b> One <i>who mocks at, scoffs at, laughs at, derides,</i> or <i>ridicules, others.</i> (S, K.)</p><p><b class=\"ar\">غَدَاةٌ هَازِئَةٌ</b> (tropical:) <i>A morning intensely cold:</i> as though mocking men when they shrug and shiver. (A.)</p><p><b class=\"ar\">مَفَازَةٌ هَازِئَةٌ بِالرَّكْبِ</b> , and with <span class=\"ar\">هُزَأَةٌ</span> for <span class=\"ar\">هازئة</span>, (tropical:) [<i>A desert that mocks the company of riders</i>]. (A.)</p>"},"هوي":{"mf":"الْهَوَى: ميل النفس إلى الشهوة. ويقال ذلك للنّفس المائلة إلى الشّهوة، وقيل: سمّي بذلك لأنّه يَهْوِي بصاحبه في الدّنيا إلى كلّ داهية، وفي الآخرة إلى الهَاوِيَةِ، وَالْهُوِيُّ: سقوط من علو إلى سفل، وقوله عزّ وجلّ: فَأُمُّهُ هاوِيَةٌ<br>[القارعة/ ٩] قيل: هو مثل قولهم: هَوَتْ أمّه أي: ثكلت. وقيل: معناه مقرّه النار، والْهَاوِيَةُ:<br>هي النار، وقيل: وَأَفْئِدَتُهُمْ هَواءٌ<br>[إبراهيم/ ٤٣] أي: خالية كقوله: وَأَصْبَحَ فُؤادُ أُمِّ مُوسى فارِغاً [القصص/ ١٠] وقد عظّم الله تعالى ذمّ اتّباع الهوى، فقال تعالى: أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلهَهُ هَواهُ<br>[الجاثية/ ٢٣]، وَلا تَتَّبِعِ الْهَوى<br>[ص/ ٢٦]، وَاتَّبَعَ هَواهُ [الأعراف/ ١٧٦] وقوله: وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ<br>[البقرة/ ١٢٠] فإنما قاله بلفظ الجمع تنبيها على أنّ لكلّ واحد هوى غير هوى الآخر، ثم هوى كلّ واحد لا يتناهى، فإذا اتّباع أهوائهم نهاية الضّلال والحيرة، وقال عزّ وجلّ:<br>وَلا تَتَّبِعْ أَهْواءَ الَّذِينَ لا يَعْلَمُونَ [الجاثية/ ١٨]، كَالَّذِي اسْتَهْوَتْهُ الشَّياطِينُ<br>[الأنعام/ ٧١] أي: حملته على اتّباع الهوى. وَلا تَتَّبِعُوا أَهْواءَ قَوْمٍ قَدْ ضَلُّوا [المائدة/ ٧٧]، قُلْ لا أَتَّبِعُ أَهْواءَكُمْ قَدْ ضَلَلْتُ [الأنعام/ ٥٦]، وَلا تَتَّبِعْ أَهْواءَهُمْ وَقُلْ آمَنْتُ بِما أَنْزَلَ اللَّهُ [الشورى/ ١٥]، وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَواهُ بِغَيْرِ هُدىً مِنَ اللَّهِ [القصص/ ٥٠] والهُوِيُّ:<br>ذهاب في انحدار، والْهَوِيُّ: ذهاب في ارتفاع، قال الشاعر:<br><span class=\"num\">٤٧٢-</span><br>يَهْوِي محارمها هويّ الأجدل<br><strong>«١»</strong> والْهَوَاءُ: ما بين الأرض والسماء، وقد حمل<br><br>على ذلك قوله: وَأَفْئِدَتُهُمْ هَواءٌ [إبراهيم/ ٤٣] إذ هي بمنزلة الهواء في الخلاء. ورأيتهم يتهاوون في المَهْوَاةِ أي: يتساقطون بعضهم في أثر بعض، وَأَهْواهُ، أي: رفعه في الهواء وأسقطه، قال تعالى: وَالْمُؤْتَفِكَةَ أَهْوى [النجم/ ٥٣].","mq":[["خلو وسقوط"],"الهاء والواو والياء: أصلٌ صحيح يدلُّ على خُلُوٍّ وسقوط.<br>أصله الهواء بين الأرض والسماء، سمِّى لخلوِّه. قالوا: وكلُّ خالٍ هواء. قال اللّه تعالى: ﴿وَأَفْئِدَتُهُمْ هَواءٌ﴾، أى خاليةٌ لا قَعِى شيئاً، ثمَّ قال زُهير:<br>كأَنَّ الرَّحْلَ منها فوقَ صَعلٍ … من الظِّلْمان جؤجؤهُ هواءُ (٣)<br>ويقال هَوَى الشّئُ يَه"],"ln":"<p><b>1.</b> <b class=\"ar\">هَوَى بِهِ</b> <i>He made it to fall down:</i> see an ex. in a verse of Ru-beh, cited voce <span class=\"ar\">رِياَغٌ</span>, in art. <span class=\"ar\">ريغ</span>. -b2- See 4. -b3- <span class=\"ar\">هَوَتْ أُذُنُهُ</span> <i>His ears heard a confused,</i> or <i>humming,</i> or <i>singing, sound.</i> (K.) -b4- <span class=\"ar\">هَوَتْ أُمُّهُ</span> is used to express wonder; like as when one says, <span class=\"ar\">قَاتَلَهُ ٱللّٰهُ مَا أَسْمَعَهُ</span>. (IB, in TA, art. <span class=\"ar\">ام</span>.)</p><p><b>4.</b> <b class=\"ar\">أَهْوَى إِلَى الشَّىْءِ بِيَدِهِ</b> <i>He extended,</i> or <i>stretched forth, his arm,</i> or <i>hand, to the thing to take it;</i> it being near: if it be distant, you say, <span class=\"ar\"> <span class=\"ar\">هَوَى</span>إِلَيْهِ</span>, without <span class=\"ar\">ا</span>. (Msb.) And <span class=\"ar\">أَهْوَى إِلى</span> <span class=\"ar\">سَيْفِهِ</span> <i>He reached his sword; took it with his hand,</i> or <i>with his extended hand;</i> or <i>took hold of it.</i> (Msb.) And <span class=\"ar\">أَهْوَيْتُ بِالشَّىْءِ</span> [in my copy of the Msb, erroneously, <span class=\"ar\">إِلَى الشَّىْءِ</span>] <i>I made a sign with the thing.</i> (As, S.)</p><p><b>5.</b> <b class=\"ar\">تَهَوَّهَ</b> : see <span class=\"ar\">آهَةٌ</span>, in art. <span class=\"ar\">اوه</span>.</p><p><b>7.</b> <b class=\"ar\">اِنْهَوَى</b> : see <span class=\"ar\">اِنْغَوَى</span>, in art. <span class=\"ar\">غو</span>.</p><p><b class=\"ar\">هَاهْ</b> and <span class=\"ar\">هَاهُ</span>: see <span class=\"ar\">آهِ</span>, in art. <span class=\"ar\">اوه</span>.</p><p><b class=\"ar\">الهَوَى</b> <i>Love,</i> and <i>attachment:</i> then, <i>inclination of the soul,</i> or <i>mind, to a thing:</i> then, <i>blameable inclination;</i> as when one says, <span class=\"ar\">اِتَّبَعَ هَوَاهُ</span> [<i>He followed his evil inclination</i>]; and <span class=\"ar\">هُوَ مِنْ أَهْلِ</span> <span class=\"ar\">الأَهْوَآءِ</span> [see below]. (Msb.) See also <span class=\"ar\">حُبٌّ</span>. -b2- <span class=\"ar\">هَوًى</span> Also signifies <i>Beloved</i> [or <i>an object of love</i>]. (K, Ham, p. 546.) [Being originally an inf. n., it may be used alike as sing. and pl. See an ex. in a verse cited in the first paragraph of art. <span class=\"ar\">زين</span>: and see an ex. voce <span class=\"ar\">شَكْلٌ</span>. -b3- <span class=\"ar\">الهَوَى</span> <i>The inclination of the soul to that in which the animal appetites take delight, without any lawful invitation thereto;</i> (KT;) [<i>natural desire:</i>] <i>love, and desire;</i> generally, <i>such as is not praiseworthy:</i> (Mgh:) I render it, <i>love,</i> or <i>desirous love.</i> -b4- [Its pl.] <span class=\"ar\">أَهْوَآءٌ</span> also signifies <i>Opinions declining,</i> or <i>swerving, from the right way,</i> or <i>from the truth.</i> (Bd, ii. 114.) [Hence,] <span class=\"ar\">أَهْلُ الأَهْوَآءِ</span> [<i>The people of erroneous opinions</i>]. (T, in art. <span class=\"ar\">سمع</span>; &amp;c.)</p><p><b class=\"ar\">هُوَّةٌ</b> <i>A deep hollow in the ground:</i> (S, JK, M, Msb, K:) or <i>a hollow,</i> or <i>cavity, in the ground; a pit:</i> (Msb:) or <i>a descent in the ground:</i> (K:) or <i>a deep hollow, cavity, or pit;</i> as also <span class=\"ar\"> <span class=\"ar\">مَهْوَاةٌ</span></span>: or <i>a low,</i> or <i>depressed, place in the ground.</i> (TA.) -b2- <span class=\"ar\">إِجْعَلِ الأَمْرَ هُوَّةً وَاحِدَةٌ</span> <i>Make thou the affair,</i> or <i>case,</i> [<i>uniform,</i> or] <i>one uniform thing.</i> (Fr in TA, in art. <span class=\"ar\">بأج</span>.)</p><p><b class=\"ar\">هَوَآءٌ</b> <i>A vacancy; a vacuity; a vacant,</i> or <i>an empty, space.</i> (Mgh.) -b2- <i>A vacant,</i> or <i>an empty, thing.</i> (Msb.)</p><p><b class=\"ar\">هَوِىٌّ</b> and <span class=\"ar\">هُوِىٌّ</span>: see 4, (last sentence), in art. <span class=\"ar\">سلم</span>.</p><p><b class=\"ar\">هَاوَنٌ</b> , said to be thus, with fet-h to the <span class=\"ar\">و</span>, originally <span class=\"ar\">هَاوُونٌ</span>, [<i>A mortar;</i>] the <i>thing in which one pounds,</i> or <i>bruises:</i> pl. <span class=\"ar\">هَوَاوِينُ</span>. (Msb.)</p><p><b class=\"ar\">هَاوِيَةٌ</b> <i>An abyss; a depth,</i> or <i>deep place, of which the bottom cannot be reached.</i> (JK, TA.)</p><p><b class=\"ar\">مَهْوَى الرَّكِيَّةِ</b> [<i>The cavity of the well</i>]. (K, voce <span class=\"ar\">إِزَآءٌ</span>.) -b2- See <span class=\"ar\">مَهْوَاةٌ</span>.</p><p><b class=\"ar\">مَهْوَاةٌ</b> : see <span class=\"ar\">هُوَّةٌ</span>. -b2- The <i>space between two mountains;</i> (S, Msb;) and <i>the like;</i> as also <span class=\"ar\"> <span class=\"ar\">مَهْوًى</span></span>: (S:) <i>a pit,</i> or <i>hollow, dug,</i> or <i>excavated.</i> (Msb.)</p><p><b class=\"ar\">مُهَيَّأٌ</b> <i>i. q.</i> <span class=\"ar\">زَُمَاوَرْدٌ</span>. (MF, art. <span class=\"ar\">ورد</span>.)</p>"},"هجر":{"mf":"الهَجْرُ والهِجْرَان: مفارقة الإنسان غيره، إمّا بالبدن، أو باللّسان، أو بالقلب. قال تعالى:<br>وَاهْجُرُوهُنَّ فِي الْمَضاجِعِ<br>[النساء/ ٣٤] كناية عن عدم قربهنّ، وقوله تعالى: إِنَّ قَوْمِي اتَّخَذُوا هذَا الْقُرْآنَ مَهْجُوراً<br>[الفرقان/ ٣٠] فهذا هَجْر بالقلب، أو بالقلب واللّسان. وقوله:<br>وَاهْجُرْهُمْ هَجْراً جَمِيلًا [المزمل/ ١٠] يحتمل الثلاثة، ومدعوّ إلى أن يتحرّى أيّ الثلاثة إن أمكنه مع تحرّي المجاملة، وكذا قوله تعالى:<br>وَاهْجُرْنِي مَلِيًّا [مريم/ ٤٦]، وقوله تعالى:<br>وَالرُّجْزَ فَاهْجُرْ [المدثر/ ٥]، فحثّ على المفارقة بالوجوه كلّها. والمُهاجرَةُ في الأصل:<br>مصارمة الغير ومتاركته، من قوله عزّ وجلّ:<br>وَالَّذِينَ آمَنُوا وَهاجَرُوا وَجاهَدُوا<br>[الأنفال/ ٧٤]، وقوله: لِلْفُقَراءِ الْمُهاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيارِهِمْ وَأَمْوالِهِمْ<br><strong>[الحشر/ ٨]، وقوله:</strong><br>وَمَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهاجِراً إِلَى اللَّهِ [النساء/ ١٠٠]، فَلا تَتَّخِذُوا مِنْهُمْ أَوْلِياءَ حَتَّى يُهاجِرُوا فِي سَبِيلِ اللَّهِ [النساء/ ٨٩] فالظاهر منه الخروج من دار الكفر إلى دار الإيمان كمن هاجر من مكّة إلى المدينة، وقيل: مقتضى ذلك هجران الشّهوات والأخلاق الذّميمة والخطايا وتركها ورفضها، وقوله: إِنِّي مُهاجِرٌ إِلى رَبِّي [العنكبوت/ ٢٦] أي: تارك لقومي وذاهب إليه. وقوله: أَلَمْ تَكُنْ أَرْضُ اللَّهِ واسِعَةً فَتُهاجِرُوا فِيها [النساء/ ٩٧]، وكذا المجاهدة تقتضي مع العدى مجاهدة النّفس كما روي في الخبر: <strong>«رجعتم من الجهاد الأصغر إلى الجهاد الأكبر»</strong> <strong>«١»</strong>، وهو مجاهدة النّفس. وروي:<br>(هاجروا ولا تهجّروا) <strong>«٢»</strong> أي: كونوا من المهاجرين، ولا تتشبّهوا بهم في القول دون الفعل، والهُجْرُ: الكلام القبيح المهجور لقبحه.<br>وفي الحديث: <strong>«ولا تقولوا هُجْراً»</strong> <strong>«٣»</strong> وأَهْجَرَ فلان: إذا أتى بهجر من الكلام عن قصد،<br><br>وهَجَرَ المريض: إذا أتى ذلك من غير قصد، وقرئ: مُسْتَكْبِرِينَ بِهِ سامِراً تَهْجُرُونَ<br>[المؤمنون/ ٦٧] <strong>«١»</strong>، وقد يشبّه المبالغ في الهجر بالمُهْجِر، فيقال: أَهْجَرَ: إذا قصد ذلك، قال الشاعر:<br><span class=\"num\">٤٥٦-</span><table class=\"poem\"><tr><td>كما جدة الأعراق قال ابن ضرّة </td><td> عليها كلاما جار فيه وأهجرا</td></tr></table><strong>«٢»</strong> ورماه بهاجرات فمه أي: فضائح كلامه، وقوله: فلان هِجِّيراه كذا: إذا أولع بذكره، وهذي به هذيان المريض المهجر، ولا يكاد يستعمل الهِجِّير إلّا في العادة الذّميمة اللهمّ إلّا أن يستعمله في ضدّه من لا يراعي مورد هذه الكلمة عن العرب. والهَجِيرُ والهاجرة: الساعة التي يمتنع فيها من السّير كالحرّ، كأنها هجرت النّاس وهجرت لذلك، والهِجَار: حبل يشدّ به الفحل، فيصير سببا لهجرانه الإبل، وجعل على بناء العقال والزّمام، وفحل مهجور، أي: مشدود به، وهِجَار القوس: وترها، وذلك تشبيه بهجار الفحل.","mq":[["علي قطيعة وقطع","علي شد (٣) شي وربطه"],"الهاء والجيم * والراء أصلانِ يدلُّ أحدهما على قطيعةٍ وقَطْع، والآخر على شَدِّ (٣) شئٍ ورَبْطِه.<br>فالأوَّل الهَجْر: ضِدُّ الوصل. وكذلك الهِجْران. وهاجَرَ القومُ مِنْ دارٍ إلى دارٍ: تَرَكُوا الأولى للثانية، كما فَعَل المهاجِرُون حِين هاجروا (٤) من مكة إلى المدينة. وتهجَّر الرّجلُ وتَمَهْجَر: تشبَّه بال"],"ln":"<p><b>1.</b> <b class=\"ar\">هَجَرَهُ</b> , (S, A, &amp;c.,) aor. <b class=\"ar\">هَجُرَ</b> , (Msb,) inf. n. <span class=\"ar\">هَجْرٌ</span> (S, A, Mgh, Msb, K) and <span class=\"ar\">هِجْرَانٌ</span>, (S, A, Mgh, K,) or the latter is a simple subst., (Msb,) <i>He cut him off from friendly</i> or <i>loving, communion</i> or <i>intercourse; contr. of</i> <span class=\"ar\">وَصَلَهُ</span>: (S, Mgh:) <i>he forsook,</i> or <i>abandoned, him;</i> syn. <span class=\"ar\">قَطَعَهُ</span>: (Msb, TA:) <i>he cut him;</i> meaning, <i>he ceased to speak to him,</i> or <i>to associate with him;</i> syn. <span class=\"ar\">صَرَمَهُ</span>, (A, Mgh, K,) and <span class=\"ar\">قَطَعَ كَلَامَهُ</span>. (Mgh.) It is said in the Kur, [iv. 38,] <span class=\"ar\">وَٱهْجُرُوهُنَّ فِى المَضَاجِعٍ</span>, i. e., [<i>And cut ye them off from loving intercourse</i>] <i>in the sleeping-places,</i> in order to obtain their obedience. (Msb.) See also 3. -b2- <i>He left it; forsook it; relinquished it; abandoned it; deserted it; quitted it: abstained from it: neglected it: shunned</i> or <i>avoided it; was averse from it:</i> syn. <span class=\"ar\">تَرَكَهُ</span>; (A, Msb, K, TA;) and <span class=\"ar\">رَفَضَهُ</span>; (Msb;) and <span class=\"ar\">فَارَقَهُ</span>: (B:) and <span class=\"ar\">أَغْفَلَهُ</span>: and <span class=\"ar\">أَعْرَضَ عَنْهُ</span>: (TA:) namely, a thing to which it was necessary for him to pay frequent attention: (Lth, TA:) as also <span class=\"ar\"> <span class=\"ar\">أَهْجَرَهُ</span></span>; (K;) which latter is of the dial. of Hudheyl: (TA:) and <span class=\"ar\">هُجِرَ</span> <i>he,</i> or <i>it, was left;</i> &amp;c. (IKtt.) <span class=\"ar\">هِجْرَانٌ</span> may be with the body and with the tongue and with the heart or mind: it is with the first in the passage of the Kur cited above: it may be with any of the three in the Kur, [lxxiii. 10,] where it is said, <span class=\"ar\">وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا</span> [<i>And avoid thou them,</i> i. e., avoid the associating with them in person, or speaking to them, or entertaining friendship for them in thy heart, <i>with an avoiding of a becoming kind</i>]: and it is with all the three in the following ex. in the Kur, [lxxiv. 5,] <span class=\"ar\">وَٱلرِّجْزَ فَٱهْجُرْ</span> [<i>And idolatry avoid thou</i>]. (B.) You say also, <span class=\"ar\">هَجَرَ الشِّرْكَ</span>, inf. n. <span class=\"ar\">هَجْرٌ</span> and <span class=\"ar\">هِجْرَانٌ</span>, [<i>He abstained from,</i> or <i>avoided, polytheism,</i> or <i>the associating of others with God,</i>] <span class=\"ar\">هِجْرَةً حَسَنَةً</span> [<i>with a good manner of abstaining,</i> or <i>avoiding</i>]. (Lh, K.) And it is said in a trad., <span class=\"ar\">وَلَا يَسْمَعُونَ القُرْآنَ إِلَّا هَجْرًا</span>, meaning, [<i>And they hear not the Kur-án save</i>] <i>with neglect of it, and aversion from it:</i> the reading <span class=\"ar\">الّا هُجْرًا</span>, mentioned by IKt, and his explanation of it, <i>save with foul speech,</i> are both said by El-Khattábee to be erroneous. (TA.) -b3- <span class=\"ar\">هَجَرَ</span>, [aor. <b class=\"ar\">هَجُرَ</b> ,] inf. n. <span class=\"ar\">هَجْرٌ</span>, <i>He</i> (a man) <i>went, removed, retired,</i> or <i>withdrew himself, to a distance, far away,</i> or <i>far off.</i> (TA.) -b4- <span class=\"ar\">هَجَرَ فِى الصَّوْمِ</span>, (K,) aor. <b class=\"ar\">هَجُرَ</b> , inf. n. <span class=\"ar\">هِجْرَانٌ</span>, (TA,) <i>He abstained from sexual intercourse in fasting.</i> (K.) -A2- <span class=\"ar\">هَجَرَ</span>, (Lth, Fr, S, A, K, &amp;c.,) or <span class=\"ar\">هَجَرَ فِى كَلَامِهِ</span>, (Msb,) aor. <b class=\"ar\">هَجُرَ</b> , (Lth, Fr, S, &amp;c.,) inf. n. <span class=\"ar\">هَجْرٌ</span>, (Lth, S, A, Mgh, Msb,) with fet-h, (Mgh,) or <span class=\"ar\">هُجْرٌ</span>, with damm, (K,) and <span class=\"ar\">هِجِّيرَى</span>, (A, K,) or this is a simple subst., (Lth,) and <span class=\"ar\">إِهْجِيرَى</span>, (K,) [or this and that which immediately precedes it are intensive inf. ns.,] <i>He</i> (a sick man, Lth, S, Msb, K, or one having the disease termed <span class=\"ar\">بِرْسَام</span>, A'Obeyd, A, or having a fever, A'Obeyd, and one sleeping. Fr, K) <i>talked nonsense; talked irrationally</i> or <i>foolishly</i> or <i>deliriously,</i> (Lth, Fr, S, A, Mgh, Msb, K,) <i>and confusedly:</i> (Msb:) or <span class=\"ar\">هِجِّيرَى</span> signifies the <i>talking much, and saying what is evil.</i> (Sb.) In the Kur, [xxiii. 69,] instead of <span class=\"ar\">تَهْجُرُونَ</span>, in the phrase <span class=\"ar\">سَامِرًا تَهْجُرُونَ</span>, [<i>Holding discourse by night, talking irrationally</i> or <i>foolishly,</i>] I'Ab reads <span class=\"ar\">تُهْجِرُونَ</span> from <span class=\"ar\"> <span class=\"ar\">أَهْجَرَ</span></span>, [q. v.,] from <span class=\"ar\">الهُجْرُ</span>. (TA.) -b2- See also 4. -b3- <span class=\"ar\">هَجَرَ بِهِ</span>, aor. <b class=\"ar\">هَجُرَ</b> , inf. n. <span class=\"ar\">هَجْرٌ</span>, <i>He dreamed of him</i> or <i>it;</i> or <i>saw him</i> or <i>it in sleep:</i> or <i>he did so and talked foolishly</i> or <i>deliriously.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">هجّر</b> , (Lth, A, K, &amp;c.,) inf. n. <span class=\"ar\">تَهْجِيرٌ</span>, (S, Msb, K,) <i>He journeyed in the time called the</i> <span class=\"ar\">هَاجِرَة</span>; (Lth, S, A, Mgh, K;) as also <span class=\"ar\"> <span class=\"ar\">تهجّر</span></span>; (IAar, S, A, K;) and <span class=\"ar\"> <span class=\"ar\">اهجر</span></span>: (K:) or <i>he went forth in that time:</i> (Az, TA:) or <i>he was</i> (<span class=\"ar\">صَارَ</span>) <i>in that time:</i> (Msb: [but in my copy of that work, <span class=\"ar\">صار</span> is perhaps a mistake for <span class=\"ar\">سَارَ</span>:]) or <span class=\"ar\"> <span class=\"ar\">اهجر</span></span> has this last signification; (Lth, TA;) or signifies <i>he entered upon that time;</i> like <span class=\"ar\">اظهر</span> (A.) -b2- <i>It</i> (the day) <i>attained to the time called he</i> <span class=\"ar\">هَاجِرَة</span>. (S, TA.)</p><p><b>3.</b> <b class=\"ar\">هاجرهُ</b> , (A,) inf. n. <span class=\"ar\">مُهَاجَرَةٌ</span>; (B;) and <span class=\"ar\"> <span class=\"ar\">اهتجرهُ</span></span>; (A;) <i>He cut him off from friendly,</i> or <i>loving, communion</i> or <i>intercourse, being so cut off by him;</i> or <i>he cut him,</i> or <i>ceased to speak to him, being in like manner cut by him:</i> and <i>he forsook,</i> or <i>abandoned, him, being forsaken,</i> or <i>abandoned, by him:</i> (A, * B:) this is the primary signification of the former. (B.) -b2- <span class=\"ar\">هاجر</span>, (T, A, Msb, K,) inf. n. <span class=\"ar\">مُهَاجَرَةٌ</span> (T, S, A, Msb) and <span class=\"ar\">هِجْرَةٌ</span>, (A,) or the latter is a simple subst., (Mgh, Msb,) <i>He</i> (an inhabitant of the desert) <i>went forth from his desert to the cities</i> or <i>towns:</i> this is the primary acceptation, with the Arabs, of the verb [when intrans.]: also, <i>he</i> (any one) <i>left his place of abode, emigrating to another people:</i> (Az:) <i>he departed,</i> or <i>went forth, from one land to another,</i> (S, K,) or <i>from one country,</i> or <i>district,</i> or <i>town, to another:</i> (Msb:) and, as used in the Kur, ii. 215, [and in many other instances in the same and other books,] <i>he went forth</i> [or <i>emigrated</i>] <i>from the territory of the unbelievers to the territory of the believers</i> [or <i>to any place of safety</i> or <i>refuge on account of religious persecution, &amp;c.</i>] (B.) See an ex. voce <span class=\"ar\">تَهَجَّرَ</span>; and see <span class=\"ar\">هِجْرَةٌ</span>.</p><p><b>4.</b> <b class=\"ar\">اهجرهُ</b> : see <span class=\"ar\">هَجَرَهُ</span>. -A2- <span class=\"ar\">اهجر فِى مَنْطِقِهِ</span>, (S, * Mgh, Msb, K,) or simply <span class=\"ar\">اهجر</span>, (A,) inf. n. <span class=\"ar\">إِهْجَارٌ</span> (S, K) and <span class=\"ar\">هُجْرٌ</span>, (Lh, Kr, K,) or the latter is, correctly speaking, a simple subst., (TA,) <i>He spoke,</i> or <i>uttered, foul, evil, bad, abominable,</i> or <i>unseemly, language:</i> (S, A, Mgh, K:) or <i>he did so much; beyond what he used to do before;</i> as also <span class=\"ar\"> <span class=\"ar\">هَجَرَ</span></span>, aor. <b class=\"ar\">هَجُرَ</b> , (Msb,) inf. n. <span class=\"ar\">هَجْرٌ</span>: (L, TA:) and in like manner, <i>he talked much of that which was not fit, suitable, meet,</i> or <i>proper.</i> (S.) -b2- <span class=\"ar\">اهجر بِهِ</span> <i>He mocked,</i> or <i>scoffed,</i> or <i>laughed at him, derided him,</i> or <i>ridiculed him, and said respecting him what was foul, evil, bad, abominable,</i> or <i>unseemly.</i> (Msb, K.) -A3- See also 2, in two places.</p><p><b>5.</b> <b class=\"ar\">تهجّر</b> <i>He affected to be like the</i> <span class=\"ar\">مُهَاجِرُون</span> [or <i>emigrants from the territory of the unbelievers to that of the believers</i>]. (A'Obeyd, S, A, K.) Hence the trad., <span class=\"ar\"> <span class=\"ar\">هَاجِرُوا</span>وَلَا تَهَجَّرُوا</span>, (A'Obeyd, S, A,) i. e., <i>Perform ye the</i> <span class=\"ar\">هِجْرَة</span> with sincerity towards God, <i>and affect not to be like those who do so without your being really such as do so:</i> said by 'Omar. (A'Obeyd, TA.) -A2- See also 2.</p><p><b>6.</b> <b class=\"ar\">تهاجروا</b> [<i>They cut one another off from friendly</i> or <i>loving communion</i> or <i>intercourse;</i> or <i>they cut,</i> or <i>ceased to speak to, one another: they forsook,</i> or <i>abandoned, one another:</i> as also <span class=\"ar\"> <span class=\"ar\">اهتجروا</span></span>] (A.) You say also <span class=\"ar\">هُمَا يَتَهَاجَرَانِ</span>, and <span class=\"ar\"> <span class=\"ar\">يَهْتَجِرَانِ</span></span>, i. e., <span class=\"ar\">يَتَقَاطِعَانِ</span> [<i>They two cut each other off &amp;c.</i>]: (K:) <span class=\"ar\">تَهَاجُرٌ</span> is <i>syn. with</i> <span class=\"ar\">تَقَاطُعُ</span>. (S.)</p><p><b>8.</b> <b class=\"ar\">إِهْتَجَرَ</b> see 3 and 6; the latter in two places. -b2- [<i>He journeyed in the time of the</i> <span class=\"ar\">حَاجِرَة</span>: see 8 in art. <span class=\"ar\">عشو</span>.]</p><p><b class=\"ar\">هَجْرٌ</b> : see <span class=\"ar\">هُجْرٌ</span>: -A2- and see also <span class=\"ar\">هَاجِرَةٌ</span>.</p><p><b class=\"ar\">هُجْرٌ</b> , a subst. from <span class=\"ar\">أَهْجَرَ</span>; (S, Mgh;) or from its syn. <span class=\"ar\">هَجَرَ</span>; (Msb;) <i>Foul, evil, bad, abominable,</i> or <i>unseemly, language,</i> or <i>talk;</i> (As, Ks, T, S, A, Mgh, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">هَجْرَآءُ</span></span>; (Sgh, K;) and <span class=\"ar\"> <span class=\"ar\">هَاجِرَةٌ</span></span>; of which last the pl. is <span class=\"ar\">هَوَاجِرُ</span>, incorrectly said by IJ to be an irreg. pl. of <span class=\"ar\">هُجْرٌ</span>; or <span class=\"ar\"> <span class=\"ar\">هَاجِرَةٌ</span></span> may be an inf. n., like <span class=\"ar\">كَاذِبَةٌ</span> &amp;c. (IB.) You say, <span class=\"ar\">قَالَ هُجْرًا وَبُجْرًا</span>, and <span class=\"ar\"> <span class=\"ar\">هَجْرًا</span> وَبَجْرًا</span>, [<i>He said</i>] <i>a foul</i> [<i>and a wonderful</i>] <i>thing:</i> <span class=\"ar\"> <span class=\"ar\">هَجْرٌ</span></span> is an inf. n., and <span class=\"ar\">هُجْرٌ</span> is a simple subst. (L, TA.) And <span class=\"ar\">رَمَاهُ <span class=\"ar\">بِٱلْهَاجِرَاتِ</span></span> <i>He assailed him with foul words:</i> <span class=\"ar\">هاجرات</span> being a word of the same class as <span class=\"ar\">لَابِنْ</span> and <span class=\"ar\">تَامِرٌ</span>. (A, Msb.) And <span class=\"ar\">رَمَاهُ <span class=\"ar\">بِهَاجِرَاتٍ</span></span>, and <span class=\"ar\"> <span class=\"ar\">بِمُهْجِرَاتٍ</span></span>, (S, K,) or <span class=\"ar\">بِٱلْهَاجِرَاتِ</span>, (A,) and <span class=\"ar\">بِٱلْمُهْجِرَاتِ</span>, (A, Msb,) <i>He accused him of evil things that exposed him to disgrace:</i> (S, K:) or <i>of foul,</i> or <i>evil, actions.</i> (A, Msb.) And <span class=\"ar\">تَكَلَّمَ <span class=\"ar\">بِٱلْمَهَاجِرِ</span></span> (in the CK <span class=\"ar\">بالمُهاجِرِ</span>) <i>He spoke foul,</i> or <i>evil, language.</i> (L, K.)</p><p><b class=\"ar\">هِجِرٌّ</b> : see <span class=\"ar\">هِجْرَةٌ</span>.</p><p><b class=\"ar\">هُجْرَةٌ</b> : see <span class=\"ar\">هِجْرَةٌ</span>.</p><p><b class=\"ar\">هِجْرَةٌ</b> , a subst. from <span class=\"ar\">هَجَرَهُ</span>, (S, K,) as also <span class=\"ar\"> <span class=\"ar\">هِجْرَانٌ</span></span>, (Msb,) signifying The <i>cutting another off from friendly</i> or <i>loving communion</i> or <i>intercourse:</i> (S:) <i>cutting one;</i> or <i>ceasing to speak to him:</i> (K:) <i>forsaking, abandoning, deserting,</i> or <i>shunning</i> or <i>avoiding, one.</i> (Msb.) It is said in a trad., <span class=\"ar\">لَا هِجْرَةَ بَعْدَ ثَلَاثٍ</span> [<i>There shall be no cutting off from friendly communion after three</i> nights with their days,]: the meaning is, <span class=\"ar\">هَجْرٌ</span> as contr. of <span class=\"ar\">وَصْلٌ</span>; i. e., such anger as exists between Muslims, or a failing, or falling short, with respect to the duties of society, exclusively of what relates to religion: but the <span class=\"ar\">هِجْرَة</span> of those who follow their own natural desires [in matters of religion], and of innovators [in religion], should continue even as long as they do not repent, and return to the truth. (TA.) -b2- [Also, <i>A mode,</i> or <i>manner, of cutting another off from friendly</i> or <i>loving communion</i> or <i>intercourse:</i> &amp;c. See 1, where an ex. occurs.] -b3- Also, <i>A removal from the desert to the towns</i> or <i>villages:</i> this was its [primary] acceptation with the Arabs: and the <i>forsaking of his country,</i> or <i>district,</i> or <i>the like, by an inhabitant of the desert,</i> or <i>by an inhabitant of a town,</i> or <i>village,</i> or <i>cultivated district, and taking up his abode in another country</i> or <i>district,</i> or <i>the like, an emigration;</i> (TA;) the <i>forsaking of one's home and removing to another place;</i> (Mgh;) the <i>forsaking of a country,</i> or <i>district,</i> or <i>the like, and removing to another;</i> (Msb;) the <i>going forth from one land to another;</i> as also <span class=\"ar\"> <span class=\"ar\">هُجْرَةٌ</span></span>. (K:) [and <i>an emigration from the territory of the unbelievers to the territory of the believers,</i> or <i>to any place of safety</i> or <i>refuge on account of religious persecution &amp;c.:</i> see 3, last signification:] a subst. from <span class=\"ar\">هَاجَرَ</span>. (Msb, TA.) -b4- [<span class=\"ar\">الهِجْرَةٌ</span>, peculiarly, <i>The emigration,</i> or <i>flight,</i> (for it was really a flight,) of Mohammad, from Mekkeh to Yethrib, which latter was afterwards called El-Medeeneh. Hence, <span class=\"ar\">تَأْرِيخُ الهِجْرَةِ</span> <i>The era of the Hijreh,</i> or <i>Flight.</i> The epoch of this era is not the date of the Flight itself, as some have imagined, (for this took place on an uncertain day, most probably the first or second, of the third lunar month of the Arabian year,) but is the first day of the Arabian year in which the Flight happened: and as I believe that all European writers who have attempted to fix it, prior to M. Caussin de Perceval, have erred respecting it, the true date, as shown by him, (see his “ Essai sur l'Histoire des Arabes, ” &amp;c., in the places referred to in the index to that work,) I think it important here to mention. The first year of the Flight was the two hundred and eleventh year of a period during which the Arabs made use of a defective luni-solar reckoning, making every third year to consist of thirteen lunar months; the others consisting of twelve such months. This mode of reckoning was abolished by Mohammad in the twelfth month of the tenth year of the Flight, at the time of the pilgrimage; whence it appears that the first year of the Flight commenced, most probably, on Monday, the nineteenth of April, A. D. 622; or perhaps on the eighteenth; for the actual appearance of the new moon properly marked its commencement, and, as the new moon happened about sunset on the sixteenth, it may perhaps have been seen on the eve of the eighteenth. According to M. Caussin de Perceval, the first ten years of the Flight commenced at the following periods. 1st. [Mon.] Apr. 19, 622 2nd. [Sat.] May 7, 623 3rd. [Th.] Apr. 26, 624 4th. [Mon.] Apr. 15, 625 5th. [Sat.] May. 3, 626 6th. [Th.] Apr. 23, 627 7th. [Tu.] Apr. 12, 628 8th. [Mon.] May. 1, 629 9th. [Fri.] Apr. 20, 630 10th. [Tu.] Apr. 9, 631 Thus it appears that the first and fourth and seventh years were of thirteen lunar months each; and the seventh was the last year that was thus augmented: therefore, with the eighth year commenced the reckoning by common lunar years; and from this point we may use the tables which have often been published for finding the periods of commencement of years of the Flight. We must not, however, rely upon the exact accuracy of these tables: for the commencement of the month was generally determined by actual observation of the new moon; not by calculation; and we often find that a year was commenced, according as the place of observation was low or high, or to the east or west of the place to which the calculation is adapted, or according as the sky was obscure or clear, a day later or earlier than that which is indicated in the tables; and in some cases, even two days later. The twelfth day of the third month of the first year of the Flight, the day of Mohammad's arrival at Kubà, was Monday: therefore the first day of the year was most probably the nineteenth of April, as two months of thirty days each, or twenty-nine days each, seldom occur together. But the tenth day of the first month of the sixty-first year, the day on which El-Hoseyn was slain at Kerbelà, was Friday: therefore the first day of that year, at that place, must have been Wednesday, the third of October, A. D. 680; not the first of October, as in most of the published tables above mentioned. (For the principal divisions of the Arabian year when the luni-solar reckoning was instituted, see <span class=\"ar\">زَمَنٌ</span>)]. <span class=\"ar\">الهِجْرَتَانِ</span> means [<i>The two emigrations,</i> or <i>flights;</i> namely,] <i>the</i> <span class=\"ar\">هِجْرَة</span> <i>to Abyssinia and the</i> <span class=\"ar\">هِجْرَة</span> <i>to El-Medeeneh.</i> (S, K.) And <span class=\"ar\">ذُو الهِجْرَتَيْنِ</span> <i>He</i> (of the <span class=\"ar\">صَحَابَة</span> [or Companions of Mohammad] TA) <i>who emigrated,</i> or <i>who has emigrated, to Abyssinia and to El-Medeeneh.</i> (K.)</p><p><b class=\"ar\">هَجْرَآءُ</b> : see <span class=\"ar\">هُجْرٌ</span>.</p><p><b class=\"ar\">هِجْرَانٌ</b> : see <span class=\"ar\">هِجْرَةٌ</span>.</p><p><b class=\"ar\">هِجْرِيَّا</b> : see <span class=\"ar\">هِجِّيرٌ</span>.</p><p><b class=\"ar\">هَجِيرٌ</b> <i>Left; forsaken; relinquished; abandoned; deserted; quitted: abstained from: neglected: shunned</i> or <i>avoided.</i> (TA.) -A2- See also <span class=\"ar\">هَاجِرَةٌ</span>, in three places.</p><p><b class=\"ar\">هَجِيرَةٌ</b> : see <span class=\"ar\">هَاجِرَةٌ</span>.</p><p><b class=\"ar\">هِجِّيرٌ</b> <i>Custom; manner; habit; wont: state; condition; case;</i> syn. <span class=\"ar\">دَأْبٌ</span>, (T, S, A, K,) and <span class=\"ar\">عَادَةٌ</span>, (S, TA,) and <span class=\"ar\">دَيْدَنٌ</span>, (TA,) and <span class=\"ar\">شَأْنٌ</span>: (T, A, K:) and the <i>speech,</i> or <i>language,</i> of a man; [or <i>what one is accustomed to say;</i>] syn. <span class=\"ar\">كَلَامٌ</span>: (T, TA:) as also <span class=\"ar\"> <span class=\"ar\">هِجِّيرَى</span></span>, (T, S, A, K,) and <span class=\"ar\"> <span class=\"ar\">إِهْجِيرَى</span></span>, (S, K,) and <span class=\"ar\"> <span class=\"ar\">إِهْجِيرَآءُ</span></span>, and <span class=\"ar\"> <span class=\"ar\">أُهْجُورَةٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">هِجْرِيَّا</span></span>, (K,) and <span class=\"ar\">إِجْرِيَّا</span>, and <span class=\"ar\">إِجْرِيَّآءُ</span>. (S.) You say, <span class=\"ar\">مَا زَالَ ذٰلِكَ هِجِّيرَهُ</span>, (A, K, * TA [in the CK, <span class=\"ar\">هٰذَا هِجِّيرَتُهُ</span>,]) and <span class=\"ar\">هِجِّيرَاهُ</span>, (S, A, K,) and <span class=\"ar\">إِهْجِيرَاهُ</span>, &amp;c., (K,) <i>That ceased not to be his custom,</i> &amp;c. (S, A, K. *) And <span class=\"ar\">مَا لَهُ <span class=\"ar\">هِجِّيرَى</span> غَيْرُهَا</span> <i>He has no custom, &amp;c., other than it.</i> (TA, from a trad.)</p><p><b class=\"ar\">هِجِّيرَى</b> : see <span class=\"ar\">هِجِّيرٌ</span>.</p><p><b class=\"ar\">هَاجِرٌ</b> , act. part. n. of 1, q. v. -b2- <i>Talking nonsense; talking foolishly</i> or <i>deliriously.</i> (S, TA.) See 1, last signification but one.</p><p><b class=\"ar\">هَاجِرَةٌ</b> : see <span class=\"ar\">هُجْرٌ</span>, in four places. -A2- <span class=\"ar\">الهَاجِرَةُ</span>, (S, A, Mgh, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">هَجِيرٌ</span></span>, (S, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">هَجِيرَةٌ</span></span>, (A, K,) and <span class=\"ar\"> <span class=\"ar\">هَجْرٌ</span></span>, (S, K,) <i>Midday when the heat is vehement:</i> (S:) or <i>midday in summer,</i> or <i>in the hot season:</i> (Mgh, Msb:) or the <i>period from a little before noon to a little after noon in summer,</i> or <i>in the hot season, only:</i> (En-Nadr, ISk:) or <i>from the time when the sun declines from the meridian:</i> (Aboo-Sa'eed:) or <i>midday, when the sun declines from the meridian, at the</i> <span class=\"ar\">ظُهْر</span>: or <i>from its declining until the</i> <span class=\"ar\">عَصْر</span>: because people [then] shelter themselves in their tents or houses; as though they forsook one another (<span class=\"ar\">تَهَاجَرُوا</span>): (K:) or <i>the vehemence of the heat</i> (K, TA) <i>therein:</i> (TA:) and <span class=\"ar\">الهُوَيْجِرَةُ</span> [dim. of <span class=\"ar\">الهاجرة</span>] <i>the period a little after the</i> <span class=\"ar\">هَاجِرَة</span>: (EsSukkaree:) [pl. of the first, <span class=\"ar\">هَوَاجِرُ</span>.] You say, <span class=\"ar\">طَبَخَتْهُ الهَوَاجِرُ</span> [<i>The vehement midday heats affected him with a hot,</i> or <i>burning, fever</i>]. (A.) And <span class=\"ar\">صَلَاةُ <span class=\"ar\">الهَجِيرِ</span></span> <i>The prayer of noon;</i> as also <span class=\"ar\">الهَجِيرُ</span>, elliptically. (TA.) See also <span class=\"ar\">ظَهِيرَةٌ</span>.</p><p><b class=\"ar\">أُهْجُورَةٌ</b> : see <span class=\"ar\">هِجِّيرٌ</span>.</p><p><b class=\"ar\">إِهْجِيرَى</b> : see <span class=\"ar\">هِجِّيرٌ</span>.</p><p><b class=\"ar\">إِهجِيرَآءُ</b> : see <span class=\"ar\">هِجِّيرٌ</span>.</p><p><b class=\"ar\">أَتَيْنَا أَهْلَنَا مُهْجِرِينَ</b> <i>We came to our family in the time of the</i> <span class=\"ar\">هَاجِرَة</span>. (S.) -b2- <span class=\"ar\">مُهْجِرَاتٌ</span> and <span class=\"ar\">مَهَاجِرُ</span>: see <span class=\"ar\">هُجْرٌ</span>.</p><p><b class=\"ar\">هَلْ مُهَجِّرٌ كَمَنْ قَالَ</b> <i>Is one who journeys in the</i> <span class=\"ar\">هَاجِرَة</span> <i>like him who stays during the time of midday?</i> (TA, from a trad.)</p><p><b class=\"ar\">مَهْجُورٌ</b> <i>Cut off from friendly</i> or <i>loving communion</i> or <i>intercourse; forsaken,</i> or <i>abandoned: cut,</i> or <i>not spoken to.</i> (Mgh, Msb.) In like manner <span class=\"ar\">مَهْجُورًا</span> is used in the Kur, [xxv. 32,] signifying <i>avoided,</i> or <i>forsaken, with the tongue,</i> or <i>with the heart</i> or <i>mind.</i> (B.) [But see what here follows.] -A2- Talk, or language, <i>uttered irrationally</i> or <i>foolishly</i> or <i>deliriously.</i> It is related by Aboo-'Obeyd, on the authority of Ibráheem, that the words of the Kur, <span class=\"ar\">إِنَّ قَوْمِى ٱتَّخَذُوا هٰذَا</span> <span class=\"ar\">ٱلْقُرْآنَ مَهْجُورًا</span>, [xxv. 32,] mean, <i>Verily my people have made this Kur-án a thing of which they have said what is not true:</i> because the sick man, when he talks irrationally or foolishly or deliriously, says what is not true: and the like is related on the authority of Mujáhid. (S.)</p><p><b class=\"ar\">مُهَاجَرٌ</b> <i>A place to which one emigrates.</i> (Msb.)</p><p><b class=\"ar\">مُهَاجِرٌ</b> Any one, whether an inhabitant of the desert [as in the primary acceptation of the epithet] or an inhabitant of a town or village or cultivated district, <i>who emigrates;</i> or <i>who forsakes his country</i> or <i>district</i> or <i>the like, and takes up his abode in another country</i> or <i>district</i> or <i>the like.</i> Hence <span class=\"ar\">المُهَاجِرُونَ</span> applied to <i>The emigrants</i> to El-Medeeneh: because they forsook their places of abode in which they were reared, for the sake of God, and attached themselves to an abode in which they had neither family nor property, when they emigrated to El-Medeeneh. (TA.)</p>"},"هون":{"mf":"<strong>الْهَوَانُ على وجهين:</strong><br>أحدهما: تذلّل الإنسان في نفسه لما لا يلحق به غضاضة، فيمدح به نحو قوله: وَعِبادُ الرَّحْمنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْناً<br>[الفرقان/ ٦٣] ونحو ما روي عن النبيّ صلّى الله عليه وسلم:<br><strong>«المؤمن هَيِّنٌ ليّن»</strong> <strong>«٣»</strong>.<br>الثاني: أن يكون من جهة متسلّط مستخفّ به<br><br>فيذمّ به. وعلى الثاني قوله تعالى: الْيَوْمَ تُجْزَوْنَ عَذابَ الْهُونِ<br>[الأنعام/ ٩٣]، فَأَخَذَتْهُمْ صاعِقَةُ الْعَذابِ الْهُونِ [فصلت/ ١٧]، وَلِلْكافِرِينَ عَذابٌ مُهِينٌ<br>[البقرة/ ٩٠]، وَلَهُمْ عَذابٌ مُهِينٌ [آل عمران/ ١٧٨]، فَأُولئِكَ لَهُمْ عَذابٌ مُهِينٌ [الحج/ ٥٧]، وَمَنْ يُهِنِ اللَّهُ فَما لَهُ مِنْ مُكْرِمٍ<br>[الحج/ ١٨] ويقال: هانَ الأمْرُ على فلان:<br>سهل. قال الله تعالى: هُوَ عَلَيَّ هَيِّنٌ [مريم/ ٢١]، وَهُوَ أَهْوَنُ عَلَيْهِ<br>[الروم/ ٢٧]، وَتَحْسَبُونَهُ هَيِّناً [النور/ ١٥] والْهَاوُونَ: فاعول من الهون، ولا يقال هارون، لأنه ليس في كلامهم فاعل.","mq":[["سكون او سكينة (٢) او ذل"],"الهاء والواو والنون أُصَيلٌ يدلُّ على سكون أو سكينة (٢) أو ذلّ. من ذلك الهَوْن: السَّكينة والوَقار. قال اللّه سبحانه: ﴿يَمْشُونَ عَلَى اَلْأَرْضِ هَوْناً﴾. والهُون: الهَوان. قال ﷿<br>: ﴿أَيُمْسِكُهُ عَلى هُونٍ﴾.<br>والهَاوُون، لِلذى يُدقُّ به عربىٌّ صحيح، كأنّه فاعول من الهَوْن.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَانَ</b> , inf. n. <span class=\"ar\">هَوَانٌ</span> and <span class=\"ar\">هُونٌ</span> (Msb, K) and <span class=\"ar\">مَهَانَةٌ</span>, (K,) <i>He,</i> or <i>it, was,</i> or <i>became, low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious,</i> and <i>weak;</i> syn. <span class=\"ar\">ذَلَّ</span>, (Msb, K,) and <span class=\"ar\">حَقُرَ</span>, (Msb,) and <span class=\"ar\">ضَعُفَ</span>. (TA.) -b2- <span class=\"ar\">هَانَ عَلَيْهِ</span> [<i>It was of light estimation to him</i>] <i>It</i> (a thing) <i>was</i> [<i>easy and</i>] <i>light to him.</i> (TA.) -b3- <span class=\"ar\">هَانَ</span> also, <i>He,</i> or <i>it, was,</i> or <i>became, gentle,</i> and <i>easy.</i> (Msb.)</p><p><b>2.</b> <b class=\"ar\">هَوَّنَهُ عَلَيْهِ</b> <i>He</i> (God) <i>made it easy and light to him.</i> (K, * TA.) -b2- <span class=\"ar\">هَوِّنِى الأَمْرَ وَلاَ تَحْزَنِيى لَهُ</span> [<i>Make thou the case,</i> or <i>affair, light,</i> or <i>easy;</i> i. e., <i>regard it lightly; and do not grieve for it</i>]. (TA, art. <span class=\"ar\">خفض</span>.)</p><p><b>4.</b> <b class=\"ar\">أَهَاهَهُ</b> , and <span class=\"ar\"> <span class=\"ar\">اِسْتَهَانَ</span>بِهِ</span>, and <span class=\"ar\"> <span class=\"ar\">تَهَاوَنَ</span>بِهِ</span>, <i>He held him in light,</i> or <i>little,</i> or <i>mean, estimation, or in contempt; despised him; made light of him</i> or <i>it.</i> (S, K, &amp;c.) -b2- <span class=\"ar\">أَهَانَهُ</span> <i>He lowered,</i> or <i>abased, him; debased him; rendered him abject, vile, mean, paltry, contemptible, despicable, or ignominious.</i></p><p><b>6.</b> <b class=\"ar\">تَهَاْوَنَ</b> see 4.</p><p><b>10.</b> <b class=\"ar\">إِسْتَهْوَنَ</b> see 4.</p><p><b class=\"ar\">هَيْنٌ</b> and <span class=\"ar\"> <span class=\"ar\">هَيِّنٌ</span></span> <i>Easy:</i> (S, Msb, K:) and the latter <i>of light estimation, paltry, despicable.</i> (K, * TA.)</p><p><b class=\"ar\">على هِيْنَتَكِ</b> <i>at their ease.</i></p><p><b class=\"ar\">هَيِّنٌ</b> : see <span class=\"ar\">هَيْنٌ</span>.</p><p><b class=\"ar\">أَهْوَنُ</b> in the sense of <span class=\"ar\">هَيِّنٌ</span>: see <span class=\"ar\">أَكْبَرُ</span>. See also an ex. voce <span class=\"ar\">بَصِيرَةٌ</span>; and another voce <span class=\"ar\">بَعْرٌ</span>.</p><p><b class=\"ar\">بَعِيرٌ مُهَانٌ عَلَى أَهْلِهِ</b> [<i>A camel held in mean estimation by his owner</i>]. (TA, art. <span class=\"ar\">دفع</span>.)</p>"},"هود":{"mf":"الْهَوْدُ: الرّجوع برفق، ومنه: التَّهْوِيدُ، وهو<br><br>مشي كالدّبيب، وصار الْهَوْدُ في التّعارف التّوبة.<br>قال تعالى: إِنَّا هُدْنا إِلَيْكَ<br>[الأعراف/ ١٥٦] أي: تبنا، قال بعضهم: يَهُودُ في الأصل من قولهم: هُدْنَا إليك، وكان اسم مدح، ثم صار بعد نسخ شريعتهم لازما لهم وإن لم يكن فيه معنى المدح، كما أنّ النصارى في الأصل من قوله: مَنْ أَنْصارِي إِلَى اللَّهِ [الصف/ ١٤] ثم صار لازما لهم بعد نسخ شريعتهم. ويقال:<br>هَادَ فلان: إذا تحرّى طريقة الْيَهُودِ في الدّين، قال الله عزّ وجلّ: إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هادُوا<br>[البقرة/ ٦٢] والاسم العلم قد يتصوّر منه معنى ما يتعاطاه المسمّى به. أي: المنسوب إليه، ثم يشتقّ منه. نحو: قولهم تفرعن فلان، وتطفّل: إذا فعل فعل فرعون في الجور، وفعل طفيل في إتيان الدّعوات من غير استدعاء، وتَهَوَّدَ في مشيه: إذا مشى مشيا رفيقا تشبيها باليهود في حركتهم عند القراءة، وكذا: هَوَّدَ الرّائض الدابّة: سيّرها برفق، وهُودٌ في الأصل جمع هَائِدٍ. أي: تائب وهو اسم نبيّ عليه السلام.","mq":[["ارواد وسكون"],"الهاء والواو والدال: أصلٌ يدلُّ على إرْوَادٍ وسُكون.<br>يقولون: [التَّهويد (٥)<br>]: المَشْىُ (٦) الرُّوَيْد. ويقولون: هَوَّدَ، إذا نامَ. وهَوَّد الشَّرابُ نَفْسَ الشّاربِ، إذا خَثَرت له نَفْسُه. والهَوَادَة: الحالُ تُرحَى معها<br>السَّلامةُ بين القوم. والمُهَاودة: المُوادَعَة (١)<br>. فأمَّا اليَهُودُ فمِن هاد"],"ln":"<p><b>1.</b> <b class=\"ar\">هَادَ</b> , aor. <span class=\"ar\">يَهُودُ</span>, (S, L, &amp;c.,) inf. n. <span class=\"ar\">هَوْدٌ</span>, (S, L, K, &amp;c.,) <i>He returned</i> (IAar, A, L, Msb) <i>from evil to good</i> or <i>from good to evil:</i> (IAar, L:) <i>he repented,</i> (S, A, L, K;) <i>and returned to the truth;</i> (S, L, K;) as also <span class=\"ar\"> <span class=\"ar\">تهوّد</span></span>: (L:) and the latter, <i>he repented and did righteously.</i> (AO, S, A, L.) -b2- <span class=\"ar\">هُدْنَا إِلَيْكَ</span> <i>We have turned unto Thee with repentance.</i> (Kur, vii, 155.] So accord. to Mujáhid and Sa'eed Ibn-Jubeyr and Ibráheem. (L.) It is made trans. by means of <span class=\"ar\">الى</span> because implying the meaning of <span class=\"ar\">رَجَعْنَا</span>. (ISd, L.) -b3- <span class=\"ar\">هَادَ</span>, (S, A, L,) aor. <span class=\"ar\">يَهُودُ</span>, inf. n. <span class=\"ar\">هَوْدٌ</span>; (L;) and <span class=\"ar\"> <span class=\"ar\">تَهوّد</span></span>; (S, A, L, Msb, K;) <i>He became a Jew;</i> (S, A, L, K;) <i>he became of the Jewish religion.</i> (L, Msb.)</p><p><b>2.</b> <b class=\"ar\">هوّدُه</b> , (L, Msb, K,) inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, (S,) <i>He made him</i> (his son [for instance] Msb) <i>a Jew;</i> (S, L, Msb;) <i>he turned him to the religion of the Jews;</i> (L, K;) <i>taught him that religion, and initiated him in it.</i> (L.) -A2- <span class=\"ar\">تَهْوِيدٌ</span> The <i>talking together of jinn,</i> or <i>genii:</i> (L, K:) so termed because of the gentleness and weakness of their voices. (L.) -b2- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, <i>He reiterated his voice,</i> or <i>quavered,</i> or <i>trilled, gently.</i> (Ibn-Jebeleh, L, K.) -b3- <span class=\"ar\">هوّد</span>, (L,) inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, (K,) <i>He sang;</i> syn. <span class=\"ar\">غَنَّى</span>: (Aboo-Málik, L:) <i>he sang,</i> or <i>gladdened, and diverted;</i> syn. <span class=\"ar\">طَرَّبَ وَأَلْهَى</span>. (K.) See also <span class=\"ar\">مُهَوِّدٌ</span>. -A3- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, <i>He went,</i> or <i>proceeded, gently,</i> or <i>in a leisurely manner,</i> (S, L, K,) like the manner termed <span class=\"ar\">دَبِيبٌ</span>: from <span class=\"ar\">الهَوَادَةُ</span>. (S, L, K.) It is said in a trad., <span class=\"ar\">أَسْرِعُوا المَشْىَ فِى الجَنَازَةِ وَلَا تُهَوِّدُوا كَمَا</span> <span class=\"ar\">تُهَوِّدُ اليَهُودُ والنَّصَارَى</span> [<i>Make ye your pace to be quick at a funeral, and go ye not in a gentle</i> or <i>leisurely manner like as go the Jews and the Christians</i>]. (S.) See also 5. -b2- <span class=\"ar\">هوّد</span>, (L,) inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, (S, L, K,) <i>It</i> beverage, or wine,) <i>intoxicated</i> (S, L, K) a person: and <i>rendered</i> him <i>languid, and caused</i> him <i>to sleep.</i> (L.) -b3- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span> and <span class=\"ar\">تَهْوَادٌ</span>; (L, K;) and <span class=\"ar\"> <span class=\"ar\">تهوّد</span></span>; (TA;) <i>He uttered a weak, gentle,</i> (L, K,) <i>and languid,</i> (L,) <i>voice.</i> (L, K.) -b4- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span> (S, L, K) and <span class=\"ar\">تَهْوَادٌ</span>; and <span class=\"ar\"> <span class=\"ar\">تهوّد</span></span>; (K;) <i>He was low, not loud,</i> in speech, or utterance. (S, L, K) -b5- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span> (L, K) and <span class=\"ar\">تَهْوَادٌ</span>; and <span class=\"ar\"> <span class=\"ar\">تهوّد</span></span>; (L;) <i>He was slow,</i> or <i>tardy, in his pace,</i> (L, K,) <i>and gentle.</i> (L.) -b6- <span class=\"ar\">هوّد</span> <i>He</i> (a man) <i>rested;</i> or <i>was still, quiet,</i> or <i>at rest.</i> (Aboo-Málik, L.) -b7- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, <i>He slept.</i> (S, L.) -b8- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span> and <span class=\"ar\">تَهْوَادٌ</span>; and <span class=\"ar\"> <span class=\"ar\">تهوّد</span></span>; <i>He was gentle; he acted,</i> or <i>behaved, in a gentle manner.</i> (L.) -b9- Also, The <i>murmuring and gentle sounding of the wind over sand.</i> (L.) -A4- <span class=\"ar\">هوّد</span>, inf. n. <span class=\"ar\">تَهْوِيدٌ</span>, <i>He ate of a camel's hump;</i> (K;) or <i>what is termed</i> <span class=\"ar\">هَوَدَة</span>. (TA.)</p><p><b>3.</b> <b class=\"ar\">هاودهُ</b> , (A,) inf. n. <span class=\"ar\">مُهَاوَدَةٌ</span>. (S, A, L, K,) <i>He made peace with him; reconciled himself with him;</i> (A;) syn. of the inf. n. <span class=\"ar\">مُوَادَعَةٌ</span>; (A, L;) in the K, <span class=\"ar\">مُوَاعَدَةٌ</span>, which is a mistake; (TA;) and <span class=\"ar\">مُصَالَحَةٌ</span>, (S, L,) and <span class=\"ar\">مُهَادَنَةٌ</span>: (TA:) and also <span class=\"ar\">مُرَاجَعَةٌ</span> [app. signifying the <i>restoring</i> a person, or <i>taking him back, into one's favour</i>]. (TA.) -b2- <i>He inclined towards him reciprocally;</i> syn. <span class=\"ar\">مَايَلَهُ</span>: and <span class=\"ar\">هَاوَدَا</span> <i>They two inclined each towards the other;</i> syn. <span class=\"ar\">مَايَلَا</span>: (TK:) syn. of the inf. n. <span class=\"ar\">مُمَايَلَةٌ</span>. (S, L.) -b3- <i>He returned to him,</i> or <i>it, time after time;</i> syn. <span class=\"ar\">عَاوَدَهُ</span>: (TK:) syn. of the inf. n. <span class=\"ar\">مُعَاوَدَةٌ</span>. (K.)</p><p><b>5.</b> <b class=\"ar\">تَهَوَّدَ</b> see 1 and 2. -b2- <span class=\"ar\">تهوّد فِى مَشْيِهِ</span> <i>He walked gently, imitating the motions of the Jews in their reciting</i> or <i>reading.</i> (El-Basáïr.) See also 2. -b3- <span class=\"ar\">تهوّد</span> <i>He became allied,</i> or <i>allied himself,</i> or <i>sought to ally himself,</i> (<span class=\"ar\">تَوَصَّلَ</span>, K, and <span class=\"ar\">تَقَرَّبَ</span>, ElBasáïr,) <i>by a bond of relationship;</i> or <i>by some other sacred</i> or <i>inviolable bond</i> or <i>tie,</i> or <i>a quality</i> <i>&amp;c. to be regarded as sacred</i> or <i>inviolable</i> or <i>rendering him entitled to respect</i> or <i>reverence.</i> (K, El-Basáïr.) See also <span class=\"ar\">مُتَهَوِّدٌ</span>.</p><p><b class=\"ar\">الهُودُ</b> : see <span class=\"ar\">يَهُودُ</span>.</p><p><b class=\"ar\">هَوْدَةٌ</b> : see <span class=\"ar\">هَوَدَةٌ</span>.</p><p><b class=\"ar\">هَوَدَةٌ</b> <i>A camel's hump:</i> (S, K:) or the <i>base of the hump:</i> (Sh, L:) as also <span class=\"ar\"> <span class=\"ar\">هَوْدَةٌ</span></span>: (L:) pl. <span class=\"ar\">هَوَدٌ</span>: (S, L, K:) [or rather, this is a coll. gen. n., and <span class=\"ar\">هَوَدَةٌ</span> is the n. un.].</p><p><b class=\"ar\">هَوَادَةٌ</b> <i>Gentleness; lenity;</i> (A, L, K;) <i>and that kind of conduct whereby one hopes to effect the adjustment of an affair between a people:</i> (L, K:) <i>quietness:</i> (L:) <i>peace,</i> or <i>reconciliation: inclination,</i> or <i>affection:</i> (S, L:) <i>favour,</i> or <i>partiality:</i> (L:) <i>facilitation, whereby a person is indulged in an affair.</i> (L, K.) Ex. <span class=\"ar\">لَا تَأْخُذُهُ</span> <span class=\"ar\">فِى ٱللّٰهِ هَوَادَةٌ</span> <i>Quietness with respect to</i> a restrictive ordinance of <i>God, with favour</i> or <i>partiality</i> towards any one, <i>will not affect him,</i> or <i>influence him.</i> And <span class=\"ar\">لَا تَأْخُذُهُ فِيكَ هَوَادَةٌ</span> <i>Favour</i> or <i>partiality with respect to thee will not affect him,</i> or <i>influence him.</i> (L, each from a trad.) -b2- <span class=\"ar\">هَوَادَةٌ</span> also signifies <i>A sacred</i> or <i>inviolable bond</i> or <i>tie;</i> or <i>a quality &amp;c. to be regarded as sacred</i> or <i>inviolable,</i> or <i>rendering one entitled to respect</i> or <i>reverence:</i> and <i>a bond of relationship.</i> (L.)</p><p><b class=\"ar\">هَائِدٌ</b> <i>Returning</i> (Msb) [<i>from evil to good</i> or <i>from good to evil:</i> see 1:] <i>repenting and returning to the truth:</i> (S, L:) pl. <span class=\"ar\">هُودٌ</span>, (S, A, L, Msb,) like as <span class=\"ar\">بُزْلٌ</span> is pl. of <span class=\"ar\">بَازِلٌ</span>. (S, L, Msb.)</p><p><b class=\"ar\">يَهُودُ</b> and <span class=\"ar\">اليَهُودُ</span> and <span class=\"ar\"> <span class=\"ar\">الهُودُ</span></span> [the second of which is the most common,] signify the same, (S, A, L, Msb, K,) <i>A certain tribe;</i> [namely, <i>the Jews:</i>] (L:) <span class=\"ar\">يَهُودُ</span> is said by some to be originally <span class=\"ar\">يَهُوذُ</span>, and arabicized by the change of <span class=\"ar\">ذ</span> into <span class=\"ar\">د</span>; but ISd disapproves of this assertion: others say, that it is from <span class=\"ar\">هَادَ</span> “ he repented: ” (L:) it is imperfectly decl., because it is a proper name and of the measure of a verb; and [of the fem. gen., as it is said to be in the S and L,] because it means a <span class=\"ar\">قَبِيلَة</span>: but it is allowable to prefix to it the art. <span class=\"ar\">ال</span>, and to say <span class=\"ar\">اليَهُودُ</span>: (Msb:) this, however, is allowable only on the ground of its being, with the art. prefixed, for <span class=\"ar\">اليَهُودِيُّونَ</span>; for it is of itself determinate: (S, L:) [thus] <span class=\"ar\">يَهُودُ</span> is [as it were] pl. of <span class=\"ar\"> <span class=\"ar\">يَهُودِىٌّ</span></span>; (L;) which is the rel. n. of <span class=\"ar\">يهود</span>, or, accord. to Sgh, of <span class=\"ar\">يَهُودَا</span> [or Judah], thus written by him with the unpointed <span class=\"ar\">د</span> in this instance, the son of <span class=\"ar\">يَعْقُوب</span> [or Jacob]: (Msb:) <span class=\"ar\">يَهُودُ</span> (sometimes, TA) has <span class=\"ar\">يَهْدَانٌ</span> as a pl.: (K:) this pl. occurs in a poem of Hassán: (TA:) Fr, says, of <span class=\"ar\">هُودًا</span>, in the Kur, ii, 105, that it is for <span class=\"ar\">يَهُودًا</span> [app. a mistake for <span class=\"ar\">يَهُودَ</span>]; or that it may be pl. of <span class=\"ar\">هَائِدٌ</span>. (L.)</p><p><b class=\"ar\">يَهُودِىٌّ</b> : see <span class=\"ar\">يَهُودُ</span>.</p><p><b class=\"ar\">اليَهُودِيَّةُ</b> <i>The Jewish religion.</i> (L.)</p><p><b class=\"ar\">غِنَآءٌ مُهَوِّدٌ</b> [in some copies of the S, <span class=\"ar\">مُهَوَّدٌ</span>,] <i>A low, not loud, singing.</i> (S, L.) -b2- <span class=\"ar\">مُهَوِّدٌ</span> also signifies <i>Gladdening, and diverting;</i> syn. <span class=\"ar\">مُطْرِبٌ</span> and <span class=\"ar\">مُلْهٍ</span>. (IAar, L.)</p><p><b class=\"ar\">مُتَهَوِّدٌ</b> <i>Allied,</i> or <i>allying himself,</i> or <i>seeking to ally himself,</i> (<span class=\"ar\">مُتَوَصِّلٌ</span>, IAar, Sh,) <i>by what is termed</i> <span class=\"ar\">هَوَادَةٌ</span>. (IAar, Sh, L.) See 5.</p>"},"هبط":{"mf":"الهُبُوط: الانحدار على سبيل القهر كهبوط الحجر، والهَبُوط بالفتح: المنحدر. يقال:<br>هَبَطْتُ أنا، وهَبَطْتُ غيري، يكون اللازم والمتعدّي على لفظ واحد. قال تعالى: وَإِنَّ مِنْها لَما يَهْبِطُ مِنْ خَشْيَةِ اللَّهِ<br>[البقرة/ ٧٤] يقال: هَبَطْتُ وهَبَطْتُهُ هَبْطاً، وإذا استعمل في الإنسان الهُبُوط فعلى سبيل الاستخفاف بخلاف الإنزال، فإنّ الإنزال ذكره تعالى في الأشياء التي نبّه على شرفها، كإنزال الملائكة والقرآن والمطر وغير ذلك. والهَبُوطُ ذكر حيث نبّه على الغضّ نحو: وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ [البقرة/ ٣٦]، فَاهْبِطْ مِنْها فَما يَكُونُ لَكَ أَنْ تَتَكَبَّرَ فِيها [الأعراف/ ١٣]، اهْبِطُوا مِصْراً فَإِنَّ لَكُمْ ما سَأَلْتُمْ [البقرة/ ٦١] وليس في قوله: فَإِنَّ لَكُمْ ما سَأَلْتُمْ [البقرة/ ٦١] تعظيم وتشريف، ألا ترى أنه تعالى قال:<br>وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَباؤُ بِغَضَبٍ مِنَ اللَّهِ [البقرة/ ٦١]، وقال جلّ ذكره: قُلْنَا اهْبِطُوا مِنْها جَمِيعاً [البقرة/ ٣٨] ويقال: هَبَطَ المَرَضُ لحم العليل: حطّه عنه، والهَبِيط:<br>الضّامر من النّوق وغيرها إذا كان ضمره من سوء غذاء، وقلّة تفقّد.","mq":[["انحدار"],"الهاء والباء والطاء: كلمةٌ تدلُّ على انحدار. وهَبَط هُبوطاً.<br>الهَبُوط: الحُدور. وهَبَطتُ أنا وهَبَطْتُ غَيرِى، وهَبَط المرضُ لحمَ العَليل.<br>والهَبِيط: الضَّامر من الإبل.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَبَطَ</b> , (S, Msb, K,) aor. <b class=\"ar\">هَبِطَ</b> and <b class=\"ar\">هَبُطَ</b> , (Msb, K,) but the latter is of rare occurrence, (Msb,) inf. n. <span class=\"ar\">هُبُوطٌ</span>, (S, K,) of that whereof the aor. is <b class=\"ar\">هَبِطَ</b> , and of that whereof the aor. is <b class=\"ar\">هَبُطَ</b> ; (TA;) or of the latter only, that of the former being <span class=\"ar\">هَبْطٌ</span>; (Msb;) <i>He,</i> or <i>it,</i> (said of water &amp;c., Msb,) <i>descended:</i> (S, Msb, K:) and <span class=\"ar\"> <span class=\"ar\">تهبّط</span></span> <i>he descended,</i> or <i>went down,</i> or <i>went down a declivity;</i> and <i>it sloped down;</i> syn. <span class=\"ar\">إِنْحَدَرَ</span>; (TA;) and <span class=\"ar\"> <span class=\"ar\">انهبط</span></span> signifies the same as this last; or (assumed tropical:) <i>he became lowered,</i> or <i>degraded;</i> syn. <span class=\"ar\">إِنْحَطَّ</span>; (K;) being quasi-pass. of <span class=\"ar\"> <span class=\"ar\">أَهْبَطَهُ</span></span>, (S, TA,) and it may be also of <span class=\"ar\">هَبَطَهُ</span>, as is said in the M. (TA.) You say, <span class=\"ar\">هَبَطْنَا فِى</span> <span class=\"ar\">حَدُورٍ صَعْبَةٍ</span> [<i>We descended a difficult declivity</i>]. (A, in art. <span class=\"ar\">حدر</span>.) And <span class=\"ar\">هَبَطَ الوَادِىَ</span>, (Bd, ii. 58, and Msb,) [as though it were trans., for <span class=\"ar\">فِى</span> <span class=\"ar\">الوَادِى</span>,] inf. n. <span class=\"ar\">هُبُوطٌ</span>, (Msb,) <i>We descended into the valley.</i> (Bd, Msb.) And <span class=\"ar\">هَبَطَ مِنْهُ</span> <i>He came forth from it.</i> (Bd, ubi supra.) It is said in the Kur, ii. 58, <span class=\"ar\">إِهْبِطُوا مِصْرًا</span> <i>Descend ye into Misr:</i> (Bd:) accord. to one reading, <span class=\"ar\">أُهْبُطُوا</span>. (Bd, TA.) You say also <span class=\"ar\">هَبَطَ بَلَدَ كَذَا</span> <i>He entered such a town</i> or <i>country.</i> (K.) And <span class=\"ar\">هَبَطْتُ مِنْ مَوْضِعٍ إِلَى مَوْضِعٍ</span> <i>I removed him from a place to a place.</i> (Msb.) -b2- <span class=\"ar\">هَبْطٌ</span> also signifies (tropical:) The <i>falling into evil:</i> (K, TA:) and (tropical:) the <i>being,</i> or <i>becoming, low, abject, mean,</i> or <i>vile:</i> (TA:) and (tropical:) the <i>suffering loss,</i> or <i>diminution.</i> (K, TA.) You say, <span class=\"ar\">هَبَطَ مِنْ مَنْزِلَتِهِ</span> (tropical:) <i>He fell from his honourable station.</i> (TA.) [See also 7, mentioned above.] And <span class=\"ar\">هَبَطَ فُلَانٌ</span> (tropical:) <i>Such a one became low, abject, mean,</i> or <i>vile.</i> (TA.) And <span class=\"ar\">هَبَطَ مِنَ الخَشْيَةِ</span> (tropical:) <i>He became mean,</i> or <i>abject, and lowly,</i> or <i>submissive, from fear</i> (TA.) [See Kur, ii. 69.] And <span class=\"ar\">هَبَطَ القَوْمُ</span>, aor. <b class=\"ar\">هَبِطَ</b> , (tropical:) <i>The people,</i> or <i>company of men, became in a state of abasement and diminution.</i> (TA.) Whence the trad., (TA,) <span class=\"ar\">أَللّٰهُمَّ غَبْطًا لَا هَبْطًا</span>, (S, TA,) i. e. <span class=\"ar\">نَسْأَلُكَ</span> <span class=\"ar\">الغِبْطَةَ وَنَعُوذُ بِكَ مِنْ أَنْ نَهْبِطَ عَنْ حَالِنَا</span> ((tropical:) <i>O God,</i> we ask of Thee <i>a good state,</i> or <i>condition,</i> and we put our trust in Thee for preservation <i>that we may not become brought down from our state</i>]: (S.) mentioned [and explained] before, in art. <span class=\"ar\">غبط</span>, q. v. (TA.) [But in this instance, <span class=\"ar\">هَبْطًا</span> may be regarded as the inf. n. of the trans. v. to be mentioned below.] You say also, <span class=\"ar\">هَبَطَتْ إِبِلِى</span> <span class=\"ar\">وَغَنَمِى</span>, aor. <b class=\"ar\">هَبِطَ</b> , inf. n. <span class=\"ar\">هُنُوطٌ</span>, (assumed tropical:) <i>My camels, and my sheep,</i> or <i>goats, suffered loss,</i> or <i>diminution:</i> and in the same sense <span class=\"ar\">هَبَطَ</span> is said of flesh, and of fat, and of fatness. (TA.) And <span class=\"ar\">هَبَطَ ثَمَنُ السِّلْعَةِ</span> (tropical:) <i>The price of the commodity,</i> or <i>article of merchandise, became diminished,</i> or <i>lessened,</i> (S, Msb, K, TA.) <i>below its former full rate;</i> (Msb;) <i>became lowered,</i> or <i>abated.</i> (TA.) And <span class=\"ar\">هَبَطَ العِدْلُ</span> (assumed tropical:) <i>The counterpoising portion of the load became adjusted</i> or <i>arranged, made even,</i> or <i>made easy,</i> upon the camel. (TA.) -A2- <span class=\"ar\">هَبَطَهُ</span>, (S, Msb. K.) aor. <b class=\"ar\">هَبُطَ</b> , (K,) inf. n. <span class=\"ar\">هَبْطٌ</span>, (S,) <i>He made him,</i> or <i>it,</i> (namely water. &amp;c., Msb,) <i>to descend:</i> (S, Msb, K;) [<i>he sent,</i> or <i>east, him,</i> or <i>it, down;</i>] as also <span class=\"ar\"> <span class=\"ar\">اهبطهُ</span></span>. (K.) You say, <span class=\"ar\"> <span class=\"ar\">أَهْبَطَتْهُمُ</span>السَّنَةُ إِلَى الأَمْصَارِ</span> [<i>The year of dearth,</i> or <i>drought, caused them to go down to the cities,</i> or <i>great towns</i>]. (A, in art. <span class=\"ar\">حسر</span>.) And <span class=\"ar\">هَبَطَهُ بَلَدَ كَذَا</span> <i>He,</i> or <i>it, caused him to enter such a town</i> or <i>country.</i> (K.) [And <span class=\"ar\">هَبَطَ بِهِ عَلَى مَكَانٍ</span> <i>He,</i> or <i>it, made him to alight upon a place:</i> see an ex. voce <span class=\"ar\">زَحَّ</span>.] -b2- (tropical:) <i>He lowered him,</i> or <i>degraded him, from his state,</i> or <i>condition;</i> (Fr;) as also <span class=\"ar\"> <span class=\"ar\">اهبطهُ</span></span>; (Fr, S;) i. e., God did so; (Fr;) or a man: (S:) <i>it</i> (time, or fortune,) <i>caused his wealth, and his goodness</i> or <i>beneficence, to go away, after he had abounded therein.</i> (TA.) -b3- <span class=\"ar\">هَبَطَ المَرَضُ لَحْمَهُ</span> (tropical:) <i>The disease rendered him lean; emaciated him:</i> (S, K:) or <i>diminished his flesh.</i> (TA.) -b4- <span class=\"ar\">هَبَطَ</span> <span class=\"ar\">ثَمَنَ السِّلْعَةِ</span>, (S, K.) inf. n. <span class=\"ar\">هَبْطٌ</span>, (K,) (tropical:) <i>He</i> (God, K, or a man, S) <i>diminished,</i> or <i>lessened, the price of the commodity,</i> or <i>article of merchandise;</i> (S, K;) <i>he lowered,</i> or <i>abated, it;</i> (TA;) as also <span class=\"ar\"> <span class=\"ar\">اهبطهُ</span></span>, said of a man: (A 'Obeyd, S, M:) or <span class=\"ar\">هَبَطَ مِنَ الثَّمَنِ</span> (assumed tropical:) <i>he diminished somewhat from the price;</i> and sometimes <span class=\"ar\"> <span class=\"ar\">اهبطهُ</span></span> is used in this sense. (Msb.) -b5- <span class=\"ar\">هَبَطَ العِدْلَ</span> (assumed tropical:) <i>He adjusted</i> or <i>arranged, made even,</i> or <i>made easy, the counterpoising portion of the load</i> upon the camel (TA.) -b6- <span class=\"ar\">هَبَطَ فُلَانًا</span> <i>He beat,</i> or <i>struck, such a one.</i> (K.)</p><p><b>4.</b> <b class=\"ar\">أَهْبَطَ</b> see <span class=\"ar\">هَبَطَهُ</span>, in five places.</p><p><b>5.</b> <b class=\"ar\">تَهَبَّطَ</b> see <span class=\"ar\">هَبَطَ</span>, first sentence.</p><p><b>7.</b> <b class=\"ar\">إِنْهَبَطَ</b> see <span class=\"ar\">هَبَطَ</span>, first sentence.</p><p><b class=\"ar\">هَبْطَةٌ</b> <i>A low,</i> or <i>depressed, piece of land</i> or <i>ground;</i> (Mgh, K;) <i>contr. of</i> <span class=\"ar\">صَعْدَةٌ</span>. (Mgh.)</p><p><b class=\"ar\">هَبُوطٌ</b> <i>A declivity,</i> or <i>declinal place, a place of descent,</i> or <i>by which one descends,</i> (S, Msb, K;) <i>a place which brings one down from a higher to a lower place.</i> (Az, TA.)</p><p><b class=\"ar\">هَبيطٌ</b> (tropical:) <i>Lean,</i> or <i>emaciated,</i> by reason of disease; as also <span class=\"ar\"> <span class=\"ar\">مَهْبُوطٌ</span></span>: (K:) both are applied to a camel, signifying <i>whose fatness has become diminished;</i> as also <span class=\"ar\"> <span class=\"ar\">هَابِطٌ</span></span>: (TA:) and the first, to a she-camel, signifying <i>lean, and lank in the belly;</i> (AO, S;) or to a wild bull, to which a she-camel is likened in respect of her swiftness, and her briskness, liveliness, or sprightliness (IB:) and ↓ the second signifies <i>rendered lean.</i> or <i>emaciated, by disease, so that his flesh quivers.</i> (TA.)</p><p><b class=\"ar\">هَابِطٌ</b> [act. part. n. of 1, both intrans. and trans.] The rájiz says, <span class=\"ar\">مَا رَاعَِنى إِلَّا جَنَاحٌ هَابِطَا</span> <span class=\"ar\">عَلَى البُيُوت قَوْطَهُ العُلَابِطَا</span> [<i>Nothing surprised me but the wolf sending down upon the tents his flock of sheep,</i> or <i>goats, fifty</i> or <i>more in number</i>]: he means <span class=\"ar\">مُهْبِطًا قَوْطَهُ</span>: so says ISd: or he may mean <span class=\"ar\">هَابِطًا عَلَى قَوْطِهِ</span> [<i>descending upon his flock,</i> &amp;c.]; making <span class=\"ar\">هابطا</span> trans by ellipsis: (TA:) <span class=\"ar\">جناح</span>, in this verse, is the name of a wolf. (TA, in art. <span class=\"ar\">جنح</span>.) -b2- See also <span class=\"ar\">هَبِيطٌ</span>.</p><p><b class=\"ar\">مَهْبِطُ الوَحْىِ</b> [<i>The place of descent of revelation;</i>] <i>a name of Mekkah.</i> (Msb, TA)</p><p><b class=\"ar\">مَهْبُوطٌ</b> (tropical:) A man <i>whose state,</i> or <i>condition has become unsound.</i> (TA.) -b2- See also <span class=\"ar\">هَبيطٌ</span>, in two places.</p>"},"همم":{"mf":"الهَمُّ الحَزَنُ الذي يذيب الإنسان. يقال:<br>هَمَمْتُ الشّحم فَانْهَمَّ، والهَمُّ: ما هممت به في نفسك، وهو الأصل، ولذا قال الشاعر:<br><span class=\"num\">٤٧٠-</span><br>وهمّك ما لم تمضه لك منصب<br><strong>«٤»</strong> قال الله تعالى: إِذْ هَمَّ قَوْمٌ أَنْ يَبْسُطُوا<br>[المائدة/ ١١]، وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِها<br>[يوسف/ ٢٤]، إِذْ هَمَّتْ طائِفَتانِ مِنْكُمْ [آل عمران/ ١٢٢]، لَهَمَّتْ طائِفَةٌ مِنْهُمْ<br>[النساء/ ١١٣]، وَهَمُّوا بِما لَمْ يَنالُوا<br>[التوبة/ ٧٤]، وَهَمُّوا بِإِخْراجِ الرَّسُولِ [التوبة/ ١٣]، وَهَمَّتْ كُلُّ أُمَّةٍ بِرَسُولِهِمْ [غافر/ ٥] وأَهَمَّنِي كذا. أي: حملني على أن أَهِمَّ به. قال الله تعالى: وَطائِفَةٌ قَدْ أَهَمَّتْهُمْ أَنْفُسُهُمْ<br>[آل عمران/ ١٥٤] ويقال: هذا رجل هَمُّكَ من رجل <strong>«٥»</strong>، وهِمَّتُكَ من رجل، كما تقول: ناهيك من رجل. والْهَوَامُّ: حشرات الأرض، ورجل هِمٌّ، وامرأة هِمَّةٌ. أي: كبير، قد هَمَّهُ العمر. أي: أذابه.","ln":"<p><b>1.</b> <b class=\"ar\">هَمَّ</b> <i>He purposed, or intended,</i> a thing. <span class=\"ar\">هَمٌّ</span> denotes more than <span class=\"ar\">إِرَادَةٌ</span>, and less than <span class=\"ar\">عَزْمٌ</span>. (Kull, p. 382.) -b2- <span class=\"ar\">لَا مَهَمَّةَ وَلَا مَكَادَةَ</span>: see art. <span class=\"ar\">كود</span>. -b3- <span class=\"ar\">هَمَّ بِالشَّىْءِ</span> [<i>He meditated, proposed to himself, purposed,</i> or <i>intended, to do the thing:</i>] <i>he desired to do the thing,</i> (S, Msb,) <i>without doing it;</i> (Msb;) <i>he endeavoured to do the thing.</i> (S.) -b4- <span class=\"ar\">هَمَّ بِالأَمْرِ</span> <i>He intended the affair.</i> or <i>purposed it;</i> or <i>he desired it.</i> (Mgh.) -b5- <span class=\"ar\">هَمَّ بِهِ فِى نَفْسِهِ</span> [aor. <b class=\"ar\">هَمُمَ</b> ] <i>He intended it, meant it, desired it.</i> or <i>determined upon it, in his mind.</i> (TA.) See also a verse cited voce <span class=\"ar\">رُتَمٌ</span>. -b6- <span class=\"ar\">هم</span> <span class=\"ar\">بِالبَكَآءِ</span> [<i>He was about,</i> or <i>ready, to weep;</i> like <span class=\"ar\">أَرَادَ البُكَآءَ</span>, and <span class=\"ar\">تَهَيَّأَ لِلبُكَآءِ</span> q. v.]. (A, art. <span class=\"ar\">جهش</span>, &amp;c.) -b7- <span class=\"ar\">هَمَّ بالسُّقُوط</span> [<i>It threatened to fall</i>], said of a wall. (S, in art. <span class=\"ar\">وهى</span>, &amp;c.) -b8- <span class=\"ar\">هَمَّهُ</span> and <span class=\"ar\"> <span class=\"ar\">أَهَمَّهُ</span></span> <i>It disquieted him;</i> (Msb;) <i>caused him care,</i> or <i>anxiety.</i> -b9- <span class=\"ar\">لَا يُهِمُّهُ إِلَّا بَطْنُهُ</span> [<i>Nothing causes him care,</i> or <i>anxiety, but his belly</i>]. (S in art. <span class=\"ar\">بطن</span>.)</p><p><b>4.</b> <b class=\"ar\">أَهَمَّتُ</b> <i>It rendered him anxious;</i> (MA;) <i>disquieted him,</i> and <i>grieved him.</i> (Mgh.) See <span class=\"ar\">عَنَاهُ</span>.</p><p><b>7.</b> <b class=\"ar\">اِنهمَّ</b> : see a verse cited in art. <span class=\"ar\">ب</span>, p. 144.</p><p><b>8.</b> <b class=\"ar\">اِهْتَمَّ بِالأَمْرِ</b> <i>He was grieved,</i> and <i>disquieted, by the affair,</i> or <i>case:</i> (TA:) you say <span class=\"ar\">اِهْتَمَّ لَهُ</span> <span class=\"ar\">بِأَمْرِهِ</span> <i>he was grieved for him by his affair,</i> or <i>case.</i> (S.) [<i>He was,</i> or <i>became, anxious, disquieted,</i> or <i>grieved,</i> by it.] -b2- <i>He minded,</i> or <i>attended to, the affair:</i> (MA:) <i>undertook,</i> or <i>superintended,</i> or <i>managed, the affair.</i> (Msb.) See <span class=\"ar\">عُنِىَ</span>, in art. <span class=\"ar\">عنى</span>. -b3- <span class=\"ar\">اِهْتَمَّ لَهُ</span> <i>He cared for, minded,</i> or <i>regarded, him,</i> or <i>it.</i> (Har, p. 94.) -b4- <span class=\"ar\">اِهْتَمَّ بَلَدَ كَذَا</span> <i>i. q.</i> <span class=\"ar\">اِعْتَسَّهُ</span>. (TA in art. <span class=\"ar\">عس</span>.)</p><p><b class=\"ar\">هَمَ</b> for <span class=\"ar\">هَمَا</span> for <span class=\"ar\">أَمَا</span> before an oath: see the last.</p><p><b class=\"ar\">هَمٌّ</b> and <span class=\"ar\"> <span class=\"ar\">هِمَّةٌ</span></span> <i>Purpose,</i> or <i>intention;</i> syn. <span class=\"ar\">أَوَّلُ العَزْمِ</span> and <span class=\"ar\">أَوَّلُ العَزِيمَةِ</span>. (Msb.) See Har, p. 345, and a verse cited voce <span class=\"ar\">طَلَّاع</span>. -b2- Also the ↓ latter, <i>Strong determination</i> or <i>resolution.</i> (Msb.) -b3- <span class=\"ar\">هَمٌّ</span> <i>An object,</i> or <i>a thing intended</i> or <i>meant</i> or <i>desired</i> or <i>determined upon, in the mind.</i> (K, * TA.) See an ex. voce <span class=\"ar\">حَمٌّ</span> and <span class=\"ar\">سَمٌّ</span>: you say, <span class=\"ar\">هَمُّهُ كَذَا</span> <i>His object is such a thing.</i> -b4- <span class=\"ar\">هَمٌّ</span> [<i>Anxiety;</i> or <i>disquietude,</i> or <i>trouble, of mind; solicitude; care:</i> or <i>grief,</i> or <i>sorrow:</i>] <i>distress,</i> or <i>disquietude, affecting the heart</i> or <i>mind, by reason of some harm,</i> or <i>annoyance, that is expected to happen;</i> differing from <span class=\"ar\">غَمٌّ</span>, which signifies “ distress, or disquietude, affecting the heart or mind, by reason of what has happened: ” or both, as some say, signify the same [namely <i>distress,</i> or <i>disquietude, of mind</i>]: the difference is asserted by 'Iyád and others. (TA in art. <span class=\"ar\">غم</span>.) -b5- <span class=\"ar\">هَمُّهُ بَطْنُهُ</span> [<i>His object of care,</i> or <i>of anxiety, is his belly</i>]. (K in art. <span class=\"ar\">بطن</span>.) And <span class=\"ar\">لَا هَمَّ لَهُ إِلَّا بَطْنُهُ</span> [<i>He has no object of care,</i> or <i>of anxiety, but his belly</i>]. (TA in that art.) -b6- <span class=\"ar\">هَمَّكَ مَا هَمَّكَ</span> means <span class=\"ar\">هَمَّكَ مَا عَنَاكَ</span>: and <span class=\"ar\">هَمَّكَ</span> also signifies <span class=\"ar\">اذابك</span>. (JK.) See also Freytag's Arab. Prov. ii. 880.</p><p><b class=\"ar\">هِمٌّ</b> A <i>decrepit, old, and weak,</i> or <i>extremely aged.</i> man. (S, Msb, K.)</p><p><b class=\"ar\">هَمَّةٌ</b> : see <span class=\"ar\">هِمَّةٌ</span>.</p><p><b class=\"ar\">هِمَّةٌ</b> <i>A thing that one meditates, purposes,</i> or <i>intends to do;</i> or <i>that one desires to do;</i> or <i>endeavours to do; a purpose; an intention;</i> or <i>an object of desire,</i> or <i>of endeavour;</i> as also <span class=\"ar\"> <span class=\"ar\">هَمَّةٌ</span></span>. (JK, K.) -b2- <span class=\"ar\">هِمَّةٌ</span> [<i>Ambition;</i> particularly <i>of a high kind;</i>] <i>a faculty firmly rooted in the soul, seeking high things, and fleeing from base things.</i> (Ibn-Kemál, in TA.) See <span class=\"ar\">بَعِيدُ</span>, and <span class=\"ar\">هَمٌّ</span>. -b3- <span class=\"ar\">هِمَّةٌ</span> [<i>Mind; purpose; aspiration; desire; ambition; enterprise; emprise.</i>] -b4- <span class=\"ar\">هِمَّةٌ عَالِيَةٌ</span> <i>High purpose; ambition.</i></p><p><b class=\"ar\">هُمَامٌ</b> <i>An aspiring king:</i> (S, K:) <i>a magnanimous,</i> i. e. <i>courageous and liberal, chief.</i> (K.)</p><p><b class=\"ar\">هَمْهَامٌ</b> <i>A wild bird of the crow kind:</i> see <span class=\"ar\">صُرَدٌ</span>.</p><p><b class=\"ar\">هَامَةٌ</b> , pl. <span class=\"ar\">هَوَامُّ</span>, <i>Any venomous creeping thing</i> or <i>reptile</i> or <i>the like, that may be killed; such as the scorpion, and the serpent:</i> and (tropical:) <i>a louse;</i> (Mgh:) <i>what has deadly venom; as the scorpion:</i> (Az, Msb:) and sometimes, <i>what is noxious:</i> (Msb:) <i>any reptile or the like, from the louse to the serpent;</i> (AHát, Msb:) but its application to the louse is tropical: (Msb:) <i>any venomous or noxious reptile or the like; such as the scorpion, and the serpent:</i> the <i>like of serpents and scorpions;</i> because they creep (<span class=\"ar\">تَهِمُّ</span>, i. e. <span class=\"ar\">تَدِبّ</span>). (JK.)</p><p><b class=\"ar\">مُهِمٌّ</b> <i>A difficult, an arduous, a distressing, or an afflictive affair,</i> or <i>business:</i> syn. <span class=\"ar\">أَمْرٌ شَدِيدٌ</span>: (S:) and <span class=\"ar\">مُهِمَّاتٌ</span> signifies <span class=\"ar\">أُمُورُ شِدَادٌ</span>, (JK,) <i>affairs of difficulty:</i> and, <i>of importance.</i></p><p><b class=\"ar\">بَرَدٌ مُنْهَمٌّ</b> [app. <i>Dissolving hail-stones</i>]. (Mughnee and K, in explanations of <span class=\"ar\">كَ</span>.) See a verse in explanation of <span class=\"ar\">بِ</span> used redundantly, p. 144.</p>"},"هلل":{"mf":"الْهِلَالُ: القمر في أوّل ليلة والثّانية، ثم يقال له القمر، ولا يقال: له هِلَالٌ، وجمعه: أَهِلَّةٌ، قال الله تعالى: يَسْئَلُونَكَ عَنِ الْأَهِلَّةِ قُلْ هِيَ مَواقِيتُ لِلنَّاسِ وَالْحَجِ<br>[البقرة/ ١٨٩] وقد كانوا سألوه عن علّة تَهَلُّلِهِ وتغيّره. وشبّه به في الهيئة السّنان الذي يصاد به وله شعبتان كرمي الهلال، وضرب من الحيّات، والماء المستدير القليل في أسفل الرّكيّ، وطرف الرّحا، فيقال لكلّ واحد منهما: هِلَالٌ، وأَهَلَّ الهلال: رؤي، واسْتَهَلَّ: طلب رؤيته. ثم قد يعبّر عن الْإِهْلَالِ بِالاسْتِهْلَالِ نحو: الإجابة والاستجابة، والإهْلالُ: رفع الصّوت عند رؤية الهلال، ثم استعمل لكلّ صوت، وبه شبّه إِهْلَالُ الصّبيّ، وقوله: وَما أُهِلَّ بِهِ لِغَيْرِ اللَّهِ<br>[البقرة/ ١٧٣] أي: ما ذكر عليه غير اسم الله، وهو ما كان يذبح لأجل الأصنام، وقيل: الْإِهْلَالُ والتَّهَلُّلُ: أن يقول لا إله إلّا الله، ومن هذه الجملة ركّبت هذه اللّفظة كقولهم: التّبسمل والبسملة <strong>«١»</strong>، والتّحولق والحوقلة إذا قال بسم الله الرحمن الرحيم، ولا حول ولا قوّة إلّا بالله، ومنه الْإِهْلَالُ بالحجّ، وتَهَلَّلَ السّحاب ببرقه: تلألأ، ويشبّه في ذلك بالهلال، وثوب مُهَلَّلٌ: سخيف النّسج، ومنه شعر مُهَلْهَلٌ.<br>هَلْ: حرف استخبار، إما على سبيل الاستفهام، وذلك لا يكون من الله عزّ وجلّ: قال تعالى: قُلْ هَلْ عِنْدَكُمْ مِنْ عِلْمٍ فَتُخْرِجُوهُ لَنا<br>[الأنعام/ ١٤٨] وإمّا على التّقرير تنبيها، أو تبكيتا، أو نفيا. نحو: هَلْ تُحِسُّ مِنْهُمْ مِنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزاً<br><strong>[مريم/ ٩٨]. وقوله:</strong><br>هَلْ تَعْلَمُ لَهُ سَمِيًّا<br>[مريم/ ٦٥]، فَارْجِعِ الْبَصَرَ هَلْ تَرى مِنْ فُطُورٍ [الملك/ ٣] كلّ ذلك تنبيه على النّفي. وقوله تعالى: هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللَّهُ فِي ظُلَلٍ مِنَ الْغَمامِ وَالْمَلائِكَةُ<br>[البقرة/ ٢١٠]، لْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلائِكَةُ<br>[النحل/ ٣٣]، هَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ [الزخرف/ ٦٦]، هَلْ يُجْزَوْنَ إِلَّا ما كانُوا يَعْمَلُونَ [سبأ/ ٣٣]، هَلْ هذا إِلَّا بَشَرٌ مِثْلُكُمْ [الأنبياء/ ٣] قيل:<br>ذلك تنبيه على قدرة الله، وتخويف من سطوته.","mq":[["رفع صوت"],"الهاء واللام أصلٌ صحيح يدلُّ على رَفْع صَوت، ثم يُتَوسَّع فيه فيسمَّى الشئُ الذى يصوَّت عنده ببعض ألفاظِ الهاء واللام. ثم يشبَّه بهذا المسمَّى غيرُه فيسمَّى به.<br>والأصل قولهم أهَلَّ بالحجِّ: رفَعَ صوته بالتَّلبِيَة واستهلَّ الصَّبىُّ صارخاً (٢)<br>:<br>صوَّت عند وِلَادِه. قال ابنُ أحمر فى الإهلال:<br>يُهِلُّ"],"ln":"<p><b>4.</b> <b class=\"ar\">أَهْلَلْنَا هِلَالَ شَهْرِ كَذَا</b> : see <span class=\"ar\">سَلَخَ</span>.</p><p><b>10.</b> <b class=\"ar\">اِسْتَهَلَّ</b> : see a verse cited at the close of the first paragraph of art. <span class=\"ar\">ضحك</span>. -b2- See also a verse cited voce <span class=\"ar\">أَفْثَأَ</span>. -b3- See <span class=\"ar\">مُسْتَهَلٌّ</span>.</p><p><b class=\"ar\">هَلْ</b> may be originally <span class=\"ar\">هَلْو</span> or <span class=\"ar\">هَلْى</span> or <span class=\"ar\">هَلّ</span>: (Akh, in S, voce <span class=\"ar\">بل</span>:) see <span class=\"ar\">بَلْ</span>. -b2- <span class=\"ar\">هَلْ</span> followed by <span class=\"ar\">إِلَى</span>: see the latter. -b3- <span class=\"ar\">حَىّ هَلَ</span>: see <span class=\"ar\">حى</span>. -b4- <span class=\"ar\">هَلَّا</span>: see <span class=\"ar\">حَضَّةٌ</span> and <span class=\"ar\">عَنْ</span>, latter part, and <span class=\"ar\">لَوْلَا</span>, and <span class=\"ar\">أَلَّا</span>.</p><p><b class=\"ar\">هَلَّةٌ</b> : see <span class=\"ar\">بَلَّةٌ</span>.</p><p><b class=\"ar\">الهِلاَلُ</b> <i>The new moon;</i> or <i>the moon when it is termed</i> <span class=\"ar\">هِلاَل</span>: it may be explained as meaning, generally, <i>the moon when near the sun,</i> or <i>moon a little after or before the change.</i> -b2- See <span class=\"ar\">سَمَا</span>.</p><p><b class=\"ar\">مُسْتَهَلُّ الشَّهْرِ</b> <i>The first night of the lunar month.</i> (Msb.)</p>"},"هنأ":{"mf":"الْهَنِيءُ: كلّ ما لا يلحق فيه مشقّة، ولا يعقب وخامة. وأصله في الطّعام يقال: هَنِئَ الطّعامُ فهو هَنِيءٌ. قال عزّ وجلّ: فَكُلُوهُ هَنِيئاً مَرِيئاً<br>[النساء/ ٤]، كُلُوا وَاشْرَبُوا هَنِيئاً بِما أَسْلَفْتُمْ [الحاقة/ ٢٤]، كُلُوا وَاشْرَبُوا هَنِيئاً بِما كُنْتُمْ تَعْمَلُونَ [المرسلات/ ٤٣]، والهِنَاءُ:<br>ضرب من القطران، يقال: هَنَأْتُ الإبلَ، فهي مَهْنُوءَةٌ.","mq":[["اصابة خير من غير مشقة"],"الهاء والنون والهمزة: يدلُّ على إصابةِ خيرٍ من غير مشقّة.<br>فالهَنْ ء: العَطِيَّةُ، وهو مصدرٌ والاسم الهِنْ ء. والهَنِئ: الأمر يأتيك من غير مشقة. وما كان هذا الطّعامُ هنيئاً ولقد هَنُؤ. وهَنِئت الماشيةُ: أصابَتْ حَظًّا من بَقْل. وإبُلٌ هَنْأَى (٢)<br>. وأمّا الهِناءُ فضَربٌ من القَطِران. هَنَأْتُ البَعِي"],"ln":"<p><b>1.</b> <b class=\"ar\">هَنُؤَ</b> , aor. <b class=\"ar\">هَنُاَ</b> , inf. n. <span class=\"ar\">هَنَآءَةٌ</span>; and <span class=\"ar\">هَنِئَ</span>, aor. <b class=\"ar\">هَنَاَ</b> ; <i>It came,</i> or <i>happened, without inconvenience,</i> or <i>trouble:</i> (K:) [<i>it was pleasant,</i> or <i>productive of enjoyment:</i> see what immediately follows]. -b2- <span class=\"ar\">هَنُؤَ الطَّعَامُ</span> (S, K *) aor. <b class=\"ar\">هَنُاَ</b> , inf. n. <span class=\"ar\">هَنَآءَةٌ</span> (S, K) and <span class=\"ar\">هَنَأَةٌ</span> and <span class=\"ar\">هَنْءٌ</span>, (K,) or <span class=\"ar\">هِنْءٌ</span> (as in some copies of the K, and in the L); epithet <span class=\"ar\">هَنِىْءٌ</span>; (S;) and <span class=\"ar\">هَنِئَ</span>, (Akh, S, K,) aor. <b class=\"ar\">هَنَاَ</b> , inf. n. <span class=\"ar\">هَنْءٌ</span>; (TA;) and <span class=\"ar\">هَنَأَ</span>, aor. <b class=\"ar\">هَنِاَ</b> , (Lth,) <i>The food was,</i> or <i>became, pleasant,</i> or <i>productive of enjoyment, to the eater:</i> or <i>easy to swallow; not attended by trouble:</i> [<i>agreeable:</i>] or <i>not succeeded by harm, even after digestion.</i> (Z, cited voce <span class=\"ar\">مَرُؤَ</span>.) -b3- <span class=\"ar\">هَنَأَنِى الطَّعَامُ</span>, (Akh, S, K), and <span class=\"ar\">هَنَأَ لِىَ</span>, aor. <b class=\"ar\">هَنِاَ</b> and <b class=\"ar\">هَنَاَ</b> (S, K) and <b class=\"ar\">هَنُاَ</b> , (K,) unexampled, says Akh, in the class termed mahmooz, (S,) [though <span class=\"ar\">بَرَأَ</span> and <span class=\"ar\">قَرَأَ</span> are similar with respect to their having damm to the aor.,] inf. n. <span class=\"ar\">هَنْءٌ</span> and <span class=\"ar\">هِنْءٌ</span>, (S, K,) [<i>The food was pleasant,</i> or <i>productive of enjoyment, to me:</i> or <i>easy to swallow; &amp;c.:</i> see <span class=\"ar\">هَنُؤَ</span>]. -b4- <span class=\"ar\">هَنَأَنِى الطّعامُ وَمَرأَنِى</span>: see art. <span class=\"ar\">مرأ</span>. -b5- <span class=\"ar\">هَنَأَهُ</span> <span class=\"ar\">ذٰلِكَ</span>, and <span class=\"ar\">هنأ لَهُ ذلك</span> <i>That</i> (thing) <i>was pleasant,</i> or <i>productive of enjoyment, to him; &amp;c.</i> (TA.) [See <span class=\"ar\">هَنُؤَ</span>.] -b6- <span class=\"ar\">هَنَأَنِى خَبَرُ فُلَانٍ</span> <i>The news of such a one was pleasant to me to hear.</i> (TA.) -b7- <span class=\"ar\">هَنِئَ الطّعَامَ</span>, aor. <b class=\"ar\">هَنَاَ</b> ; and <span class=\"ar\"> <span class=\"ar\">تهنّأ</span>بَالطّعامِ</span>, (S, K,) and <span class=\"ar\">تهنّأ الطّعام</span>, and <span class=\"ar\">استهنأهُ</span>, (TA,) [<i>He enjoyed the food; found it pleasant,</i> or <i>productive of enjoyment;</i> &amp;c.: see <span class=\"ar\">هَنُؤَ</span>:] <i>he found the food to be productive of no evil result, and not attended by inconvenience.</i> (TA.) -b8- <span class=\"ar\">هَنِئَ</span>, (AZ, S, K,) aor. <b class=\"ar\">هَنَاَ</b> , inf. n. <span class=\"ar\">هَنَأٌ</span> and <span class=\"ar\">هَنْءٌ</span>, (K,) <i>He</i> (a beast) <i>lighted upon a good piece of herbage, but did not satiate himself therewith.</i> (AZ, S, K.) -b9- <span class=\"ar\">أَكَلْنَا هٰذَا الطَّعَامَ حَتَّى هَنِئْنَا مِنْهُ</span> <i>We ate this food until we were satiated with it.</i> (TA.) -b10- <span class=\"ar\">هَنِئَتِ</span> <span class=\"ar\">الإِبِلُ</span> <i>The camels were satiated</i> with herbage. (TA.) -b11- <span class=\"ar\">هَنِئَ بِهِ</span> <i>He rejoiced in him,</i> or <i>it.</i> (K.) -b12- <span class=\"ar\">هَنَأَنَا اللّٰهُ الطَّعَامَ</span> [<i>God made the food pleasant,</i> or <i>productive of enjoyment, to us: &amp;c.: made us to enjoy it:</i> see <span class=\"ar\">هَنُؤَ</span>]. (TA.) -b13- <span class=\"ar\">هَنَأَتْنِيهِ</span> <span class=\"ar\">العَافِيَةُ</span> [<i>Health made it pleasant,</i> or <i>productive of enjoyment, to me:</i> &amp;c.]. (K.) -b14- <span class=\"ar\">لِيَهْنِئْكَ الفَارِسُ</span> [<i>May the horseman give thee joy:</i> a form of congratulation on the exploits of a horseman; i. e., I congratulate thee on the exploits of the horseman]: also written and pronounced <span class=\"ar\">لِيَهْنِيكَ</span>: <span class=\"ar\">ليهنك</span>, though it occurs in a trad., pronounced <span class=\"ar\">لِيَهْنِكَ</span> or <span class=\"ar\">لِيَهْنَكَ</span>, (but which pronunciation is to be preferred is disputed,) is said to be a vulgarism, and not allowable. (TA.) -b15- <span class=\"ar\">هَنَأَهُ</span>, aor. <b class=\"ar\">هَنَاَ</b> (K) [and app., <b class=\"ar\">هَنِاَ</b> (see <span class=\"ar\">هَانِئٌ</span>)], inf. n. <span class=\"ar\">هَنْءٌ</span>, (TA,) <i>He fed him;</i> or <i>gave him to eat.</i> (K.) -b16- <span class=\"ar\">هَنَأَهُ</span>, aor. <b class=\"ar\">هَنَاَ</b> and <b class=\"ar\">هَنِاَ</b> , (S, K,) inf. n. <span class=\"ar\">هَنْءٌ</span>; (S;) and <span class=\"ar\"> <span class=\"ar\">اهنأهُ</span></span>; (IAar, K;) <i>He gave him,</i> or <i>bestowed upon him:</i> (S, K:) <i>gave him plentifully.</i> (TA.) -b17- <span class=\"ar\">هَنَأَ الطَّعَامَ</span>, inf. n. <span class=\"ar\">هَنْءٌ</span> and <span class=\"ar\">هِنْءٌ</span> (K) and <span class=\"ar\">هَنَآءَةٌ</span> (as in some copies of the K) or <span class=\"ar\">هَنَأَةٌ</span> (as in others) or <span class=\"ar\">هِنَأَةٌ</span> (as in others) or <span class=\"ar\">هَنْأَةٌ</span> (as in the CK), <i>He made the food good; qualified it properly; seasoned it:</i> syn. <span class=\"ar\">أَصْلَحَهُ</span>. (K.) -b18- <span class=\"ar\">هَنَأَ مَالَهُ</span>, (TA,) and <span class=\"ar\"> <span class=\"ar\">اهتنأ</span>ماله</span>, (K,) <i>He put his property in a right,</i> or <i>good, state.</i> (K.) -b19- <span class=\"ar\">هَنَأَ القَوْمَ</span>, aor. <b class=\"ar\">هَنَاَ</b> , <i>He nourished,</i> or <i>maintained, the people;</i> (S;) <i>satisfied their wants; bestowed upon them.</i> (TA.) Ex. <span class=\"ar\">هَنَأَهُمْ شَهْرَيْنِ</span> [<i>He maintained them two months</i>]. Hence the proverb quoted in illustration of the word <span class=\"ar\">هَانِئٌ</span>, accord. to the second reading. (TA) -b20- <span class=\"ar\">هَنَأَهُ</span> <i>He aided, succoured,</i> or <i>defended, him.</i> (K.) -A2- <span class=\"ar\">هَنَأَ الإِبِلَ</span>, aor. <b class=\"ar\">هَنَاَ</b> (S, K,) and <b class=\"ar\">هَنِاَ</b> and <b class=\"ar\">هَنُاَ</b> (K: dev. from constant rule as shown above: TA), inf. n. <span class=\"ar\">هَنَأٌ</span> and <span class=\"ar\">هَنْءٌ</span>, (TA,) <i>He smeared the camels with</i> <span class=\"ar\">هِنَآء</span>, which is <i>tar,</i> or <i>liquid pitch,</i> syn. <span class=\"ar\">قَطِرَان</span>, (AZ, S, K,) or <i>a kind thereof,</i> (TA,) [as a remedy for, or preservative against, the mange, or scab]. -b2- <span class=\"ar\">لَيْسَ الهَنْءُ بِالدَّسِّ</span> <i>The smearing of a camel</i> [<i>all over</i>] <i>with</i> <span class=\"ar\">هِنَآء</span> <i>is not</i> [<i>merely</i>] <i>smearing the cavities under the shoulders, and the like,</i> which the mange, or scab, more quickly attacks. A proverb, applied to him who does not a thing thoroughly. (TA.) -b3- See 2.</p><p><b>2.</b> <b class=\"ar\">هَنَّاهُ وَمَنَّاهُ</b> (in a trad. respecting the prostration for inattention) <i>He</i> (the devil) <i>made him to think of pleasant things,</i> or <i>things productive of enjoyment, and of things wished for,</i> or <i>objects of desire,</i> in his prayer. The former verb is pronounced thus to assimilate it to the latter. (TA.) -b2- <span class=\"ar\">هنّأهُ بِالأَمْرِ</span>, inf. n. <span class=\"ar\">تَهْنِئَةٌ</span> and <span class=\"ar\">تَهْنِىْءٌ</span>; (S, K;) and <span class=\"ar\"> <span class=\"ar\">هَنَأَهُ</span></span>, (K,) inf. n. <span class=\"ar\">هَنْءٌ</span>; (TA;) <i>He congratulated him on the thing,</i> (S, K,) such as the possession of a government, &amp;c.: (S:) <i>he said to him</i> <span class=\"ar\">لِيَهْنِئْكَ</span> [<i>May it give thee joy</i>]. (K.) -b3- [When the agent of the verb is God, the meaning necessarily is, <i>He granted him enjoyment in the thing; made him to have enjoyment in it.</i>] -b4- <span class=\"ar\">هُنِّئْتَ وَلَا تُنْكَهْ</span>: see art. <span class=\"ar\">نكأ</span>.</p><p><b>4.</b> <b class=\"ar\">أَهْنَاَ</b> see 1.</p><p><b>5.</b> <b class=\"ar\">تهنّأ</b> <i>He gave many gifts.</i> (IAar.) -b2- <span class=\"ar\">تهنّأ</span> <span class=\"ar\">بِكَذَا</span> [unless it be a mistake for <span class=\"ar\">تهيّأ</span>, as IbrD suggests, which I think not improbable, though mentioned in this art. in the TA] <i>He prided himself in such a thing:</i> syn. <span class=\"ar\">تمرّأ</span> and <span class=\"ar\">تغيّظ</span> and <span class=\"ar\">تسمّن</span> and <span class=\"ar\">تخيّل</span> and <span class=\"ar\">تزيّن</span>. (TA.) -b3- See 1.</p><p><b>8.</b> <b class=\"ar\">إِهْتَنَاَ</b> see 1.</p><p><b>10.</b> <b class=\"ar\">استهنأهُ</b> <i>He asked him for aid, succour,</i> or <i>defence.</i> (K.) -b2- <i>He asked him for a gift.</i> (K, TA.) -b3- <i>He conceded to him,</i> or <i>gave him, a part of his dues,</i> or <i>rights.</i> (TA.) -b4- See 1.</p><p><b class=\"ar\">هِنْءٌ</b> <i>A gift.</i> (S, K.) -A2- <i>A part of the night.</i> (K.) -A3- <span class=\"ar\">هِنْءٌ</span> subst. from <span class=\"ar\">هَنَأَ الإِبِلَ</span>; (K;) i. e., The <i>smearing with</i> <span class=\"ar\">هِنَآء</span>. (MF.)</p><p><b class=\"ar\">إِبِلٌ هَنْأَى</b> <i>Camels which have lighted upon a good piece of herbage, but are not satiated therewith.</i> (K.)</p><p><b class=\"ar\">هِنَآءٌ</b> <i>Tar,</i> or <i>liquid pitch;</i> syn. <span class=\"ar\">قَطِرَانٌ</span>: (S, K:) or <i>a kind thereof.</i> (TA.) See also <span class=\"ar\">نُورَةٌ</span>; and <span class=\"ar\">قالِبٌ</span>. -A2- <span class=\"ar\">هِنَآءٌ</span> dial. var. of <span class=\"ar\">إِهَانٌ</span>, (K,) or formed from the latter by transposition, (TA,) <i>A raceme of a palm-tree.</i> (AHn, K.) [See <span class=\"ar\">إِهَانٌ</span>.]</p><p><b class=\"ar\">هَنِىْءٌ</b> <i>What comes</i> or <i>happens to one without inconvenience,</i> or <i>trouble:</i> (S, K:) [<i>what is pleasant,</i> or <i>productive of enjoyment; an unalloyed gratification,</i> i. e., <i>a thing that gives unalloyed enjoyment;</i> see what follows:] as also <span class=\"ar\"> <span class=\"ar\">مَهْنَأٌ</span></span>, (K,) a subst., sometimes written and pronounced <span class=\"ar\">مَهْنَا</span>; pl. <span class=\"ar\">مَهَانِئُ</span>, sometimes written and pronounced <span class=\"ar\">مَهَانٍ</span>. (TA.) [See <span class=\"ar\">مهنأ</span> also below.] -b2- <i>Pleasant,</i> or <i>productive of enjoyment, to the eater:</i> or <i>easy to swallow; not attended by trouble:</i> or <i>not succeeded by harm, even after its digestion.</i> (Z, cited voce <span class=\"ar\">مَرُؤَ</span>.) -b3- <span class=\"ar\">هَنِيْئًا مَرِيْئًا</span> [May it be, or Eat it, or Drink it, <i>with enjoyment, and with wholesome result:</i> or <i>with ease in the swallowing, and with quickness in digesting: &amp;c.:</i> see <span class=\"ar\">مَرُؤَ</span>]. (S.) -b4- <span class=\"ar\">هَنِيْئًا لَهُ ذٰلِكَ</span> [<i>May that be productive of enjoyment to him!</i>]. (TA.) -b5- <span class=\"ar\">هَنِيْئًا</span> and <span class=\"ar\">مَرِيْئًا</span> are of the number of epithets which are employed after the manner of inf. ns. significant of a prayer or good wish, governed in the acc. case by a verb understood. (Sb.)</p><p><b class=\"ar\">هُنَيْئَةٌ</b> (K) and <span class=\"ar\">هُنَيَّةٌ</span> and <span class=\"ar\">هُنَيْهَةٌ</span> (the second is the most usual; and the third is said to be formed by substituting <span class=\"ar\">ه</span> for <span class=\"ar\">ء</span>; but accord. to some, the word is incorrectly written with <span class=\"ar\">ء</span>, [so says F,] and is a dim. formed from <span class=\"ar\">هَنْوَةٌ</span>, which becomes first <span class=\"ar\">هُنَيْوَةٌ</span>, and then <span class=\"ar\">هُنَيَّةٌ</span>: see art. <span class=\"ar\">هنو</span>:) (TA:) <i>A little; a little while.</i> (K.)</p><p><b class=\"ar\">هَانِئٌ</b> <i>A servant.</i> (K.) -b2- <span class=\"ar\">هَانِئًا</span> occurs in this sense in a trad.; but the reading commonly known is <span class=\"ar\">مَاهِنًا</span>. If right, it is an act. part. n. from <span class=\"ar\">هنأ</span> “ he gave. ” (TA.) -b3- <span class=\"ar\">إِنَّمَا سُمِّيتَ هَانِئًا</span> <span class=\"ar\">لِتَهْنِئَ</span>, or <span class=\"ar\">لِتَهْنَأَ</span>; the former is the reading of El-Umawee; the latter, of Ks; <i>Thou art only named Háni</i> (Giver, or Nourisher,) <i>that thou mayest give,</i> accord. to both readings; or <i>that thou mayest nourish,</i> or <i>maintain, and supply people's wants;</i> <span class=\"ar\">لتعول وتكفى</span>: (TA:) [such is said to be the meaning of <span class=\"ar\">لتهنأ</span> here:] and accord. to El-Umawee, <span class=\"ar\">لتهنئ</span> signifies <span class=\"ar\">لِتُمْرِئَ</span>, (S,) [which is app. the same as <span class=\"ar\">لتعول</span>]. A proverb: said to him who is known for his beneficence, in order that he may continue to do as he has been wont. (TA.)</p><p><b class=\"ar\">مَهْنَأٌ</b> : see <span class=\"ar\">هَنِىءٌ</span>. -b2- <span class=\"ar\">لَكَ المَهْنَأُ</span>, (S,) and <span class=\"ar\">المَهْنَا</span>, (TA,) [<i>Unalloyed gratification to thee!</i>] -b3- <span class=\"ar\">لَكَ المَهْنَأُ وَعَلَيْهِ الوِزْرُ</span> [<i>To thee be unalloyed gratification, and on him be the burden,</i> or <i>sin</i>]: said, accord. to a trad., to one who asked whether he should accept an invitation to eat the food of one who received unlawful interest or profit; and also said with respect to eating the food of a tyrannical intendant. (TA.)</p><p><b class=\"ar\">مَهْنُوْءٌ</b> A camel <i>smeared with</i> <span class=\"ar\">هِنَاء</span>. (S.)</p>"},"هزز":{"mf":"الْهَزُّ: التّحريك الشّديد، يقال: هَزَزْتُ الرّمح فَاهْتَزَّ وهَزَزْتُ فلانا للعطاء. قال تعالى: وَهُزِّي<br><br>إِلَيْكِ بِجِذْعِ النَّخْلَةِ [مريم/ ٢٥]، فَلَمَّا رَآها تَهْتَزُّ<br>[النمل/ ١٠]، واهْتَزَّ النّبات: إذا تحرّك لنضارته، قال تعالى: فَإِذا أَنْزَلْنا عَلَيْهَا الْماءَ اهْتَزَّتْ وَرَبَتْ<br>[الحج/ ٥] واهْتَزَّ الكوكب في انقضاضه، وسيف هَزْهَازٌ، وماء هُزَهِزٌ ورجل هُزَهِزٌ: خفيف.","mq":[["اضطراب في شي وحركة"],"الهاء والزاء: أصلٌ يدلُّ على اضطرابٍ فى شئ وحركة.<br>وهَزَزْت القناةَ فاهتزَّتْ. واهتَزَّ النَّباتُ، وهَزَّتْه الرِّيح. وهزَّ الحادى الإبلَ بحُدائِهِ واهتزَّتْ هى فى سيرها. وهَزِيزُ الرِّيح: حرَكتُها وصوتُها.<br>ومن الباب الهَزَاهِزُ (١)<br>: الفِتَنُ يَهْتَزُّ فيها النّاس. وسيفٌ هَزهازٌ وهُزْهُزٌ:<br>صافٍ حسنُ"],"ln":"<p><b>1.</b> <b class=\"ar\">هَزَّهُ</b> , (S, A, Msb, K,) and <span class=\"ar\">هَزَّ بِهِ</span>, [respecting which see what is said on an ex. below,] (A, K,) aor. <b class=\"ar\">هَزُزَ</b> , (A, Msb,) inf. n. <span class=\"ar\">هَزٌّ</span>, (S, A, Msb,) [<i>He shook it;</i>] <i>he put it in motion,</i> or <i>into a state of commotion;</i> (S, A, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">هزّزهُ</span></span>, (S, K,) and <span class=\"ar\">هزّز بِهِ</span>, (TA,) inf. n. <span class=\"ar\">تَهْزِيزٌ</span>; (K;) and <span class=\"ar\"> <span class=\"ar\">هَزْهَزَهُ</span></span>, (S, K,) inf. n. <span class=\"ar\">هَزْهَزَةٌ</span>; (TA;) meaning, <i>he made it move by pulling and pushing;</i> or <i>he made it move to the right and left:</i> or, accord. to Er-Rághib, <i>he did so with violence,</i> or <i>vehemence.</i> (TA.) It is said that <span class=\"ar\">هَزَّ</span> is trans. by itself, and by means of <span class=\"ar\">بِ</span>, like <span class=\"ar\">أَخَذَ</span> and <span class=\"ar\">تَعَلَّقَ</span>: it is trans. in the latter manner in the Kur., [xix. 25,] where it is said, <span class=\"ar\">وَهُزِّى إِلَيْكِ بِجِذْعِ النَّخْلَةِ</span> [<i>And shake thou towards thee the trunk of the palm-tree</i>], i. e. <span class=\"ar\">حَرِّكِى</span>: but ISd says, that the verb is here made trans. by means of <span class=\"ar\">ب</span> because it is used in the sense of <span class=\"ar\">جُرِّى</span>: and MF says, that, properly, it is not trans. by means of <span class=\"ar\">ب</span>. (TA.) You say, <span class=\"ar\">هَزَّ السَّيْفَ وَغَيْرَهُ</span> [<i>He shook the sword,</i> &amp;c.] (A.) And <span class=\"ar\">هَزَّتِ الرِّيحُ الأَغْصَانَ</span>, (A,) and <span class=\"ar\">الشَّجَرَ</span>, and <span class=\"ar\"> <span class=\"ar\">هَزَّزَتْهَا</span></span>, (S,) [<i>The wind shook the branches,</i> and <i>the trees,</i>] and <span class=\"ar\">هَزَّتِ النَّبَاتَ</span> <i>it shook</i> (<span class=\"ar\">حَرَّكَت</span>) <i>the plants:</i> but this has also a tropical signification, which see below. (TA.) -b2- You say also, <span class=\"ar\">أُهُزُّ</span> <span class=\"ar\">كَتِفِى</span>, and <span class=\"ar\">مَنْكِبِى</span>, (tropical:) [lit., <i>I shake my shoulderblade,</i> and <i>my shoulder-joint;</i>] meaning, <i>I walk with an elegant and a proud and self-conceited gait; I behave with pride and self-conceitedness.</i> (Mgh.) And <span class=\"ar\">هَزَّ عِطْفَيْهِ لِكَذَا</span> (tropical:) [lit., <i>He shook his sides at such a thing</i> app. meaning, <i>he was active,</i> or <i>prompt, and brisk,</i> or <i>was moved with alacrity, to do such a thing,</i> or <i>he was rejoiced at such a thing:</i> like <span class=\"ar\">اِهْتَزَّ <span class=\"ar\">لَهُ</span></span>, q. v.]: and in like manner, <span class=\"ar\">هَزَّ مَنْكِبَيْهِ</span>. (A.) [In like manner also you say,] <span class=\"ar\">هَزَّ مَا رَأَيْتُ مِنْ عِطْفَى</span> [app. meaning, accord. to a gloss cited by De Sacy in his Anthol. Gr. Ar., p. 309, (tropical:) <i>What I saw rejoiced me:</i> or, as rendered by him, p. 286, <i>ce dont j'étois temoin, réveilla en moi le courage.</i>] (Z, in his preface to the Keshsháf.) And <span class=\"ar\">هَزَّ الإِبِلَ</span>, (S, A, K,) aor. <b class=\"ar\">هَزُزَ</b> , inf. n. <span class=\"ar\">هَزٌّ</span> (TA) and <span class=\"ar\">هَزِيزٌ</span>, (S, K, TA,) (tropical:) <i>He</i> (a man urging his beasts by singing) <i>made the camels to be brisk,</i> or <i>sprightly,</i> by his singing to urge them. (S, * A, K.) And <span class=\"ar\">هَزَّهَا السَّيْرُ</span> (tropical:) [<i>The journeying made them to be brisk,</i> or <i>sprightly</i>]. (TA.) And <span class=\"ar\">هَزَّ بِهِ السَّيْرُ</span> (assumed tropical:) <i>The pace brought him on quickly.</i> (TA.) And <span class=\"ar\">هَزَزْتُ فُلَانًا لِخَيْرٍ</span> (assumed tropical:) <i>I made such a one to rejoice</i> [or <i>to be prompt and brisk</i> (see the quasi-pass., 8,) <i>to do good</i>]: said of a generous man: (En-Nadr, TA:) and <span class=\"ar\"> <span class=\"ar\">هَزْهَزْتُهُ</span></span> and <span class=\"ar\">هَزْهَزْتُ</span> <span class=\"ar\">مِنْهُ</span> [app. signify the same]. (A.) And <span class=\"ar\">جَآءَ فُلَانٌ</span> <span class=\"ar\">يَهُزُّ المَشْىَ</span>, and <span class=\"ar\">يَهُضُّهُ</span>, (assumed tropical:) <i>Such a one came walking impulsively:</i> (JK in art. <span class=\"ar\">هض</span>:) or <i>with a graceful gait, impulsively.</i> (Ibn-El-Faraj, TA, in art. <span class=\"ar\">هض</span>.) -b3- You also say, of a plant, or herbage, <span class=\"ar\"> <span class=\"ar\">هَزَّتْهُ</span>الرِّيَاحُ وَالأَمْطَارُ</span> (tropical:) <i>The winds and the rains made it to become tall.</i> (A, TA. *) -b4- <span class=\"ar\">هَزَّ الكَوْكَبُ</span>: see 8. -b5- [<span class=\"ar\">مَهَزَّةٌ</span> seems to be an inf. n. of <span class=\"ar\">هَزَّهُ</span>.] You say <span class=\"ar\">رُمْحٌ لَدْنُ المَهَزَّةِ</span> (S, TA, art. <span class=\"ar\">عرص</span>,) [app. for <span class=\"ar\">عِنْدَ المَهَزَّةِ</span>] <i>A spear that vibrates,</i> or <i>quivers, when shaken.</i> (TA, ibid.)</p><p><b>2.</b> <b class=\"ar\">هَزَّزَ</b> see 1, in two places.</p><p><b>5.</b> <b class=\"ar\">تَهَزَّزَ</b> see 8.</p><p><b>8.</b> <b class=\"ar\">اهتزّ</b> , (inf. n. <span class=\"ar\">اِهْتِزَازٌ</span>,) quasi-pass. of <span class=\"ar\">هَزَّهُ</span>, (TA,) [<i>It shook;</i> or <i>quivered;</i>] <i>it became in motion,</i> or <i>in a state of commotion;</i> (S, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">تهزّز</span></span>, (S, K,) quasi-pass. of <span class=\"ar\">هزّزهُ</span>; (TA;) and <span class=\"ar\"> <span class=\"ar\">تَهَزْهَزَ</span></span>, (S, A, K,) [quasi-pass. of <span class=\"ar\">هَزْهَزَهُ</span>; meaning, accord. to explanations of <span class=\"ar\">هَزَّهُ</span> in the TA, <i>it became moved by being pulled and pushed;</i> or <i>it became moved to the right and left:</i> or <i>it became so moved with violence,</i> or <i>vehemence.</i>] -b2- <span class=\"ar\">اهتزّ المَِآءُ فى جَزْيِهِ</span> (tropical:) [app. <i>the water quivered in its running</i>]: and <span class=\"ar\">الكَوْكَبُ فِى ٱنْقِضَاضِهِ</span> (tropical:) [<i>the star in its shooting,</i> or <i>darting, down</i>]: (S, A, TA:) and <span class=\"ar\">اهتزّ الكَوْكَبُ</span> (tropical:) <i>the star shot,</i> or <i>darted, down</i> [app. <i>with a quivering motion</i>]; (O, L, TA;) as also <span class=\"ar\">هَزَّ</span>. (A, K.) -b3- <span class=\"ar\">اهتزّ المَوْكِبُ</span> (tropical:) <i>The procession,</i> or <i>cavalcade, went quickly:</i> (En-Nadr, TA:) or <i>made a noise and clamour.</i> (S.) -b4- <span class=\"ar\">اهتزّت الإِبِلُ</span> (tropical:) <i>The camels,</i> being urged on by the singing of their driver, <i>became brisk,</i> or <i>sprightly.</i> (S, * A, TA.) You say also, <span class=\"ar\">اهتزّ لِأَمْرٍ</span> (tropical:) <i>He was,</i> or <i>became, active,</i> or <i>prompt, and brisk,</i> or <i>cheerfully excited, at a thing,</i> or <i>to do a thing.</i> (TA.) [Ex.] <span class=\"ar\">اهتزّ لِخَيْرٍ</span> (tropical:) <i>He rejoiced</i> [or <i>was active</i> or <i>prompt,</i> &amp;c., <i>to do good</i>]: said of a generous man. (En-Nadr, TA.) And <span class=\"ar\">هُوَ يَهْتَزُّ لِلْمَعْرُوفِ</span> (tropical:) [<i>He rejoices,</i> or is <i>active,</i> or <i>prompt,</i> &amp;c., <i>to do what is beneficent,</i> or <i>kind</i>]. (A.) [Hence the saying,] <span class=\"ar\">فُلَانٌ لَا يَهْتَزُّ وَلٰكِنَّهُ يَكُتَزُّ</span> (tropical:) [<i>Such a one does not rejoice,</i> &amp;c., <i>to give, but he shrinks from giving</i>]. (A, TA, art. <span class=\"ar\">كز</span>.) [Hence also,] <span class=\"ar\">إِهُتَزَّ عَرْشُ الرَّحْمَانِ لِمَوْتِ سَعْدٍ</span> (tropical:) <i>The empyrean of the Compassionate rejoiced at the death of Saad;</i> (En-Nadr, IAth, K, TA;) meaning Saad Ibn-Mo'ádh; (TA;) i. e., when he [meaning his soul] was taken up; (IAth, TA;) because of the honour in which he was held by his Lord; (K;) or <i>the inhabitants of the empyrean rejoiced at his death:</i> these words occur in a trad., of which there is another relation, <span class=\"ar\">اهتزّ العَرْشُ</span>: and some say, that by <span class=\"ar\">العرش</span> is meant the bier upon which Saad was removed to his grave. (TA.) You also say, <span class=\"ar\"> <span class=\"ar\">تَهَزْهَزَ</span>إِلَيْهِ قَلْبِى</span> (tropical:) <i>My heart became moved by a cheerful,</i> or <i>joyful, affection towards him.</i> (K, TA.) -b5- <span class=\"ar\">اهتزّ النَّبَاتُ</span> (tropical:) <i>The plant,</i> or <i>herbage, became tall.</i> (A, TA.) -b6- <span class=\"ar\">اهتزّت الأَرْضُ</span> (tropical:) <i>The land produced plants,</i> or <i>herbage:</i> (A:) or <i>became put in motion, and produced plants,</i> or <i>herbage.</i> (TA.)</p><p><b>R. Q. 1.</b> <b class=\"ar\">هَزْهَزَهُ</b> , and <span class=\"ar\">هَزْهَزْتُهُ</span>, and <span class=\"ar\">هَزْهَزْتُ مِنْهُ</span>: see 1. -b2- Also, the first, (inf. n. <span class=\"ar\">هَزْهَزَةٌ</span>, TA,) (tropical:) <i>He subdued him,</i> or <i>rendered him submissive;</i> syn <span class=\"ar\">ذَلَّلَهُ</span>. (K, * TA.)</p><p><b>R. Q. 2.</b> <b class=\"ar\">تَهَزْهَزَ</b> : see 8, in two places. -b2- Also, (tropical:) <i>He became subdued,</i> or <i>submissive;</i> quasi-pass. of <span class=\"ar\">هَزْهَزَهُ</span>. (TA.)</p><p><b class=\"ar\">هَزَّةٌ</b> (tropical:) <i>Brisk and rejoicing to do evil</i> or <i>mischief;</i> applied to a woman: pl. <span class=\"ar\">هَزَّاتٌ</span>. (A, TA.)</p><p><b class=\"ar\">هِزَّةٌ</b> (tropical:) <i>Briskness,</i> or <i>sprightliness:</i> (S, K:) and (tropical:) <i>briskness, sprightliness, alacrity,</i> or <i>cheerfulness, disposing one to promptness in acts of liberality, kindness, and beneficence;</i> or <i>liberality of disposition;</i> syn. <span class=\"ar\">أَرْيَحِيَّةٌ</span>; (K;) and [in like manner] <span class=\"ar\"> <span class=\"ar\">هَزِيزٌ</span></span> (tropical:) <i>briskness,</i> or <i>sprightliness, of camels when urged on by the singing of their driver.</i> (A, TA.) -b2- (tropical:) <i>A kind of pace,</i> or <i>manner of going, of camels;</i> (As, K;) <i>when the train goes quickly:</i> (As, * En-Nadr, TA:) or <i>a state of commotion of a train</i> or <i>procession</i> or <i>cavalcade:</i> (ISd, TA.) or the <i>confused sound thereof.</i> (IDrd, TA.) -b3- -b4- (tropical:) The <i>sound of the boiling of a cooking-pot:</i> (S, K:) (assumed tropical:) the <i>reiterating sound of thunder;</i> as also <span class=\"ar\"> <span class=\"ar\">هَزِيزٌ</span></span> (K:) which latter has likewise the following similar significations: (assumed tropical:) <i>a sound,</i> or <i>noise;</i> (K:) as, for instance, <i>a sound,</i> or <i>noise, of turning</i> of a mill; as also <span class=\"ar\">أَزِيزَّ</span> [inf. n. of <span class=\"ar\">أَزَّ</span>]: (TA:) and (tropical:) the <i>murmuring of the wind</i> (S, K) <i>when it shakes the trees:</i> (S:) or <i>the sound of the blowing of the wind:</i> (TA:) or the <i>lightness of the wind, and</i> the <i>quickness of its blowing.</i> (A, TA.)</p><p><b class=\"ar\">هَزِيزٌ</b> : see <span class=\"ar\">هِزَّةٌ</span>.</p><p><b class=\"ar\">هَزَائِزُ</b> (assumed tropical:) <i>Difficulties, afflictions,</i> or <i>calamities:</i> [a pl.] having no singular. (Th, TA.)</p><p><b class=\"ar\">كَوْكَبٌ هَازٌّ</b> (tropical:) [<i>A star shooting,</i> or <i>darting, down;</i> or <i>quivering in doing so:</i> see 8]. (S, TA.)</p><p><b class=\"ar\">هَزْهَزَةٌ</b> : see R. Q. 1, of which it is the inf. n.: and see <span class=\"ar\">هَزَاهِزُ</span>.</p><p><b class=\"ar\">هَزَاهِزُ</b> [app. pl. of <span class=\"ar\">هَزْهَزَةٌ</span>] <i>Seditions,</i> or <i>discords,</i> or <i>dissensions,</i> (<span class=\"ar\">فِتَنٌ</span>,) <i>in which people are in a state of commotion:</i> (S, Msb:) or <i>wars and difficulties</i> or <i>afflictions</i> or <i>calamities that put into a state of commotion:</i> (A:) or the <i>excitement of commotion in men, by trials,</i> or <i>trying events, and by wars;</i> (K, * TA;) as also <span class=\"ar\"> <span class=\"ar\">هَزْهَزَةٌ</span></span>. (K.)</p>"},"هطع":{"mf":"هَطَعَ الرجل ببصره: إذا صوّبه، وبعير مُهْطِعٌ:<br>إذا صوّب عنقه. قال تعالى: مُهْطِعِينَ مُقْنِعِي رُؤُسِهِمْ لا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ<br>[إبراهيم/ ٤٣]، مُهْطِعِينَ إِلَى الدَّاعِ<br>[القمر/ ٨].","mq":[["اقبال علي الشي وانقياد"],"الهاء والطاء والعين: أُصَيلٌ يدلُّ على إقبالٍ على الشّئ وانقِياد. يقال: هَطَعَ الرّجلُ على الشَّئ ببصره: أقبَلَ وأهطعَ البعيرُ: صَوَّبَ عنقَه منقاداً. وأهْطَعَ: أسْرَعَ.<br>"]},"هزم":{"mf":"أصل الهَزْمِ: غمز الشيء اليابس حتى ينحطم، كَهَزْمِ الشّنّ، وهَزْمِ القثّاء والبطّيخ، ومنه: الهَزِيمَةُ لأنه كما يعبّر عنه بذلك يعبّر عنه بالحطم والكسر. قال تعالى: فَهَزَمُوهُمْ بِإِذْنِ اللَّهِ<br>[البقرة/ ٢٥١]، جُنْدٌ ما هُنالِكَ مَهْزُومٌ مِنَ الْأَحْزابِ<br>[ص/ ١١] وأصابته هَازِمَةُ الدّهر. أي: كاسرة كقولهم: فاقرة، وهَزَمَ الرّعد: تكسّر صوته، والْمِهْزَامُ: عود يجعل الصّبيان في رأسه نارا فيلعبون به، كأنّهم يَهْزِمُونَ به الصّبيان. ويقولون للرّجل الطّبع: هَزَمَ واهْتَزَمَ.","mq":[["ان تغمز الشي بيدك فينهزم الي داخل، كالقثاءة والبطيخة"],"الهاء والزاء والميم أصلٌ صحيحٌ يدلُّ على غَمْز وكَسْر. فالهَزْم:<br>أن تَغْمِزَ الشئَ بيدك فيَنْهَزمَ إلى داخل، كالقِثّاءةِ والبِطِّيخة. ومنه الهَزِيمة فى الْحَرْب. وغيثٌ هَزِيم: متبعِّق. وهَزِيم الرَّعدِ: صوتُه، كأنّه يتكسَّر، من قولهم: تهزَّمَ السِّقاء: يَبِسَ فتشَقَّقَ.<br>ومن الباب اهتَزَمْتُ الشَّاةَ"],"ln":"<p><b>7.</b> <b class=\"ar\">اِنْهَزَمَ</b> <i>It</i> (an army) <i>was routed, discomfited, defeated,</i> or <i>put to flight.</i> (K, &amp;c.) See <span class=\"ar\">حَاصَ</span>, in art. <span class=\"ar\">حيص</span>; and <span class=\"ar\">اِنْحَازَ</span>, in art. <span class=\"ar\">حوز</span>; from both of which it is distinguished.</p><p><b class=\"ar\">هَزْمَةٌ</b> The [<i>purring,</i> or] <i>sound of the throat</i> of a cat. (TA.) -b2- The <i>pit between the two collar-bones.</i> (TA, art. <span class=\"ar\">ترب</span>.) -b3- [The <i>pit</i> above a horse's eye.] (K, voce <span class=\"ar\">وَقْبٌ</span>.) See also <span class=\"ar\">خُنْعُبَةٌ</span>, and <span class=\"ar\">قَلْتَةٌ</span>: and see <span class=\"ar\">عُقْمٌ</span>, where it seems to mean <i>a stricture:</i> it generally and properly signifies <i>a depression,</i> or <i>dint:</i> or <i>a pit,</i> or <i>small hollow, resembling a dint:</i> see also <span class=\"ar\">غَيْبٌ</span>.</p><p><b class=\"ar\">مَهْزُومُ الصَّدْرِ</b> <i>Depressed of breast,</i> i. e., apparently, <i>illiberal, niggardly:</i> see <span class=\"ar\">حَوْضٌ</span>.</p>"},"هيأ":{"mf":"الْهَيْئَةُ: الحالة التي يكون عليها الشيء، محسوسة كانت أو معقولة، لكن في المحسوس أكثر. قال تعالى: أَنِّي أَخْلُقُ لَكُمْ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ [آل عمران/ ٤٩]، وَالمُهايأَةُ:<br>ما يَتَهَيَّأُ القوم له فيتراضون عليه على وجه التّخمين، قال تعالى: وَهَيِّئْ لَنا مِنْ أَمْرِنا رَشَداً<br>[الكهف/ ١٠]، وَيُهَيِّئْ لَكُمْ مِنْ أَمْرِكُمْ مِرفَقاً<br>[الكهف/ ١٦] وقيل: هَيَّاكَ أن تفعل كذا. بمعنى: إيّاك، قال الشاعر:<br><span class=\"num\">٤٧٣-</span><br>هيّاك هيّاك وحنواء العنق<br><strong>«١»</strong>","mq":[[],"الهاء والياء والألف كلمةٌ تأتى وهاؤها زائدة. يقال: هَيَا، والمرادُ: يا. قال الشاعر:<br>فَيُصِيخُ يرجُو أنْ يكونَ حَياً … ويقولُ مِنْ طربٍ هَيَا ربَّا (١)<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَآءَ</b> , aor. <span class=\"ar\">يَهَآءُ</span> and <span class=\"ar\">يَهِيْءُ</span>, (K; the latter not of respectable authority, Lh;) inf. n. <span class=\"ar\">هَيْئَةٌ</span>, <i>He was,</i> or <i>became, of good,</i> or <i>goodly, form</i> or <i>appearance,</i> or <i>other properties denoted by the term</i> <span class=\"ar\">هَيْئَة</span>, q. v. (K.) -b2- [<span class=\"ar\">هَيُؤَ</span>, accord. to the K, signifies <i>the same:</i> but see below.] -b3- <span class=\"ar\">هَيُؤَ</span>, accord. to IHsh and others, the only verb of this form whose medial radical letter is <span class=\"ar\">ى</span>: (MF:) accord. to the K, syn. with <span class=\"ar\">هَآءَ</span>, in a sense indicated above: but IJ states that it has a superlative sense; that it is to be classed with <span class=\"ar\">قَضُوَ</span> “ excellent [or how excellent (see <span class=\"ar\">بَطُؤَ</span> voce <span class=\"ar\">بُطَآنَ</span>)] is he in his judging! ” and <span class=\"ar\">رَمُوَ</span> “ excellent [or how excellent] is he in his throwing, or shooting! ” [wherefore it signifies <i>Excellent,</i> or <i>how excellent, is he in his form</i> or <i>appearance!</i> &amp;c.;] and that it is, like <span class=\"ar\">قَضُوَ</span> [and <span class=\"ar\">رَمُوَ</span>], invariable [as to person, tense, and mood]. He observes that, as a verb of the measure <span class=\"ar\">فَعُلَ</span> is formed from one whose final radical letter is <span class=\"ar\">ى</span>, [as <span class=\"ar\">قَضُوَ</span> and <span class=\"ar\">رَمُوَ</span> from <span class=\"ar\">قَضَى</span> and <span class=\"ar\">رَمَى</span>,] so is this formed on the same measure from a verb whose medial radical letter is <span class=\"ar\">ى</span>: and that it is invariable [as to person, tense, and mood,] because of its resemblance, in its superlative sense, to the class of verbs of wonder, and to <span class=\"ar\">نِعْمَ</span> and <span class=\"ar\">بِئْسَ</span>. He further remarks, that they [the Arabs] have abstained from forming a verb on the measure <span class=\"ar\">فَعُلَ</span> [variable as to person, tense, and mood,] from one whose medial radical letter is <span class=\"ar\">ى</span>, fearing to make what is difficult to pronounce still more so; for in that case they would be obliged to say <span class=\"ar\">أَبُوعُ بُعْتُ</span>, and <span class=\"ar\">بُوعَا</span>; and, as would also happen if a variable verb of the same measure were formed from one whose final radical letter is <span class=\"ar\">ى</span>, the change of <span class=\"ar\">ى</span> into <span class=\"ar\">و</span>, which is more difficult to pronounce, would thus become frequent. (TA.) -b4- <span class=\"ar\">هَآءَ إِلَيْهِ</span>, aor. <span class=\"ar\">يَهَآءُ</span>, inf. n. <span class=\"ar\">هِيْئَةٌ</span>, <i>He desired, longed for, longed to see, him</i> or <i>it.</i> (K.)</p><p><b>2.</b> <b class=\"ar\">هيّأ</b> , inf. n. <span class=\"ar\">تَهْيِئَةٌ</span> and <span class=\"ar\">تَهْيِىْءٌ</span>, [primarily signifies <i>He invested him with,</i> or <i>made him to have,</i> <span class=\"ar\">هَيْءَة</span>, as meaning <i>garb, guise,</i> &amp;c. See Bd xviii. 9. -b2- And hence,] <i>He prepared, provided, disposed, arranged,</i> or <i>put into a right,</i> or <i>good state,</i> &amp;c. (S, K.) [And hence, <i>He rendered</i> an affair <i>feasible,</i> or <i>practicable; he facilitated it.</i>]</p><p><b>5.</b> <b class=\"ar\">تهيّأ</b> [<i>He,</i> or <i>it, was,</i> or <i>became, prepared, provided, disposed, arranged,</i> or <i>put into a right</i> or <i>good state,</i> &amp;c. And hence, <i>It</i> (an affair) <i>was,</i> or <i>became, feasible,</i> or <i>practicable:</i> and <i>it</i> (a thing) <i>was,</i> or <i>became, attainable,</i> or <i>within power</i> or <i>reach.</i>] -b2- <span class=\"ar\">تهيّأ لِلْأَمْرِ</span>; and <span class=\"ar\">هَآء لَهُ</span>, (S, K,) aor. <span class=\"ar\">يَهَآءُ</span> (K) and <span class=\"ar\">يَهِىْءُ</span>, (S, K,) inf. n. <span class=\"ar\">هَيْئَةٌ</span>; (S;) <i>He prepared himself for the thing.</i> (K.) Ex. <span class=\"ar\">وَقَالَتْ هِئْتُ لَكَ</span> <i>And she said, I have prepared myself for thee:</i> accord. to one reading [for <span class=\"ar\">هَيْتَ</span>, in the Kur, xii. 23]. (Akh, S.) -b3- [See also <span class=\"ar\">تهنّأ</span>.] -b4- <span class=\"ar\">تهيّأ لَهُ الأَمْرُ</span>, (Msb, K, art. <span class=\"ar\">اتى</span>, &amp;c.,) or <span class=\"ar\">الشَّىْءٌ</span>, (S, art. <span class=\"ar\">اتى</span>, &amp;c.,) <i>The thing,</i> or <i>affair, was,</i> or <i>became, feasible,</i> or <i>practicable, to him;</i> and <i>the thing was attainable.</i>] -b5- <span class=\"ar\">تهيّأ لِلْبُكَآءِ</span> [<i>He was ready,</i> or <i>about, to weep:</i> a phrase of frequent occurrence; like <span class=\"ar\">أَرَادَ البُكَآءَ</span>, and <span class=\"ar\">هَمَّ بِالْبُكَاءِ</span>.] (S, art. <span class=\"ar\">جهش</span>, &amp;c.)</p><p><b>6.</b> <b class=\"ar\">تَهَايَؤُوا عَلَى ذٰلِكَ</b> <i>They agreed together upon that,</i> or <i>to do that.</i> (K, * TA.)</p><p><b class=\"ar\">هَىْءٌ</b> and <span class=\"ar\">هِىْءٌ</span> The <i>calling,</i> or <i>a call, to food and beverage.</i> (K.) -b2- The <i>calling,</i> or <i>a call, to camels to drink:</i> (K:) or, [rather,] <i>a call to camels to food,</i> or <i>provender.</i> (TA.) -b3- [See arts. <span class=\"ar\">جيأ</span> and <span class=\"ar\">هأ</span>.]</p><p><b class=\"ar\">يَا هَىْءَ مَا لِى</b> [but see <span class=\"ar\">شىءٌ</span>] [<i>Oh! what has happened to me?</i>] an expression of regret; <span class=\"ar\">هَىْءٌ</span> being a word signifying <i>regret</i> for a thing that passes away from one, or escapes him: (S, TA:) or, (as some say, TA,) an expression of wonder: (K:) see also <span class=\"ar\">يَاشَىْءِ</span> and <span class=\"ar\">يَافَىْءَ</span>, which are syn. with <span class=\"ar\">يَاهَىْءَ</span>: (TA:) or <span class=\"ar\">هَىْءَ</span>, (accord. to certain of the lexicologists, as related by IB, TA,) is an imperative verbal noun, signifying <i>Attend!</i> (<span class=\"ar\">تَنَبَّهْ</span>); like <span class=\"ar\">صَهْ</span>, which signifies “ Be silent! ” (K;) the interjection <span class=\"ar\">يا</span> being put before it in like manner as it is in the saying of Esh-Shemmakh, <span class=\"ar\">أَلَا يَا ٱسْقِيَانِى قَبْلَ غَارَةِ سَنْجَالِ</span> [<i>Come now! O, give me to drink, before the expedition of Sinjáb!</i>]; (TA;) and <span class=\"ar\">هىء</span> being indeclinable, with a vowel for its termination to obviate the occurrence of two quiescent letters, and with fet-hah as the final vowel because it is more easy of pronunciation than the others in this case. (K, TA.) -b2- [See also art. <span class=\"ar\">شيأ</span>.]</p><p><b class=\"ar\">هَيْئَةٌ</b> and <span class=\"ar\"> <span class=\"ar\">هِيْئَةٌ</span></span> <i>Form, fashion, shape, aspect,</i> or <i>appearance; figure, person, mien, feature,</i> or <i>lineaments;</i> (S, TA;) <i>guise;</i> or <i>external state</i> or <i>condition;</i> (Msb;) <i>state with regard to apparel and the like;</i> or <i>garb;</i> (Lth;) <i>state, condition,</i> or <i>case; quality, mode</i> or <i>manner of being:</i> (K:) pl. <span class=\"ar\">هَيْآتٌ</span> and <span class=\"ar\">هِيْآتٌ</span>. (TA.) -b2- <span class=\"ar\">حَسَنُ الهَيْئَةِ</span> [<i>of goodly form, aspect,</i> or <i>appearance, guise, state of apparel, garb, &amp;c.</i>]. (S.) -b3- [Also, <i>goodliness of form</i> &amp;c.: see 1. See also <span class=\"ar\">سَمْتٌ</span>, for an addition.] -b4- [<span class=\"ar\">هَيْئَةٌ عَارِضَةٌ</span>, in Logic, <i>An accidental mode.</i>] -b5- <span class=\"ar\">أَقِيلُوا ذَوِى الهَيْآتِ عَثَرَاتِهِمْ</span>, in a trad., signifies, <i>Forgive ye the people of good qualities &amp;c., who keep to one state and way, their slips.</i> It alludes to those who make a slip unwittingly. (TA.)</p><p><b class=\"ar\">هِيْئَةٌ</b> : see <span class=\"ar\">هَيْئَةٌ</span>.</p><p><b class=\"ar\">هَيِىْءٌ</b> : see what next follows.</p><p><b class=\"ar\">هَيِّئٌ</b> and <span class=\"ar\"> <span class=\"ar\">هَيِّىْءٌ</span></span> A person <i>of good,</i> or <i>goodly, form</i> or <i>appearance,</i> or <i>other properties denoted by the term</i> <span class=\"ar\">هَيْئَة</span>. (K.)</p><p><b class=\"ar\">مُهَيَّأٌ</b> [<i>Prepared,</i> &amp;c.] -b2- Also <i>i. q.</i> <span class=\"ar\">زُمَا وَرْدٌ</span>, q. v. (MF, art. <span class=\"ar\">ورد</span>.)</p><p><b class=\"ar\">مَهَايَأَةٌ</b> <i>A thing respecting which persons have agreed together.</i> (K, TA.)</p><p><b class=\"ar\">مَتَهَيِّئَةٌ</b> A camel <i>that seldom fails of becoming pregnant when she has been covered.</i> (K.)</p>"},"همن":{"mq":[[],"الهاء والميم والنون ليس بشئ. فأمّا المُهيمِن، وهو الشاهد فليس من هذا، إنَّما هو من باب أمن (٥)<br>، والهاء مبدلة من همزة.<br>"]},"هلم":{"mf":"<strong>هَلُمَّ دعاء إلى الشيء، وفيه قولان:</strong><br><br>أحدهما: أنّ أصله هَا لُمَّ <strong>«١»</strong>. من: قولهم:<br>لممت الشيء. أي: أصلحته، فحذف ألفها فقيل: هلمّ.<br>وقيل أصله هل أمّ <strong>«٢»</strong>، كأنه قيل: هل لك في كذا أمّه. أي: قصده، فركّبا. قال عزّ وجلّ:<br>وَالْقائِلِينَ لِإِخْوانِهِمْ هَلُمَّ إِلَيْنا [الأحزاب/ ١٨]، فمنهم من تركه على حالته في التّثنية والجمع، وبه ورد القرآن، ومنهم من قال: هَلُمَّا، وهَلُمُّوا، وهَلُمِّي، وهَلْمُمْنَ <strong>«٣»</strong>.","mq":[[],"الهاء واللام والميم ليس فيه إلاّ قولهم هَلُمَّ: كلمة دعوة إلى شَئ.<br>قالوا: وأصلها هَلْ أَؤُمُّ، كلامُ مَنْ يريد إتيان الطعام، ثمَّ كثُرت حتَّى تكلَّم بها الدَّاعى، مثل قولهم: تَعَالَ، أى اعْلُ، ثمَّ كثُرت حتّى قالها مَنْ كان أسفَلَ لمن كان فَوق. ويحتمل أنْ يكون معناها هلْ لك فى الطَّعام أُمَّ، أى اقص"],"ln":"<p><b class=\"ar\">هَلُمَّ</b> <i>i. q.</i> <span class=\"ar\">نَعَالَ</span> <i>Come.</i> (S, K, &amp;c.) -b2- It is intrans.; as in <span class=\"ar\">هَلُمَّ إِلَيْنَا</span> <i>Come to us.</i> And tran also; as in <span class=\"ar\">هَلُمَّ شُهَدَآءَ كُمْ</span> <i>Cause your witnesses to come; bring your witnesses.</i> (Msb.) -b3- <span class=\"ar\">هَلُمَّ</span> <span class=\"ar\">جَرًّا</span> <i>At thine ease:</i> see 1 in art. <span class=\"ar\">جر</span>.</p>"},"هرع":{"mf":"يقال هَرِعَ وأَهْرَعَ: ساقه سوقا بعنف وتخويف. قال الله تعالى: وَجاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ<br><strong>[هود/ ٧٨] وهَرَعَ برمحه فَتَهَرَّعَ:</strong><br>إذا أشرعه سريعا، والهَرِعُ: السّريع المشي والبكاء، قيل: والْهَرِيعُ والْهَرْعَةُ: القملة الصّغيرة.","mq":[["حركة واضطراب"],"الهاء والراء والعين: أصلٌ صحيحٌ يدلُّ على حركةٍ واضطراب.<br>وأُهْرِعَ الرّجُلُ: ارتَعَدَ فَرَقاً. وسمِّىَ الأحمقُ هَيْرَعاً لاضطرابِ رائِهِ. ويمكن أنَّ الهاء فيه زائدة، فيكون من باب يَرَع. ويقال الهِرْياع: سَفِير الشَّجرِ، لأنَّه مضطرِبٌ تحمِلُهُ الرِّيحُ من موضعٍ إلى موضع.<br>ومن الباب: الهَرِع: الدَّمعُ"]},"هشم":{"mf":"الْهَشْمُ: كسر الشيء الرّخو كالنّبات. قال تعالى: فَأَصْبَحَ هَشِيماً تَذْرُوهُ الرِّياحُ<br>[الكهف/ ٤٥]، فَكانُوا كَهَشِيمِ الْمُحْتَظِرِ<br><strong>[القمر/ ٣١] يقال: هَشَمَ عظمه، ومنه:</strong><br><strong>هَشَمْتُ الخبز، قال الشاعر:</strong><br><span class=\"num\">٤٦٨-</span><table class=\"poem\"><tr><td>عمرو العلا هَشَمَ الثّريد لقومه </td><td> ورجال مكّة مسنتون عجاف</td></tr></table><strong>«٢»</strong> والْهَاشِمَةُ: الشّجّة تَهْشِمُ عظم الرأس، واهْتَشَمَ كلّ ما في ضرع الناقة: إذا احتلبه ويقال: تَهَشَّمَ فلان على فلان: تعطّف.","mq":[["كسر الشي الاجوف وغير الاجوف وهشمته هشما"],"الهاء والشين والميم أصلٌ يدلُّ على كسْر الشَّئ الأجوفِ وغيرِ الأجوف وهَشمْتُهُ هَشْماً. والهاشِمَة الشَّجَّة تَهْشِمُ عظمَ الرَّأْس. ومُجْمَعٌ على أن هاشماً سمِّى به لأنَّه هَشَمَ الثرِبد، واسمه عَمرو. والهشيم من النَّبات: اليابس المتكسِّر.<br>ورجلٌ هشِيمٌ: ضعيف البَدَن. وربما قالوا: تهشَّمَ فلانٌ على"],"ln":"<p><b>1.</b> <b class=\"ar\">هَشَمَهُ</b> <i>He crushed it.</i></p><p><b>2.</b> <b class=\"ar\">هَشَّمَهُ</b> , inf. n. <span class=\"ar\">تَهْشِيمٌ</span>, <i>He broke it</i> [<i>much,</i> or <i>so crushed it</i>]; (TA;) namely, a dry thing, and anything hollow, such as the head, and the like. (TA in art. <span class=\"ar\">شدخ</span>.)</p><p><b>5.</b> <b class=\"ar\">تَهَشَّمَ</b> <i>It</i> (a plant, or herbage,) <i>became</i> <span class=\"ar\">هَشِيم</span>, i. e. <i>dry, and broken in pieces.</i></p><p><b class=\"ar\">هَشِيمٌ</b> A plant <i>that is dry, and breaks,</i> or <i>is broken, in pieces.</i> (S, Msb, K.)</p><p><b class=\"ar\">هَاشِمَةٌ</b> <i>A wound in the head which breaks the bone:</i> see <span class=\"ar\">شَجَّةٌ</span>.</p><p><b class=\"ar\">الكُرُّ الهَاشِمِىُّ</b> : see <span class=\"ar\">كُرٌّ</span>.</p>"},"هبو":{"mf":"هَبَا الغبار يَهْبُو: ثار وسطع، والهَبْوَة كالغبرة، والهَبَاء: دقاق التّراب وما نبت في الهواء فلا يبدو إلّا في أثنا ضوء الشمس في الكوّة. قال تعالى:<br>فَجَعَلْناهُ هَباءً مَنْثُوراً<br>[الفرقان/ ٢٣]، فَكانَتْ هَباءً مُنْبَثًّا. [الواقعة/ ٦].","mq":[[],"الهاء والباء والحرف المعتلّ: كلمةٌ تدلُّ على غَبَرة ورقَّة فيها.<br>منه الهَبْوة: الغَبَرة. وهبا الغُبارُ يَهبو فهو هابٍ: سَطع. والهَبَاء: دُقَاق التُّراب.<br>قال:<br>تَرَوَّد منا بينَ أُذْناهُ ضَربةً … دعَتْه إلى هابِى الترابِ عقِيم (٤)<br>وهَبَا الرَّمادُ: اختَلَطَ بالتُّراب وهَمَد. والشَّئُ المنبثُّ الذى راه"],"ln":"<p><b>1.</b> <b class=\"ar\">هَباَ الرَّمَادُ</b> , (JK, TA,) aor. <span class=\"ar\">يَهْبُو</span>, (TA,) <i>The ashes became mixed with dust,</i> and extinguished: (JK, TA:) and <span class=\"ar\">هَباَ الجَمْرُ</span>. (M, art. <span class=\"ar\">رمد</span>.)</p><p><b class=\"ar\">هُبَةٌ</b> : see <span class=\"ar\">أَهْبَةٌ</span>.</p><p><b class=\"ar\">هَبْوَةٌ</b> <i>Dust rising,</i> or <i>spreading, in the sky like smoke.</i> (JK.)</p><p><b class=\"ar\">هَبَآءٌ</b> <i>The motes that are seen in the rays of the sun:</i> (TA:) see an ex. voce <span class=\"ar\">غُثَآءٌ</span>.</p>"},"هيج":{"mf":"يقال: هَاجَ البقل يَهِيجُ: اصفرّ وطاب، قال عزّ وجلّ: ثُمَّ يَهِيجُ فَتَراهُ مُصْفَرًّا [الزمر/ ٢١] وأَهْيَجَتِ الأرضُ: صار فيها كذلك، وهَاجَ الدّم والفحل هَيْجاً وهَيَاجاً، وهَيَّجَتِ الشّرّ والحرب، والْهَيْجَاءُ: الحرب وقد يقصر، وهَيَّجْتُ البعيرَ: أَثَرْتُهُ.","mq":[["يدل علي ثوران شي","علي يبس نبات"],"الهاء والياء والجيم أصلان صحيحان: أحدهما يدلُّ على ثَوَرَان شئ، والآخر على يُبْس نَبَات. فالأوّل: هاجَ الفحلُ هَيْجاً وهِياجاً. وكذلك الدَّم: والهَيْجاء تمدُّ وتقصر. وهِجت (٢) الشَّرَّ وهيَّجْته. وهيَّجْتُ النّاقَة فانبعثَتْ. ويقال للنَّاقةِ النَّزوع إلى وَطَنِها: مِهياج.<br>والآخَر قولهم: هاجَ البقلُ،"],"ln":"<p><b>1.</b> <b class=\"ar\">هَاجَ</b> , aor. <span class=\"ar\">يَهِيجُ</span>, inf. n. <span class=\"ar\">هَيْجٌ</span> and <span class=\"ar\">هَيَجَانٌ</span> [the most common form]; and <span class=\"ar\">هِيَاجٌ</span>; and <span class=\"ar\"> <span class=\"ar\">اهتاج</span></span>, and <span class=\"ar\"> <span class=\"ar\">تهيّج</span></span>; <i>It</i> (a thing, S) <i>became raised, roused, excited, stirred up,</i> or <i>provoked;</i> syn. <span class=\"ar\">ثَارَ</span>: (S, L, K:) it became so by reason of distress, or difficulty; or of harm, or injury: you say <span class=\"ar\">هَاجَ بِهِ الدَّمُ</span>, inf. n. <span class=\"ar\">هَيْجٌ</span> and <span class=\"ar\">هَيَجَانٌ</span>, <i>The blood became roused,</i> or <i>stirred up, in him:</i> (A, L:) and in like manner, <span class=\"ar\">المِرَّةُ</span> <i>the gall,</i> or <i>bile:</i> and <span class=\"ar\">الغُبَارُ</span> <i>the dust.</i> (A.) See also <span class=\"ar\">هَائِجٌ</span>. -b2- <span class=\"ar\">هَاجَ</span>, inf. n. <span class=\"ar\">هِيَاجٌ</span> and <span class=\"ar\">هُيُوجٌ</span> and <span class=\"ar\">هَيَجَانٌ</span>; and <span class=\"ar\"> <span class=\"ar\">اهتاج</span></span>; (tropical:) <i>He</i> (a stallion-camel) <i>became excited by lust; initum appetivit; brayed, and became excited by lust.</i> When this is the case, he becomes lean, and his price is lessened. (L.) -b3- <span class=\"ar\">هَاجَتْ عَيْنُهُ</span>, (S, art. <span class=\"ar\">مرح</span>; and L, art. <span class=\"ar\">رمد</span>; &amp;c.) inf. n. <span class=\"ar\">هَيَجَانٌ</span>, (K, art. <span class=\"ar\">رمد</span>; &amp;c.) <i>His eye became inflamed; painful and swollen; affected with ophthalmia;</i> (L, art. <span class=\"ar\">رمد</span>;) <i>i. q.</i> <span class=\"ar\">رَمِدَ</span>. (S, art. <span class=\"ar\">رمد</span>; and L, K, * in the same art.) -b4- <span class=\"ar\">هَاجٌ به</span> <span class=\"ar\">فَهَجَاهُ</span> (tropical:) [<i>He became excited against him,</i> or <i>attacked him, and satirized him</i>]. (A.) -b5- <span class=\"ar\">هَاجَ</span> <span class=\"ar\">الهِجَآءُ بَيْنَهُمَا</span> (tropical:) [<i>Satire was excited between them two.</i> (A.) -b6- <span class=\"ar\">هَاجَتِ الحَرْبُ</span> (inf. n. <span class=\"ar\">هَيْجٌ</span>, Msb) (tropical:) <i>War became excited,</i> or <i>raised.</i> (A, Msb.) -b7- <span class=\"ar\">هَاجَ الشَّرُّ بَيْنَهُمْ</span> (tropical:) <i>Evil become excited among them.</i> (A.) -b8- <span class=\"ar\">هَاجَ</span>, inf. n. <span class=\"ar\">هَيْجٌ</span>, <i>He,</i> or <i>it, was in a state of commotion.</i> (L.) -b9- <span class=\"ar\">هَاجَتِ السَّمَآءُ فَمُطِرْنَا</span> <i>The sky became cloudy and windy, and we were rained upon.</i> (TA.) -b10- <span class=\"ar\">هَاجَ</span>; (S, K;) [followed by an accus., and also by <span class=\"ar\">ب</span>;] and <span class=\"ar\"> <span class=\"ar\">هيّج</span></span>, inf. n. <span class=\"ar\">تَهْيِيجٌ</span>, the most common form;] and <span class=\"ar\"> <span class=\"ar\">هَايَجَ</span></span>; (S;) <i>He,</i> or <i>it, raised, roused, excited, stirred up,</i> or <i>provoked,</i> (S, K,) a thing; (S;) syn. <span class=\"ar\">أَثَارَ</span>. (K.) Thus the first of these verbs is trans. as well as intrans. (S.) All have the same meaning: (S:) or the second has an intensive signification. (Msb.) -b11- <span class=\"ar\">هَاجَ الغُبَارَ</span>, and <span class=\"ar\"> <span class=\"ar\">هيّجهُ</span></span>, [which is more common,] <i>He raised the dust.</i> (TA.) -b12-<span class=\"ar\"> <span class=\"ar\">هيّج</span>الشَّرَّ</span> (tropical:) <i>He excited evil</i> among a people. (A) -b13-<span class=\"ar\"> <span class=\"ar\">هَيَّجْتُ</span>النَّاقَةَ فَٱنْبَعَثَتْ</span> <i>I roused the she-camel, and she became roused.</i> (A.) -b14- <span class=\"ar\">هِجْتُهُ فَهَاجَ</span> <i>I roused him, and he became roused.</i> (TA.) -b15- <span class=\"ar\">هَاجَتْ لَهُ الدَّارُ الشَّوْقَ</span> <i>The dwelling excited his longing desire.</i> (A.) -b16- <span class=\"ar\">هَاجَ</span> <i>He,</i> or <i>it, disquieted, and scared,</i> a person. (L.) -b17- <span class=\"ar\">هَاج الإِبَلَ</span>, inf. n. <span class=\"ar\">هَيْجٌ</span>, <i>He put the camels in motion, by night, towards the watering-place and pasture.</i> (L.) -b18- <span class=\"ar\">هَاجَتِ الإِبِلُ</span> <i>The camels thirsted.</i> (K.) -b19- <span class=\"ar\">هَاجَ</span>, (inf. n. <span class=\"ar\">هِيَاجٌ</span>, S, and <span class=\"ar\">هَيْجٌ</span>, TA,) (tropical:) <i>It</i> (a plant, or herbage,) <i>dried up:</i> (S, K:) [<i>it withered:</i>] <i>it</i> (a leguminous plant) <i>became yellow:</i> (Msb:) or <i>dried up and became yellow:</i> and <i>became tall.</i> (L.) -b20- <span class=\"ar\">هَاجَتِ الأَرْضُ</span>, inf. n. <span class=\"ar\">هِيَاجٌ</span> and <span class=\"ar\">هَيْجٌ</span> and <span class=\"ar\">هَيَجَانٌ</span>, (tropical:) <i>The plants,</i> or <i>herbage,</i> or <i>leguminous plants, of the land dried up.</i> (L.)</p><p><b>2.</b> <b class=\"ar\">هَيَّجَ</b> see 1 and 4.</p><p><b>3.</b> <b class=\"ar\">هايجهُ</b> , (TK,) inf. n. <span class=\"ar\">هِيَاجٌ</span>, (S, K,) <i>He fought with him; engaged in a conflict,</i> or <i>combat, with him.</i> (TK.) -b2- <span class=\"ar\">يَوْمُ الهِيَاجِ</span> <i>The day of fight, conflict</i> or <i>combat.</i> (S, K. *) -b3- See 1.</p><p><b>4.</b> <b class=\"ar\">أَهَاجَتِ الرِّيحُ النَّبْثَ</b> (tropical:) <i>The wind dried up,</i> or <i>caused to dry up, the plants,</i> or <i>herbage:</i> (S, K *:) and [so] <span class=\"ar\"> <span class=\"ar\">هَيَّجَتْهُ</span></span>. (O, K in art. <span class=\"ar\">صوع</span>.) -b2- <span class=\"ar\">أَهْيَجْنَا الأَرْضَ</span> (tropical:) <i>We found the land to have its plants</i> or <i>herbage, dried up.</i> (S, K.)</p><p><b>5.</b> <b class=\"ar\">تَهَيَّجَ</b> see 1.</p><p><b>6.</b> <b class=\"ar\">تَهَايَجُوا</b> (assumed tropical:) <i>They leaped,</i> or <i>sprung up, together, to fight, one against another.</i> (S, K.)</p><p><b>8.</b> <b class=\"ar\">إِهْتَيَجَ</b> see 1.</p><p><b class=\"ar\">هِجْ</b> : see <span class=\"ar\">هِيج</span>.</p><p><b class=\"ar\">هَيْجٌ</b> <i>Civil war;</i> or <i>conflict and faction;</i> or <i>discord,</i> or <i>dissension;</i> syn. <span class=\"ar\">فِتْنَةٌ</span>. (L.) See <span class=\"ar\">هَيْجَآءُ</span>. -b2- <i>Excitement of the blood:</i> or, <i>of coitus:</i> or, <i>of longing desire.</i> (L.) -b3- <span class=\"ar\">يَوْمُ هَيْجٍ</span> <i>A day of wind:</i> or, <i>of clouds,</i> or <i>mist, and rain.</i> (K, TA: [but accord. to some copies of the K, instead of “ and rain, ” “ or, <i>of rain.</i> ”]) -b4- <span class=\"ar\">هَاجَ</span> <span class=\"ar\">لَهُ هَيْجٌ حَسَنٌ</span>, said with respect to a cloud, or body of clouds, when first rising; (As;) [meaning, <i>It hath had a good rising,</i> or <i>hath risen well,</i> so as to present, at its first rising, a good, or promising, appearance: an expression like <span class=\"ar\">لَهُ نَشْءٌ حَسَنٌ</span>, q. v., art. <span class=\"ar\">نشأ</span>]. -b5- <span class=\"ar\">هَيْجٌ</span>, (assumed tropical:) <i>Yellowness:</i> [app. in a plant]: (L:) or <i>a state of drying up.</i> (IAar, L.) See <span class=\"ar\">هَائِجٌ</span>.</p><p><b class=\"ar\">هِيجِ</b> , indecl., with kesreh for its termination, and <span class=\"ar\"> <span class=\"ar\">هِجْ</span></span>, <i>Cries by which a she-camel is chidden.</i> (K.) [See also <span class=\"ar\">هَجْهَجَ</span>, in art. <span class=\"ar\">هج</span>.]</p><p><b class=\"ar\">هَاجَةٌ</b> A ewe <i>that does not desire the ram:</i> as though deprived of excitement. (M.) -b2- <span class=\"ar\">هَاجَةٌ</span> <i>A female frog.</i> (L, K.) See an ex. in a verse cited voce <span class=\"ar\">صُبَارَةٌ</span>. -b3- <i>An ostrich.</i> (L.) Pl. of both, <span class=\"ar\">هَاجَاتٌ</span>. (L. K.) Dim. <span class=\"ar\">هُوَيْجَةٌ</span> and <span class=\"ar\">هُيَيْجَةٌ</span>. (L.)</p><p><b class=\"ar\">هَيْجَى</b> : see <span class=\"ar\">هَيْجَآءُ</span>.</p><p><b class=\"ar\">هَيْجَآءُ</b> and <span class=\"ar\"> <span class=\"ar\">هَيْجَى</span></span> (S, L, K) and <span class=\"ar\"> <span class=\"ar\">هَيْجٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">هِيَاجٌ</span></span> (L) the third [as also the fourth] originally an inf. n., (Msb,) <i>War.</i> (S, L, K.)</p><p><b class=\"ar\">هَيِّجٌ</b> : see <span class=\"ar\">هَائِجٌ</span>.</p><p><b class=\"ar\">هِيَاجٌ</b> : see 1 and 3; and <span class=\"ar\">هَيْجَآءُ</span>.</p><p><b class=\"ar\">شَيْءٌ هَيُوجٌ</b> , and <span class=\"ar\"> <span class=\"ar\">مِهْيَاجٌ</span></span>, <i>A thing,</i> or <i>person, that raises, rouses, excites, stirs up,</i> or <i>provokes, much:</i> each of these epithets having a trans. signification. The former is also used as a fem. epithet. (L.)</p><p><b class=\"ar\">هَائِجٌ</b> (tropical:) <i>Anger; an ebullition of anger, rage,</i> or <i>passion;</i> syn. <span class=\"ar\">فَوْرَةٌ</span>. (S, K.) Ex. <span class=\"ar\">هَاجَ هَائِجُهُ</span> (tropical:) <i>His anger became roused,</i> or <i>excited;</i> (S;) <i>became violent;</i> (TA;) <i>he became inflamed with anger.</i> (A.) And <span class=\"ar\">هَدَأ هَائِجُهُ</span> (tropical:) <i>The ebullition of his anger, rage,</i> or <i>passion, became appeased.</i> (S.) -b2- <span class=\"ar\">هَائِجٌ</span> (S, K) and <span class=\"ar\"> <span class=\"ar\">هَيِّجٌ</span></span> (TA) (tropical:) A stallion <i>excited by lust; initum appetens.</i> (S, K.) -b3- <span class=\"ar\">أَرْضٌ هَائِجَةٌ</span> (tropical:) <i>Land of which the leguminous plants have dried up,</i> or <i>become yellow:</i> (S, K:) or, as in some lexicons, [and as in one copy of the S in my hands,] <i>and become yellow:</i> (TA:) or, <i>of which the leguminous plants have dried up.</i> (TA.) <span class=\"ar\">بَقْلٌ هَائِجٌ</span>, and <span class=\"ar\"> <span class=\"ar\">هِيْجٌ</span></span>, (tropical:) <i>Leguminous plants dried up,</i> or <i>drying up,</i> [<i>and yellow</i>]. (L.)</p><p><b class=\"ar\">مِهْيَاجٌ</b> A she-camel <i>that is excited by desire for its accustomed place, and hastens thither.</i> (S, K.) -b2- See <span class=\"ar\">هَبُوجٌ</span>. -b3- <span class=\"ar\">مِهْيَاجٌ</span> A camel <i>that thirsts before</i> [<i>other</i>] <i>camels.</i> (K.)</p>"},"هور":{"mf":"يقال: هَارَ البناء، وتَهَوَّرَ: إذا سقط نحو:<br>انْهَارَ. قال تعالى: عَلى شَفا جُرُفٍ هارٍ فَانْهارَ بِهِ فِي نارِ جَهَنَّمَ<br><strong>[التوبة/ ١٠٩] وقرئ:</strong><br>(هَائِرٌ) <strong>«١»</strong>. يقال: بئر هَائِرٌ، وهَارٌ، وهَارٍ، ومُهَارٌ، ويقال: انْهَارَ فلان: إذا سقط من مكان عال، ورجل هَارٍ وهَائِرٌ: ضعيف في أمره تشبيها بالبئر الهَائِرِ، وتَهَوَّرَ الليل: اشتدّ ظلامه، وتَهَوَّرَ الشّتاءُ: ذهب أكثره، وقيل: تَهَيَّرَ، وقيل: تَهَيَّرَهُ فهذا من الياء، ولو كان من الواو لقيل تهوّره.","mq":[["تساقط شي"],"الهاء والواو والراء: أصلٌ يدلُّ على تساقُطِ شئٍ. منه تَهَوَّرَ البِناء: انهَدَم. وتهَوّر اللَّيلُ: انكسَرَ ظلامُه، كأنَّه تهدَّم ومرَّ. وتهوَّرَ الشِّتاء: ذهبَ أشدُّهُ. ويقولون للقَطِيع من الغَنم: هَوْرٌ؛ وهو صحِيحٌ لأنَّه مِنْ كثرته يتساقط بعضُه على بعض.<br>ومما شذَّ عن الباب قولهم: هُرْتُ فلاناً بكذا"],"ln":"<p><b>1.</b> <b class=\"ar\">هَارَه</b> , (K,) [aor. <span class=\"ar\">يَهُورُهُ</span>,] inf. n. <span class=\"ar\">هَوْرٌ</span>, (TA,) <i>He threw it down; pulled it down; pulled it to pieces;</i> or <i>demolished it;</i> namely, a building; (K;) and in like manner, a <span class=\"ar\">جُرْف</span> [i. e. an abrupt, water-worn, bank, rising by the bed of a torrent or stream]; (TA [in which <span class=\"ar\">هُؤُورٌ</span> is given as an inf. n. of this verb; but it is more probably an inf. n. of the intrans. verb only, agreeably with analogy;]) as also <span class=\"ar\"> <span class=\"ar\">هوّرهُ</span></span>, (S, A,) the pronoun relating to a building, (A,) and to a <span class=\"ar\">جُرْف</span>; (S;) and <span class=\"ar\">هيّرهُ</span> [in illustration of which see what is said of <span class=\"ar\">تهيّر</span>, below]; (S, art. <span class=\"ar\">هير</span>;) and <span class=\"ar\"> <span class=\"ar\">تهوّرهُ</span></span>, in which the pronoun relates to the upper part of a <span class=\"ar\">جُرْف</span>, or to the brink of a well. (TA.) -b2- <span class=\"ar\">هَارَ القَوْمَ</span>, (K,) aor. <span class=\"ar\">يَهُورُهُمْ</span>, inf. n. <span class=\"ar\">هَوْرٌ</span>, (TA,) (tropical:) <i>He slew the people, and threw them down prostrate, one upon another,</i> (K,) <i>like as when a</i> <span class=\"ar\">جُرْف</span> <i>falls down.</i> (TA.) And [in like manner you say,] <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">فُلَانًا فَهَارَهُ</span> (assumed tropical:) <i>He smote such a one and prostrated him;</i> as also <span class=\"ar\"> <span class=\"ar\">هوّرهُ</span></span>. (K, * TA.) -b3- <span class=\"ar\">هَارَ</span>, (S, A, Msb, K,) aor. <span class=\"ar\">يَهُورُ</span>, inf. n. <span class=\"ar\">هَوْرٌ</span> (S, Msb) and <span class=\"ar\">هُؤُورٌ</span>, (S,) <i>It became thrown down, pulled down, pulled to pieces,</i> or <i>demolished;</i> or <i>it fell in ruins,</i> or <i>to pieces;</i> (S, A, K;) said of a building, (K,) and of a <span class=\"ar\">جُرْف</span> [explained above]; (S, A;) as also <span class=\"ar\"> <span class=\"ar\">انهار</span></span> and <span class=\"ar\"> <span class=\"ar\">تهوّر</span></span> (S, A, K) and <span class=\"ar\">تهيّر</span>, (K,) which last has <span class=\"ar\">ى</span> as being interchangeable with <span class=\"ar\">و</span>, or it may be of the measure <span class=\"ar\">تَفَيْعَلَ</span> [originally <span class=\"ar\">تَهَيْوَرَ</span>]: (TA:) or <i>it fell; it fell,</i> or <i>tumbled, down; it collapsed; broke down;</i> said of a building; (TA;) as also <span class=\"ar\"> <span class=\"ar\">انهار</span></span> and <span class=\"ar\"> <span class=\"ar\">تهوّر</span></span>; (Msb, TA;) said of a building, (TA,) and of a <span class=\"ar\">جُرْف</span>, (Msb,) or of the upper part of the latter, and of the brink of a well; (TA;) [and <span class=\"ar\"> <span class=\"ar\">اِهْتَوَرَ</span></span>, q. v., probably signifies the same:] or <i>it cracked, without falling;</i> said of a <span class=\"ar\">جُرْف</span>: (Msb:) or <i>it cracked in its hinder part, remaining yet in its place;</i> said of a building. (TA.)</p><p><b>2.</b> <b class=\"ar\">هوّرهُ</b> : see <span class=\"ar\">هَارَهُ</span>, in two places.</p><p><b>5.</b> <b class=\"ar\">تهوّر</b> : see <span class=\"ar\">هَارَ</span>, in two places; in the former of which, <span class=\"ar\">تهيّر</span> is also mentioned as syn. with <span class=\"ar\">تَهوّر</span>. -b2- (tropical:) <i>He plunged,</i> or <i>fell, into an affair with little care</i> [<i>for the consequence thereof</i>]: (S, K:) or <span class=\"ar\">تهوّر فِى الأُمُورِ</span> <i>he plunged,</i> or <i>fell, into affairs without thought,</i> or <i>reflection,</i> or <i>consideration:</i> (A:) or <span class=\"ar\">تَهَوُّرٌ</span> is <i>a state,</i> or <i>condition, adventitious to the irascible faculty, by reason of which one ventures upon affairs not fit,</i> or <i>meet, to be ventured upon; as the fighting with unbelievers</i> <i>when they are more than double the number of the Muslims.</i> (KT.) -A2- <span class=\"ar\">تهوّرهُ</span>: see <span class=\"ar\">هَارَهُ</span>.</p><p><b>7.</b> <b class=\"ar\">إِنْهَوَرَ</b> see <span class=\"ar\">هَارَ</span>, in two places.</p><p><b>8.</b> <b class=\"ar\">اِهْتَوَرَ</b> : see <span class=\"ar\">هَارَ</span>, last signification. -b2- <i>It</i> (a thing, S) <i>perished.</i> (S, K.)</p><p><b class=\"ar\">هَائِرٌ</b> and <span class=\"ar\">هَارٍ</span>, (S, A, Msb, K,) the latter formed by transposition from the former, [first into <span class=\"ar\">هَارِىٌ</span>, and then into <span class=\"ar\">هَارٍ</span>,] (S, TA,) like as <span class=\"ar\">شَائِكُ السِّلاحِ</span> is changed into <span class=\"ar\">شَاكِى السِّلاحِ</span>, (S,) applied to a building, (K,) and to a <span class=\"ar\">جُرْف</span>, [explained above, (see <span class=\"ar\">هَارَهُ</span>,)] (S, A, Msb,) <i>Becoming thrown down, pulled down, pulled to pieces,</i> or <i>demolished:</i> (S, A, K:) or <i>falling; falling,</i> or <i>tumbling, down:</i> (IAar:) or <i>cracking, without falling:</i> (Msb:) or <i>cracking in its hinder part, remaining yet in its place.</i> (TA.) See an ex. of the latter voce <span class=\"ar\">جَفْرٌ</span>: and another in the Kur, ix. 110.]</p><p><b class=\"ar\">مُتَهَوِّرٌ</b> A man <i>plunging,</i> or <i>falling,</i> or <i>who plunges,</i> or <i>falls, into an affair with little care</i> [<i>for the consequences thereof</i>]. (S.) See 5.</p>"},"هيت":{"mf":"هَيْتَ: قريب من هلمّ، وقرئ: هَيْتَ لَكَ<br><strong>«٢»</strong> : أي: تهيّأت لك، ويقال: هَيْتَ به وتَهَيَّتْ: إذا قالت: هَيْتَ لك. قال الله تعالى:<br>وَقالَتْ هَيْتَ لَكَ<br>[يوسف/ ٢٣].<br>يقال: هَاتِ، وهَاتِيَا، وهَاتُوا. قال تعالى:<br>قُلْ هاتُوا بُرْهانَكُمْ [البقرة/ ١١١] قال الفرّاء: ليس في كلامهم هاتيت، وإنما ذلك في ألسن الحيرة <strong>«٣»</strong>، قال: ولا يقال لا تهات. وقال الخليل <strong>«٤»</strong> : المُهَاتَاةُ والهتاءُ مصدر هات.","mq":[["الصيحة"],"الهاء والياء والتاء كلمة تدلُّ على الصَّيحة. يقولون: هيَّتَ به، إذا صاح. قال:<br>وحديثها كالقطر يسمعه … راعى سنين تتابعت جدبا.<br>* إذا تجاوبت الأصداء بالسحر *.<br>* لو كانَ مَعْنِيًّا بِها لَهَيَّتا (١) *<br>ويقولون فى معنى هَيْت لك: هَلُمَّ.<br>"],"ln":"<p><b>2.</b> <b class=\"ar\">هيّت بِهِ</b> , (S, K,) inf. n. <span class=\"ar\">تَهْيِيتٌ</span>, (TA,) as also <span class=\"ar\">هوّت</span>, (S,) <i>He cried out to him, and called</i> <i>him,</i> (S, K,) <i>saying,</i> <span class=\"ar\">هَيْتَ هَيْتَ</span>; or saying <span class=\"ar\">يَاهْ يَاهْ</span>, which is a cry by which a pastor calls his companion from afar; or, accord. to AZ, saying <span class=\"ar\">يَا هَيَا</span> [or rather <span class=\"ar\">يَاهَيَاهْ</span>: see art. <span class=\"ar\">يه</span>]. (TA.)</p><p><b>3.</b> <b class=\"ar\">هَات</b> <i>Give me:</i> (K:) <span class=\"ar\">هَاتِ يَا رَجُلُ</span> <i>Give me, O man:</i> (T, S, M:) <i>i. q.</i> <span class=\"ar\">أَعْطِنِى</span>: (T, S, M, K:) to two men, <span class=\"ar\">هَاتِيَا</span>: to a plurality of men, <span class=\"ar\">هَاتُوا</span>: to a woman, <span class=\"ar\">هَاتِى</span>: to two women, <span class=\"ar\">هَاتِيَا</span>: to a plurality of women, <span class=\"ar\">هَاتِينَ</span>: you say <span class=\"ar\">هَاتِ</span> <span class=\"ar\">لا هَاتَيْتَ</span> [<i>Give me: mayest thou not give</i> (hereafter)! an imprecation, of the like of which there are many examples]; and <span class=\"ar\">هَاتِ إِنْ كَانَتْ بِكَ</span> <span class=\"ar\">مُهَاتَاةٌ</span> [<i>Give me, if there be in thee</i> (<i>a disposition for</i>) <i>giving</i>]; and <span class=\"ar\">مَا أُهاتِيكَ</span> [<i>I do not give thee</i>], like as you say, <span class=\"ar\">مَا أُعَاطِيكَ</span>; but you do not say <span class=\"ar\">هَاتَيْتُ</span>; nor do you use this verb in a prohibitive manner: [it is used neither affirmatively nor prohibitively:] accord. to Kh, <span class=\"ar\">هَاتِ</span> is from <span class=\"ar\">ٱتَى</span>, aor. <span class=\"ar\">يُوتِى</span>; the <span class=\"ar\">ا</span> being changed into <span class=\"ar\">ه</span>. (S.) [But <span class=\"ar\">ٱتَى</span> is of the measure <span class=\"ar\">أَفْعَلَ</span>; and <span class=\"ar\">هَاتِ</span> is the imp. from the measure <span class=\"ar\">فَاعَلَ</span>. See also art. <span class=\"ar\">هتى</span>, where it is mentioned again in the S and K.]</p><p><b class=\"ar\">هَيْتَ</b> an exclamation denoting wonder: the Arabs say, <span class=\"ar\">هَيْتَ لِلْحِلْمِ</span> [<i>What forbearing mildness,</i> or <i>clemency!</i>] (L.) -b2- <span class=\"ar\">هَيْتَ لَكَ</span>, (Akh, S, K, &amp;c.,) and <span class=\"ar\">هَيْتِ لك</span>, (Akh, K,) and <span class=\"ar\">هَيْتَ لك</span>, (Akh, IB, K,) and the first letter is sometimes with kesreh; (K;) as is related on the authority of 'Alee, (TA,) [so that you say <span class=\"ar\">هِيتَ</span> and <span class=\"ar\">هِيتِ</span> and <span class=\"ar\">هِيتُ</span>, the first of which three forms is mentioned by Fr, Akh, IB, and the third by Fr, IB; but for the second I find no other authority than that implied above;] of all which, the most common is <span class=\"ar\">هَيْتَ لك</span>, with fet-hah to the <span class=\"ar\">ه</span> and <span class=\"ar\">ت</span>: (Zj:) <span class=\"ar\">هَيْتَ</span> is of the dial. of Howrán, whence it became introduced into Mekkeh; and <span class=\"ar\">هِيتَ</span>, of the dial. of El-Medeeneh: (Fr:) [imper. verbal ns.] <i>i. q.</i> <span class=\"ar\">هَلُمَّ</span>, <i>Come!</i> (Akh, S, L, K,) or <span class=\"ar\">تَعَالَ</span> the same, (Fr, Ks,) or <span class=\"ar\">أَقْبِلْ</span>, the same, or <i>Come forward!</i> (L.) It occurs in the Kur, xii. 23; where it is commonly read <span class=\"ar\">هَيْتَ لَكَ</span>; (Zj;) but 'Alee and Ibn-'Abbás are said to have read <span class=\"ar\">هِئْتُ لَكَ</span>, with hemzeh. [See art. <span class=\"ar\">هيأ</span>.] (TA.) <span class=\"ar\">هَيْتَ</span> is itself invariable whether used to denote the sing. or pl. or fem. or masc.; but the difference of number is observed in what follows it; for you say <span class=\"ar\">هَيْتَ لَكُمَا</span> [<i>Come ye two!</i>] and <span class=\"ar\">هَيْتَ لَكُنَّ</span> [<i>Come ye</i> women! &amp;c.]: (S:) you also say simply <span class=\"ar\">هَيْتَ</span> [<i>Come!</i>] and this is also said to signify <i>Hasten!</i> and <i>Set forth journeying</i> through the land, or earth. (TA.) Authorities differ respecting this word; whether it be Arabic or arabicized; and whether it be a noun or a verb; &amp;c. Accord. to AZ, as related by Az, <span class=\"ar\">هيت لك</span> is arabicized in the Kur, from the Hebrew <span class=\"ar\">هيتا كخ</span> [app. a mistake for <span class=\"ar\">هيتا كخ</span>, which I suppose to be meant for עַהׇּה לְבׇה “ Now, come! ” occurring in Gen. xxxi. 44]. (TA.)</p><p><b class=\"ar\">هَيْتَ هَيْتَ</b> : see 2.</p><p><b class=\"ar\">هِيتٌ</b> <i>A low,</i> or <i>depressed, piece of ground:</i> (K:) <i>a piece of ground having a low,</i> or <i>depressed, bottom:</i> (TA:) <i>i. q.</i> <span class=\"ar\">هُوَّةٌ</span> and <span class=\"ar\">هُوتَةُ</span>. (IAar.)</p><p><b class=\"ar\">هِيتَاءٌ</b> , and <span class=\"ar\">هِيتَاه</span>: see art. <span class=\"ar\">هوت</span>.</p><p><b class=\"ar\">هَيَّاتٌ</b> [<i>Clamorous; calling out often,</i> or <i>much</i>]. (S.)</p>"},"هجد":{"mf":"الهُجُود: النّوم، والهَاجِد: النّائم، وهجّدته فتهجّد: أزلت هجوده نحو: مرّضته. ومعناه:<br>أيقظته فتيقّظ، وقوله: وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ [الإسراء/ ٧٩] أي: تيقّظ بالقرآن، وذلك حثّ على إقامة الصلاة في الليل المذكور في قوله:<br>قُمِ اللَّيْلَ إِلَّا قَلِيلًا نِصْفَهُ [المزمل/ ٢- ٣] والمتهجّد: المصلّي ليلا، وأهجد البعير: ألقى جرانه على الأرض متحرّيا للهجود.","mq":[["ركود في مكان"],"الهاء والجيم والدال أُصَيْلٌ يدلُّ على ركودٍ فى مكان.<br>يقال: هَجَد، إذا نامَ، هُجُوداً. والهاجد: النَّائم؛ وإن صلَّى ليلاً فهو متهجِّد، كأنَّه بصلاته تركَ الهجودَ عنه. وهذا قياسٌ مستعمَل، كما يقال رجلٌ آثم؛ فإذا كَرِهَ الإِثمَ وانتَفَى منه قيل متأثِّم. والعرب تقول: أَهْجَدَ البعيرُ: ألقَى جِرانَهُ با"],"ln":"<p><b>1.</b> <b class=\"ar\">هَجَدَ</b> , (S, A, L, Msb,) aor. <b class=\"ar\">هَجُدَ</b> , (L, Msb,) inf. n. <span class=\"ar\">هُجُودٌ</span>; (L, Msb, K;) and <span class=\"ar\"> <span class=\"ar\">تهجّد</span></span>, (S, A, L, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">اهجد</span></span>, (L, K,) and <span class=\"ar\"> <span class=\"ar\">هجّد</span></span>; (IAar, L;) <i>He</i> (a man, L) <i>slept:</i> (L, Msb, K:) or <i>slept in the night:</i> (IAar, S, A, L:) or, <i>in the latter part of the night.</i> (L.) -b2- Also <span class=\"ar\">هَجَدَ</span> and <span class=\"ar\"> <span class=\"ar\">تهجّد</span></span> (S, A, L, Msb, K [in some copies, of the last of which the former verb is written <span class=\"ar\"> <span class=\"ar\">هجّد</span></span> and so in the TA) <i>He remained awake,</i> or <i>was sleepless</i> or <i>wakeful in the night:</i> (S, A, L:) and hence the <i>praying in the night</i> is called <span class=\"ar\">تَهَجُّدٌ</span>: (S, L:) or <i>he awoke from sleep</i> (K) <i>to pray,</i> or <i>for some other purpose:</i> (TA:) or <i>he prayed in the night;</i> (Msb;) as also <span class=\"ar\"> <span class=\"ar\">هجّد</span></span>: (IAar, L:) thus these verbs bear two contr. significations: (S, A, L, Msb, K:) and <span class=\"ar\"> <span class=\"ar\">تهجّد</span></span> <i>he relinquished sleep for prayer:</i> (A:) so in the Kur, xvii., 81. (Beyd.)</p><p><b>2.</b> <b class=\"ar\">هَجَّدَ</b> see 1, in three places. -b2- Also <span class=\"ar\">هجّدهُ</span>, inf. n. <span class=\"ar\">تَهْجِيدٌ</span>, <i>He made him,</i> or <i>caused him, to sleep;</i> (S, L, K;) as also <span class=\"ar\"> <span class=\"ar\">اهجدهُ</span></span>. (Ibn-Buzurj, L, K.) -b3- Also, <i>He awoke him from sleep.</i> (Ibn-Buzurj, L, K.) Thus it bears two contr. significations. (K.) -b4- See also 4.</p><p><b>4.</b> <b class=\"ar\">أَهْجَدَ</b> see 1: and 2. -b2- Also <span class=\"ar\">اهجدهُ</span> <i>He found him</i> (namely a man, K) <i>sleeping.</i> (L, K.) -b3- And <span class=\"ar\">اهجد</span> <i>He</i> (a camel) <i>laid the fore-part of his neck</i> (the part called <span class=\"ar\">جِرَان</span>) <i>upon the ground;</i> (ISk, S, L, K;) as also <span class=\"ar\"> <span class=\"ar\">هجّد</span></span>, (IKtt, El-Basáïr, K, TA, [in the CK <span class=\"ar\">هَجَدَ</span>]) inf. n. <span class=\"ar\">تَهْجِيدٌ</span>. (IKtt, El-Basáïr, TA.)</p><p><b>5.</b> <b class=\"ar\">تَهَجَّدَ</b> see 1, in three places.</p><p><b class=\"ar\">هَجِدْ</b> , (as in some copies of the K,) or <span class=\"ar\">هِجْدْ</span>, (accord. to others and the TA,) <i>A cry by which a horse is chidden.</i> (K.)</p><p><b class=\"ar\">هَجُودٌ</b> : see <span class=\"ar\">هَاجِدٌ</span>.</p><p><b class=\"ar\">هَاجِدٌ</b> <i>Sleeping:</i> (T, L, Msb:) pl. <span class=\"ar\">هُجُودٌ</span> and <span class=\"ar\">هُجَّدٌ</span>. (Msb.) [See an ex. in a verse cited voce <span class=\"ar\">مُرِمٌّ</span>, in art. <span class=\"ar\">رم</span>.] -b2- Also, (L,) and <span class=\"ar\"> <span class=\"ar\">هَجُودٌ</span></span> (L, K) and <span class=\"ar\"> <span class=\"ar\">مُتَهَجِّدٌ</span></span> (T, L) <i>Praying in the night:</i> (T, L, K:) pl. of the first, (L,) or second, (L, K,) <span class=\"ar\">هُجُودٌ</span> and <span class=\"ar\">هُجَّدٌ</span>. (L, K.) <span class=\"ar\">هُجْدٌ</span> and <span class=\"ar\">هُجَّدٌ</span> are also fem. pls. [app. in both of the above senses]. (A.)</p><p><b class=\"ar\">مُتَهَجِّدٌ</b> : see <span class=\"ar\">هَاجِدٌ</span>.</p>"},"هدد":{"mf":"الهَدُّ: هدم له وقع، وسقوط شيء ثقيل، والهَدَّة: صوت وقعه. قال تعالى: وَتَنْشَقُّ الْأَرْضُ وَتَخِرُّ الْجِبالُ هَدًّا<br>[مريم/ ٩٠] وهدّدت البقرة: إذا أوقعتها للذّبح، والهِدُّ:<br>المهدود كالذّبح للمذبوح، ويعبّر به عن الضّعيف والجبان، وقيل: مررت برجل هَدَّكَ من رجل <strong>«٣»</strong>، كقولك: حسبك، وتحقيقه: يَهُدُّكَ ويزعجك وجود مثله، وهَدَّدْتُ فلانا وتَهَدَّدْتُهُ: إذا زعزعته بالوعيد، والهَدْهَدَة: تحريك الصّبيّ لينام، والهُدْهُدُ: طائر معروف. قال تعالى:<br>ما لِيَ لا أَرَى الْهُدْهُدَ [النمل/ ٢٠] وجمعه:<br>هَدَاهِد، والهُدَاهِد بالضّمّ واحد، قال الشاعر:<br><br><span class=\"num\">٤٥٧-</span><table class=\"poem\"><tr><td>كهداهد كسر الرّماة جناحه </td><td> يدعو بقارعة الطريق هديلا</td></tr></table><strong>«١»</strong>","mq":[["كسر وهضم وهدم"],"الهاء والدال: أصلٌ صحيح يدلُّ على كَسْر وهَضْم وهدم.<br>وهَدَدْتُه هَدَّا: هَدَمتُه. ويرجع الباب كلُّه إلى هذا القياس. فالهَدُّ من الرِّجال:<br>الضَّعيف، كأنَّه هُدَّ. ورجال هَدُّونَ. وقد خُولف الأصمعىّ (٣) فخبّرنى علىُّ ابن إبراهيم القَطّان، عن ثعلبٍ عن ابن الأعرابى، وعن عمرو بن أبى عمرٍ وعن أبيه قالا (٤"],"ln":"<p><b>1.</b> <b class=\"ar\">هَدَّ</b> , aor. <b class=\"ar\">هَدُدَ</b> , (S, L, Msb,) inf. n. <span class=\"ar\">هَدٌّ</span> (S, L, Msb, K) and <span class=\"ar\">هُدُودٌ</span>, (L, K,) <i>He demolished</i> a a building; (As, S, A, L, K: *) <i>threw it down;</i> (TA;) <i>pulled</i> it <i>down to the ground:</i> (As, S, A, L:) <i>demolished</i> it <i>with violence:</i> (L, K: *) <i>demolished</i> it <i>at once, with a vehement noise.</i> (Msb.) -A2- [Hence you say,] <span class=\"ar\">مَا هَذُهُ كَذَا</span> (assumed tropical:) <i>Such a thing did not break him,</i> or <i>it.</i> (S, L.) -b2- <span class=\"ar\">هَدَّنِى الأَمْرُ</span>, and <span class=\"ar\">هَدَّ رُكْنى</span>, (assumed tropical:) <i>The thing distressed, and broke,</i> or <i>crashed, me.</i> And [in like manner] <span class=\"ar\">مَا هَدَّنِى مَوْتُ أَحَدٍ</span> (assumed tropical:) [<i>The death of any one has not distressed, nor broken,</i> or <i>crushed, me</i>]. (L.) And <span class=\"ar\">هَدَّتْهُ المُصِيبَةُ</span> <i>The</i> (tropical:) <i>calamity debilitated,</i> or <i>enervated, him.</i> (S, A, L.) -b3- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدَدَ</b> , and <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدٌّ</span>, <i>He</i> (a man) <i>was,</i> or <i>became, weak,</i> (L, K,) <i>in body;</i> (L:) <i>became extremely aged,</i> or <i>decrepit.</i> (TK.) -b4- See 7. -b5- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدِيدٌ</span>, <i>It</i> (a wall or the like, S, L, or a part of a mountain, L, by its falling, S, L) <i>made a noise;</i> (S;) or, <i>a violent noise.</i> (L.) -b6- <span class=\"ar\">هَدَّتْ</span> <i>It</i> (the sky) <i>sent forth a noise,</i> or <i>sound, occasioned by the falling of rain.</i> (L.) -b7- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدَدَ</b> , (L,) inf. n. <span class=\"ar\">هَدِيدٌ</span>, (S, L,) <i>It</i> (the sound called <span class=\"ar\">هَادّ</span>, from the sea,) <i>made a murmuring.</i> (S, * L.) -b8- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدٌّ</span>, <i>He</i> (a camel) <i>brayed.</i> (TK.) See also R. Q. 1. -A3- <span class=\"ar\">مَرَرْتُ بِرَجُلٍ هَدَّكَ مِنْ رَجُلٍ</span> <i>I passed by a man who is sufficient for they as a man;</i> (L, K:) as also <span class=\"ar\">هَدِّكَ</span>: (K.) an expression of praise (L:) or it means, <i>the description of whose good qualities would be burdensome to thee:</i> there are two dial. forms used in this case: some use <span class=\"ar\">هدّ</span> as an inf. n., [in the sense of an epithet, (marginal note in a copy of the S,) saying, in such a phrase as the above, <span class=\"ar\">هَدِّكَ</span>,] in which case, it has no fem. nor dual. nor pl. form; (S, L:) the sing and dual and pl. are the same: (K:) and some make it a verb, and give it [a fem. and] a dual and a pl, and say, <span class=\"ar\">مررت برجل</span> <span class=\"ar\">هَدَّكَ من رجل</span>, as above, (S, L,) and <span class=\"ar\">بٱمْرَأَةٍ</span> <span class=\"ar\">هَدَّنْكَ منِ ٱمْرَأَةٍ</span>, (S, L, K,) like as you say <span class=\"ar\">كَفّاكَ</span> and <span class=\"ar\">كَفَيْكَ</span>, (L.,) and <span class=\"ar\">بِرَجُلَيْنِ هَدَّاكَ</span>, and <span class=\"ar\">بِرِجَالٍ هَدُّوكَ</span>, and <span class=\"ar\">بِٱمْرَأَتَيْنِ هَدَّتَاكَ</span>, and <span class=\"ar\">بِنِسْوَةِ</span> <span class=\"ar\">هَدَدْتَكَ</span>. (S, L, K.) -b2- IAar also cites the following ex. [by El-Kattál El-Kilábee, (marginal note in a copy of the S)] <span class=\"ar\">وَلِى صَاحِبٌ فِى الغَارِ هَدَّكَ صَاحِبًا</span> as meaning. [<i>And I have a companion in the race;</i>] <i>of how great estimation, and how ingenious, and how knowing, is he</i> [<i>as a companion</i>] describing a wolf: (L:) in which he who reads <span class=\"ar\">هَدَّكَ</span> makes <span class=\"ar\">هَدَّ</span> a verb; and as such it has a dual and pl. and fem. but some read <span class=\"ar\">هَدُّكَ</span>. making it an inf. n. used as an epithet; and as such it has no dual nor pl. nor fem. (Marginal note in a copy of the S.) -b3- <span class=\"ar\">هَدَّ الرَّجُلُ</span> also signifies <i>Excellent is the man;</i> (ISd, L:) and <span class=\"ar\">إِنّهُ لَهَدَّ الرَّجُلُ</span> <i>Verily, excellent is the man</i> (L, K) <i>in hardiness and strength:</i> (L:) and <span class=\"ar\">لَهَدَّ</span> <span class=\"ar\">الرَّجُلُ</span> <i>How hardy is the man!</i> (L.) -b4- In a trad., Aboo Lahab is related to have said, <span class=\"ar\">لَهَدَّ مَا سَخَرَكُمْ صَاحِبُكُمْ</span>, [meaning <i>How greatly hath your companion enchanted you!</i>): <span class=\"ar\">لَهَدَّ</span> is an expression of wonder. (L.) -b5- <span class=\"ar\">فُلَانٌ يُهَدُّ</span> <i>Such a one is praiseworthy for hardiness</i> (S, L, K) <i>and strength.</i> (S, L.)</p><p><b>2.</b> <b class=\"ar\">هدّدهُ</b> , (Msb, K,) inf. n. <span class=\"ar\">تَهْدِيدٌ</span> (S, L) and <span class=\"ar\">تَهْدَادٌ</span>; (L:) and <span class=\"ar\"> <span class=\"ar\">تهدّدهُ</span></span>: (S, L, Msb;) <i>He threatened him;</i> (L;) <i>threatened him with punishment;</i> (Msb;) <i>frightened,</i> or <i>terrified, him.</i> (S, L, K.)</p><p><b>5.</b> <b class=\"ar\">تَهَدَّدَ</b> see 2.</p><p><b>7.</b> <b class=\"ar\">انهدّ</b> <i>It</i> (a building) [<i>fell down:</i> or] <i>became demolished at once, with a vehement noise:</i> (Msb:) and <span class=\"ar\"> <span class=\"ar\">هَدَّ</span></span>, aor. <b class=\"ar\">هَدِدَ</b> , <i>it</i> (a wall) <i>fell down;</i> mentioned by AHei; and also by Es-Semeen, who concedes it; (MF;) but this form of the verb is commonly known only as transitive. (TA.) -b2- <i>It</i> (a mountain) <i>broke down.</i> (S, L.)</p><p><b>10.</b> <b class=\"ar\">استهدّهُ</b> <i>He regarded him as weak.</i> (L.)</p><p><b>R. Q. 1.</b> <b class=\"ar\">هَدْهَدَ</b> , (S, L, K,) inf. n. <span class=\"ar\">هدْهَدَةٌ</span>, (S, L,) <i>He</i> (a bird) <i>cooed;</i> syn. <span class=\"ar\">قَرْقَرَ</span>: (L, K, TA [in the CK, <span class=\"ar\">فَرْفَرَ</span>]:) <i>he</i> (a pigeon) <i>cooed</i> syn. <span class=\"ar\">هَدَرَ</span>, and <span class=\"ar\">هَدَلَ</span>: (TA:) or <i>made a murmuring</i> or <i>confused noise</i> in cooing: (S, L, accord to the explanation of <span class=\"ar\">هَدْهَدَةٌ</span>:) and <i>he</i> (a camel, S, L) <i>brayed:</i> syn. <span class=\"ar\">هَدَرَ</span>: (K:) or <i>made a murmuring</i> or <i>confused noise</i> in braying (S, L,) See also 1. -b2- <span class=\"ar\">هَدْهَدَتْ</span>, (inf. n. <span class=\"ar\">هَدْهَدةٌ</span>, L.) <i>She</i> (a woman, S, L) <i>shook,</i> or <i>rocked,</i> a child (S, L, K) in its cradle, (L,) <i>in order that it might sleep.</i> (S, L, K.) -A2- <span class=\"ar\">هَدْهَدَ</span> <i>He sent,</i> or <i>threw,</i> a thing <i>down,</i> from a high place to a low one, (L, K.)</p><p><b class=\"ar\">هَدٌّ</b> A <i>weak</i> man; (As, S, L, K;) i. e., <i>weak in body;</i> (L;) as also <span class=\"ar\"> <span class=\"ar\">هِدٌّ</span></span>: (K:) or, accord. to IAar, the latter only, meaning <i>cowardly and weak:</i> (S, L:) or <span class=\"ar\">هَدٌّ</span> (Sh, L) and <span class=\"ar\"> <span class=\"ar\">أَهدُّ</span></span> (L, K) and <span class=\"ar\"> <span class=\"ar\">هَدَادَةٌ</span></span> (Sh, L, K) signify a <i>cowardly</i> (<i>and weak,</i> TA) man: (Sh, L, K:) and <span class=\"ar\">قَوْمٌ <span class=\"ar\">هَدَادٌ</span></span> <i>a cowardly people:</i> (Sh, L:) pl. of <span class=\"ar\">هَدٌّ</span>, <span class=\"ar\">هَدُّونَ</span>: (L, K:) it has no broken pl. (L:) and of <span class=\"ar\">هِدٌّ</span>, <span class=\"ar\">هِدّٰونَ</span>. (K.) A man says to another, in threatening him, <span class=\"ar\">إِنِّى لَعَيْرُ هَدٍّ</span> <i>Verily I am not weak.</i> (S, L.) -b2- <span class=\"ar\">هَدٌّ</span> <i>Extreme odd age; decrepitude.</i> (K, TA.) See 1. -A2- <span class=\"ar\">هَدٌّ</span> <i>A cough,</i> or <i>harsh, sound;</i> as also <span class=\"ar\"> <span class=\"ar\">هَدَدٌ</span></span>. (L, K.) -b2- <span class=\"ar\">هَدٌّ</span> The <i>braying</i> of a camel. (Lh, L, K.) See 1. -A3- <span class=\"ar\">هَدٌّ</span> <i>A generous, liberal. beautiful</i> man. (IAar. S, L, K. *) -b2- A <i>strong</i> man. (IAar. L.) -b3- <span class=\"ar\">لِى صَاحِبٌ هَدُّكَ صَاحِبًا</span>, and <span class=\"ar\">مَرَرْتُ بِرَجُلٍ هَدِّكَ مِنْ</span> <span class=\"ar\">رَجُلٍ</span>: see 1.</p><p><b class=\"ar\">هِدٌّ</b> and <span class=\"ar\">هَدَرٌ</span>: see <span class=\"ar\">هَدٌّ</span>.</p><p><b class=\"ar\">هَدَّةٌ</b> The <i>sound of the fall of a wall</i> or <i>the like:</i> (S:) or <i>a violent sound occasional thereby,</i> or <i>by the fall of a part of a mountain.</i> (L.) -b2- The <i>sound of rain falling from the sky.</i> (L.) -b3- <i>A sinking, and falling in, of the ground.</i> (L.)</p><p><b class=\"ar\">هَدْهَدٌ</b> The <i>voices,</i> or <i>cries, of jinn,</i> or <i>genii:</i> without a singular. (L, K)</p><p><b class=\"ar\">هُدْهُدٌ</b> <i>A certain bird,</i> (S, L, Msb, K,) <i>well known;</i> (L, Msb, K;) [namely, the <i>hoopee,</i> or <i>upupa</i> of Linnæus; so this bird is called in the present day; and this, accord. to a common tradition, is the bird mentioned in the Kur, xxvii. 20;] as also <span class=\"ar\">هُدَهِدٌ</span> (K) and <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (S, L, K:) or the last, <i>a certain bird resembling the pigeon:</i> (Lth, Az, L:) or (in the K, and) <span class=\"ar\">هُدْهُدٌ</span> signifies <i>a pigeon that cooes much;</i> (IDrd in explanation of v. 20 of ch. xxvii. of the Kur., and AHn, L K;) as also <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (IDrd, AHn, L:) and <i>any bird that cooes; that utters the cry called</i> <span class=\"ar\">قَرْقَرَة</span>; (L, K, TA [in the CK, <span class=\"ar\">يُفَرْفِرُ</span> is put for <span class=\"ar\">يُقَرْقِرُ</span>]) as also <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (As, L:) pl. (of all, K) <span class=\"ar\">هَدَاهِدُ</span> (S, L, K) and <span class=\"ar\">هَدَاهِيدُ</span>: (Kr, L, K:) but ISd says of the latter, I know not how this is, unless the sing. be <span class=\"ar\">هَدْهَادٌ</span>. (L.) Er-Rá'ee says, <span class=\"ar\">كَهُدَاهِدٍ كَسَرَ الرُّمَاةُ جَنَاحَهُ</span> [<i>Like a</i> <span class=\"ar\">هداهد</span> <i>whose wing the shooters have broken</i>]: (S, L:) As says, he means the <span class=\"ar\">فَاخِتَة</span>, or the <span class=\"ar\">دُبْسِىّ</span>, or the <span class=\"ar\">وَرَشَان</span>, or the <span class=\"ar\">هُدْهُد</span>, or a man, or camels: and Lh says, that Ks asserts him to mean, by <span class=\"ar\">هداهد</span>, the dim. of <span class=\"ar\">هُدْهُدٌ</span>: but As disapproves of this; and so does ISd; but the latter adds, that it may perhaps be for <span class=\"ar\">هُدَيْهِدٌ</span>; as some of the Arabs say <span class=\"ar\">دُوَابَّةٌ</span> and <span class=\"ar\">شُوَابَّةٌ</span> for <span class=\"ar\">دُويْبَّةٌ</span> and <span class=\"ar\">شُوَيْبَّةٌ</span>; though they are only known to change the <span class=\"ar\">ى</span> into <span class=\"ar\">ا</span> before a double consonant. (L.)</p><p><b class=\"ar\">هَدْهَدَةٌ</b> [an inf. n. used as a simple subst.] The <i>murmuring</i> or <i>confused sound of</i> the <i>cooing</i> of pigeons, and <i>of</i> the <i>braying</i> of a camel [and of thunder (see <span class=\"ar\">زَمْزَمَةٌ</span>)]: pl. <span class=\"ar\">هَدَاهِدُ</span>. (S, L.)</p><p><b class=\"ar\">هَدَادٌ</b> and <span class=\"ar\">هَدَادَةٌ</span>: see <span class=\"ar\">هَدٌّ</span>.</p><p><b class=\"ar\">هُدَاهِدٌ</b> A stallion-camel <i>that brays much among the she-camels but does not cover them.</i> (L.) -b2- See <span class=\"ar\">هُدْهُدٌ</span>.</p><p><b class=\"ar\">هَدِيدٌ</b> <i>A voice, cry, sound,</i> or <i>noise.</i> (L.) See also 1. -b2- <i>A threatening from behind one.</i> (As, L.)</p><p><b class=\"ar\">هَادٌّ</b> <i>A certain murmuring sound from the sea;</i> (K;) <i>a sound which is heard by people inhabiting the sea-shore, coming to them from the direction of the sea, murmuring over the land, and sometimes followed by an earthquake.</i> (S, L.)</p><p><b class=\"ar\">هَادَّةٌ</b> <i>Thunder.</i> (L, K.) Ex. <span class=\"ar\">مَا سَمِعْنَا العَامَ هَادَّةً</span> <i>We have not heard this year thunder.</i> (L.)</p><p><b class=\"ar\">أَهَدُّ</b> : see <span class=\"ar\">هَدٌّ</span>.</p>"},"هشش":{"mf":"الْهَشُّ: يقارب الهزّ في التّحريك، ويقع على الشيء اللّيّن كَهَشِّ الورق، أي: خبطه بالعصا.<br>قال تعالى: وَأَهُشُّ بِها عَلى غَنَمِي<br>[طه/ ١٨] وهَشَّ الرّغيف في التّنّور يَهِشُّ، وناقة هَشُوشٌ: ليّنة غزيرة اللّبن، وفرس هَشُوشٌ <strong>«١»</strong> :<br>ضدّ الصّلود، والصّلود: الذي لا يكاد يعرق.<br>ورجل هَشُّ الوجه: طلق المحيّا، وقد هَشَشْتُ، وهَشَّ للمعروف يَهِشُّ، وفلان ذو هَشَاشٍ.","mq":[["رخاوة ولين"],"الهاء والشين: أصلٌ صحيحٌ يدلُّ على رَخاوةٍ وليِن. والرِّخْو اللَّيِّن هَشٌّ. ومنه رجل هشٌّ: طَلْق المُحيَّا، وقد هَشِشتَ (٢)<br>، وذُو هَشَاش (٣)<br>.<br>والفرس الهَشُّ: الكثير العَرَق. وشَاةٌ هَشُوشٌ: ثَرَّةٌ (٤)<br>.<br>ومن الباب هَشَشْتُ الورقَ هشّاً: خبطتُه بعَصاً.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَشَّ</b> , aor. <span class=\"ar\">يَهِشُّ</span>; (JK, TA;) or <span class=\"ar\">هَشَّ</span>, secpers. <span class=\"ar\">هَشِشْتَ</span>, aor. <span class=\"ar\">يَهَشُّ</span>; (Msb;) inf. n. <span class=\"ar\">هَشَاشَةٌ</span> (JK, A, Msb, TA) [and <span class=\"ar\">هُشُوشَةٌ</span> and <span class=\"ar\">هُشُوشٌ</span> and <span class=\"ar\">هَشٌّ</span>, as appears from what follows]; <i>It,</i> (a thing) <i>was,</i> or <i>became, soft, yielding, flaccid, flabby, lax, slack, uncompact, crummy, fragile, frangible, brittle, friable, easily</i> or <i>quickly broken;</i> (JK, A, Msb, TA;) syn. <span class=\"ar\">كَانَ فِيهِ رَخَاوَةٌ</span>, (JK,) or <span class=\"ar\">كَانَ رِخْوًا لَيِّنًا</span>, (A, * TA,) or <span class=\"ar\">لَانَ وَٱسْتَرْخَى</span>. (Msb.) You say, <span class=\"ar\">هَشَّ الخُبْزُ</span>, aor. <b class=\"ar\">هَشِشَ</b> , (S, K,) inf. n. <span class=\"ar\">هُشُوشَةٌ</span> (K) and <span class=\"ar\">هَشٌّ</span>, (TA,) meaning, <span class=\"ar\">صار</span> <span class=\"ar\">هَشًّا</span>; (S, K;) i. e., <i>The bread became</i> [<i>soft, &amp;c.,</i> or] <i>easy to break.</i> (TA.) And <span class=\"ar\">هَشَّ العُودُ</span>, (IAar, Msb,) aor. [ <b class=\"ar\">هَشِشَ</b> , or] <b class=\"ar\">هَشَشَ</b> , (Msb,) inf. n. <span class=\"ar\">هُشُوشٌ</span>, (IAar, Msb,) <i>The wood,</i> or <i>stick, broke in pieces:</i> (IAar:) or <i>became easily</i> or <i>quickly broken.</i> (Msb.) And <span class=\"ar\">هَشَّتِ الشَّجَرَةُ</span>, inf. n. <span class=\"ar\">هَشٌّ</span>, <i>The tree dropped its leaves, one after another.</i> (Msb [in which it seems to be indicated that the aor. of the verb in this sense is <b class=\"ar\">هَشُشَ</b> ; but this is contr. to rule in an intrans. verb of this class; and I think it improbable.]) -b2- <span class=\"ar\">هَشَّ</span>, inf. n. <span class=\"ar\">هُشُوشَةٌ</span>, (assumed tropical:) <i>He</i> (a man) <i>became weak; unable to endure difficulty</i> or <i>distress.</i> (TA.) And <span class=\"ar\">هَشَّ</span>, aor. <b class=\"ar\">هَشِشَ</b> , (assumed tropical:) <i>He affected languor,</i> or <i>languidness;</i> syn. <span class=\"ar\">تَكَسَّرَ</span>: and <i>he became old,</i> or <i>aged.</i> (TA.) -A2- <span class=\"ar\">هَشَّ</span>, (Msb, K,) first pers. <span class=\"ar\">هَشِشْتُ</span>, (S, Msb, K,) aor. <span class=\"ar\">يَهَشُّ</span>; (Msb, K,) and <span class=\"ar\">هَشَّ</span>, first pers. <span class=\"ar\">هَشَشْتُ</span>, aor. <span class=\"ar\">يَهِشُّ</span>; (Msb, K;) inf. n. <span class=\"ar\">هَشَاشَةٌ</span> (S, Msb, K) and <span class=\"ar\">هَشَاشٌ</span>; (A, K;) (tropical:) <i>He was,</i> or <i>became, cheerful, brisk, lively,</i> or <i>sprightly:</i> (S, K:) or <i>he smiled, and was,</i> or <i>became cheerful, brisk, lively,</i> or <i>sprightly.</i> (Msb.) You say, <span class=\"ar\">هَشِشْتُ بِفُلَانٍ</span>, (S, TA,) and <span class=\"ar\">هَشَشْتُ بِهِ</span>, (TA,) (tropical:) <i>I was,</i> or <i>became, cheerful,</i> &amp;c. <i>in behaviour towards such a one:</i> (S:) or <i>I was,</i> or <i>became cheerful in countenance,</i> or <i>joyful,</i> or <i>pleased, at meeting with such a one.</i> (TA.) And <span class=\"ar\">هُوَ يَهَشُّ إِلَى إِخْوَانِهِ</span>, (tropical:) <i>He is cheerful,</i> &amp;c., <i>towards his brethren</i>]. (A.) And <span class=\"ar\">دَخَلْتُ عَلَيْهِ <span class=\"ar\">فَٱهْتَشَّ</span>بِى</span> (tropical:) [<i>I went in to him, and he was cheerful,</i> &amp;c., <i>in his behaviour towards me</i>]; like <span class=\"ar\">إِهْتَزَّ لى</span>. (A, * TA.) And <span class=\"ar\">هَشِشْتُ لِلْمَعْرُوفِ</span>, (JK, TA, *) and <span class=\"ar\">هَشَشْتُ</span>, (TA,) inf. n. <span class=\"ar\">هَشَاشَةٌ</span> (S) and <span class=\"ar\">هَشَاشٌ</span>, (A,) (tropical:) <i>I was,</i> or <i>became, cheerful, brisk,</i> &amp;c., <i>to do what was kind,</i> or <i>beneficent:</i> (S, * TA:) or <i>I desired to do it:</i> (JK:) and <span class=\"ar\"> <span class=\"ar\">إِهْتَشَشْتُ</span> للمعروف</span> <i>I was,</i> or <i>became, cheerful,</i> &amp;c., <i>and desirous, to do what was kind,</i> or <i>beneficent.</i> (TA.) And <span class=\"ar\">هُوَ ذُو هَشَاشٍ إِلَى الخَيْرِ</span> (tropical:) [<i>He possesses cheerfulness, briskness, liveliness,</i> or <i>sprightliness, of disposition to do good</i>]. (A.) Accord. to Sh, <span class=\"ar\">هَشِشْتُ</span> signifies (assumed tropical:) <i>He rejoiced, and desired;</i> or <i>was,</i> or <i>became, joyful, and desirous.</i> (TA.) And the phrase <span class=\"ar\">هَشِشْتُ إِلَى ٱمْرَأَتِى</span>, if correct, means either (assumed tropical:) <i>I inclined towards my wife,</i> or <i>I was,</i> or <i>became, brisk,</i> or <i>sprightly, in disposition towards her.</i> (Mgh.) And accord to ISd, <span class=\"ar\">هَشَاشُ القَوْمِ</span> [so in the TA, but accord. to the JK <span class=\"ar\">هَشَاهِشُ</span>,] (assumed tropical:) <i>The people's being in a state of commotion,</i> or <i>agitation.</i> (TA.) -A3- <span class=\"ar\">هَشَّ الوَرَقَ</span>, aor. <b class=\"ar\">هَشُشَ</b> , (S, A, K,) and <b class=\"ar\">هَشِشَ</b> , (Sgh, K,) inf. n. <span class=\"ar\">هَشٌّ</span>, (S,) <i>He beat the leaves</i> with a staff, or stick, <i>in order that they might fall;</i> (S, A, K;) as also <span class=\"ar\"> <span class=\"ar\">هَشْهَشَهُ</span></span>. (Z, TA.) It is said in the Kur, [xx. 19,] (S,) <span class=\"ar\">وَأَهُشُّ بِهَا عَلَى غَنَمِى</span> [<i>And I beat the leaves with it in order that they may fall upon my sheep,</i> or <i>goats</i>]: (S, A:) or, accord. to Fr, <i>and I beat the dry trees with it in order that their leaves may fall so that my sheep,</i> or <i>goats, may feed upon them;</i> and so says As: (TA:) Lth says, that <span class=\"ar\">الهَشُّ</span> signifies thy <i>drawing towards thee a branch of a tree:</i> and also, thy <i>scattering its leaves towards thee with a staff,</i> or <i>stick:</i> (JK, * TA:) but Az says, that the correct ex- planation is that given by Fr and As; not the former of the two explanations given by Lth. (TA.) [The verb also seems to have a similar application in a more extended sense; for it is said that] <span class=\"ar\">هَشَّ</span>, aor. <b class=\"ar\">هَشُشَ</b> , inf. n. <span class=\"ar\">هَشٌّ</span>, signifies He (a man) assaulted (<span class=\"ar\">صَالَ</span>) with his staff, or stick. (Msb.) You say also, <span class=\"ar\">هَشَّ الهَشِيمَ</span> <i>He broke in pieces the dry herbage</i> or <i>the like.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">هشّشهُ</b> , (JK, K,) inf. n. <span class=\"ar\">تَهْشِيشٌ</span>, (TA,) (assumed tropical:) <i>He deemed him,</i> or <i>reckoned him, weak,</i> or <i>feeble,</i> (JK, K, *) <i>and soft,</i> or <i>gentle.</i> (TA.) -A2- (tropical:) <i>He,</i> or <i>it, rendered him brisk, lively,</i> or <i>sprightly; and joyful, glad,</i> or <i>happy:</i> (K:) and <span class=\"ar\"> <span class=\"ar\">استهشّهُ</span></span> (tropical:) <i>it</i> (a thing, JK, TA) <i>incited him,</i> or <i>excited him, to briskness, liveliness</i> or <i>sprightliness;</i> syn. <span class=\"ar\">إِسْتَخَفَّهُ</span>. (JK, K, TA.) You say, <span class=\"ar\">فُلَانٌ مَا <span class=\"ar\">يَسْتَهِشُّهُ</span> النَّعِيمُ</span> (tropical:) [<i>Such a one, weal,</i> or <i>welfare, does not excite him to briskness,</i> &amp;c.] (A, TA.)</p><p><b>8.</b> <b class=\"ar\">اهتشّ</b> <i>He was,</i> or <i>became, cheerful,</i> &amp;c.: see 1, in two places.</p><p><b>10.</b> <b class=\"ar\">إِسْتَهْشَشَ</b> see 2, in two places.</p><p><b>R. Q. 1.</b> <b class=\"ar\">هَشْهَشَهُ</b> : see 1, latter part. -b2- <i>He moved,</i> or <i>put in motion,</i> or <i>into a state of commotion, him, or it.</i> (IDrd, K.)</p><p><b class=\"ar\">هَشٌّ</b> A thing, (S, Msb,) or anything, (JK,) <i>soft, yielding, flaccid, flabby, lax, slack, uncompact, crummy, fragile, frangible, brittle, friable, easily</i> or <i>quickly broken;</i> (JK, * S, * A, * Msb, K, * TA;) syn. <span class=\"ar\">رِخْوٌ لَيِّنٌ</span>; (S, A, K;) as also <span class=\"ar\"> <span class=\"ar\">هَشِيشٌ</span></span>. (JK, S, K.) You say, <span class=\"ar\">خُبْزٌ هَشٌّ</span>, (S, K,) and <span class=\"ar\"> <span class=\"ar\">هَشَاشٌ</span></span>, (K,) <i>Bread that is</i> [<i>soft,</i> &amp;c., or] <i>easy to break.</i> (TA.) And <span class=\"ar\">خُبْزَةٌ هَشَّةٌ</span> <i>A lump of dough, baked in a fire in the ground, that is dry,</i> or <i>hard:</i> asserted by IKtt to have two contr. significations. (TA.) [But to this assertion it may be replied, that dry bread is easy to break.] And in like manner, <span class=\"ar\">أُتْرُجَّةٌ هَشَّةٌ</span> <i>A citron easy to break:</i> or <i>dry,</i> or <i>hard.</i> (TA.) And <span class=\"ar\">عُودٌ هَشٌّ</span> <i>Wood,</i> or <i>a stick, that is easily,</i> or <i>quickly broken.</i> (Msb.) -b2- [Hence,] <span class=\"ar\">هُوَ هَشٌّ</span> <span class=\"ar\">المَكْسِرِ</span>, (JK, S, A, K,) or <span class=\"ar\">المَكْسَرِ</span>, (TA, [but this is contr. to all the other authorities that I know,]) and <span class=\"ar\">المُكَسَّرِ</span>, (TA,) (tropical:) <i>He is easy,</i> or <i>compliant, when asked:</i> (A:) or <i>he is of easy nature,</i> or <i>disposition,</i> (JK, S, K,) <i>with respect to what is sought,</i> or <i>demanded, of him, of things needed:</i> (S:) said in praise of a man (S, TA) when it means [lit.] that he is not one whose wood gives only a sound when one endeavours to produce fire from it; but said in dispraise of a man when it means [lit.] that he is one whose wood is weak. (TA.) [And in like manner] <span class=\"ar\"> <span class=\"ar\">هَشِيشٌ</span></span> (K) and <span class=\"ar\"> <span class=\"ar\">هَاشٌّ</span></span> (TA) signify (tropical:) One <i>who rejoices,</i> or <i>is glad, when asked.</i> (K, TA.) You say, <span class=\"ar\">هُوَ <span class=\"ar\">هَاشٌ</span> عِنْدَ السُّؤَالِ</span>, and <span class=\"ar\"> <span class=\"ar\">هَشِيشٌ</span></span>, (tropical:) <i>He is one who rejoices,</i> or <i>is glad, at being asked.</i> (TA.) -b3- [Hence also,] <span class=\"ar\">رَجُلٌ هَشٌّ</span>, (TA,) or <span class=\"ar\">رَجُلٌ هَشٌّ إِلَى إِخْوَانِهِ</span>, and <span class=\"ar\"> <span class=\"ar\">هَاشٌّ</span></span>, (JK,) (tropical:) <i>A man who is cheerful, brisk, lively,</i> or <i>sprightly, in his behaviour towards his brethren.</i> (JK, TA.) And <span class=\"ar\">رَجُلٌ هَشٌّ بَشٌّ</span> (tropical:) <i>A man who is cheerful, brisk, lively,</i> or <i>sprightly:</i> (S:) or <i>cheerful in countenance; pleasant</i> [<i>therein</i>]. (S, TA in art. <span class=\"ar\">بش</span>.) And <span class=\"ar\">أَنَا بِهِ هَشٌّ بَشٌّ</span> (tropical:) <i>I am cheerful, brisk, lively,</i> or <i>sprightly, in behaviour towards him;</i> (K;) <i>joyful; happy.</i> (TA.) And <span class=\"ar\">رَجُلٌ هَشٌّ فُؤَادُهُ</span> (tropical:) <i>A man quick,</i> or <i>prompt, to do good.</i> (As.) And <span class=\"ar\">فَرَشٌ هَشُّ</span> <span class=\"ar\">العِنَانِ</span> (assumed tropical:) [<i>A horse that is brisk, lively,</i> or <i>sprightly;</i> lit.,] <i>light of rein.</i> (TA.) And <span class=\"ar\">فَرَسٌ هَشٌّ</span> (tropical:) <i>A horse that sweats much;</i> (JK, IF, K;) <i>contr. of</i> <span class=\"ar\">صَلُودٌ</span>; (S;) or <i>not</i> <span class=\"ar\">صلود</span>. (A.)</p><p><b class=\"ar\">هَشُاشٌ</b> : see <span class=\"ar\">هَشٌّ</span>, second sentence.</p><p><b class=\"ar\">هَشُوشٌ</b> (assumed tropical:) A ewe, or she-goat, <i>abounding with milk.</i> (S, K.)</p><p><b class=\"ar\">هَشِيشٌ</b> <i>Dry herbage,</i> syn. <span class=\"ar\">هَشِيمٌ</span>, (K, TA,) <i>for the horses of the people of</i> <span class=\"ar\">الأَسْيَاف</span> [app. meaning <i>the shores of 'Omán</i>] <i>in particular.</i> (TA.) -A2- See also <span class=\"ar\">هَشٌّ</span>, in three places. -b2- Also, (assumed tropical:) A man <i>who is niggardly towards his family,</i> or <i>others, with respect to food;</i> syn. <span class=\"ar\">مُحْتِرٌ</span>. (TA.) [Thus it bears two contr. significations.]</p><p><b class=\"ar\">هَشِيشَةٌ</b> is thought by ISd to signify <i>Leaves</i> [app. <i>beaten from a tree</i>]. (TA.)</p><p><b class=\"ar\">قِرْبَةٌ هَشَّاشَةٌ</b> <i>A water-skin from which the water flows by reason of its thinness.</i> (K.)</p><p><b class=\"ar\">هَشْهَشَةٌ</b> (assumed tropical:) <i>Motion;</i> or <i>commotion.</i> (JK.) [<span class=\"ar\">هَشَاهِشُ</span> is app. its pl.: see 1, next before <span class=\"ar\">هَشَّ</span> <span class=\"ar\">الوَرَقَ</span>.]</p><p><b class=\"ar\">هَشْهَاشٌ</b> (tropical:) <i>Good in disposition; liberal,</i> or <i>bountiful.</i> (IAar, K.)</p><p><b class=\"ar\">هَاشٌّ</b> : see <span class=\"ar\">هَشٌّ</span>, in three places.</p><p><b class=\"ar\">مُهَشْهِشَةٌ</b> , in the copies of the K erroneously written <span class=\"ar\">مُتَهَشْهِشَة</span>, (TA,) (assumed tropical:) A woman <i>who manifests love to her husband, and rejoices in him.</i> (K, * TA.)</p>"},"همس":{"mf":"الْهَمْسُ: الصوت الخفيّ، وهَمْسُ الأقدام:<br>أخفى ما يكون من صوتها. قال تعالى: فَلا تَسْمَعُ إِلَّا هَمْساً<br>[طه/ ١٠٨].","mq":[["خفاء صوت وحس"],"الهاء والميم والسين يدلُّ على خَفاءِ صَوتٍ وحِسٍّ. منه الهَمْس: الصَّوت الخفِىّ. وهَمْسُ الأقدام أخَفَى ما يكونُ من وطءِ القدَم.<br>وأمَّا قولهُم الهَمَّاس: الأسَد الشَّديد، فمِنْ هذا عندنا أيضاً، لأنّه إنَّما يُراد به هَمْسُه إمَّا فى وَطْئه وإمَّا فى عَضِّه. قال:<br>* عادتُه خَبْطٌ وعضٌّ هَمّاسْ (٣) *<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَمَس</b> , aor. <b class=\"ar\">هَمِسَ</b> , (A, TA,) inf. n. <span class=\"ar\">هَمْس</span> (AHeyth, L, TA) and <span class=\"ar\">هَمِيسٌ</span> and <span class=\"ar\">هُمُوسٌ</span>, (L, TA,) <i>He spoke inaudibly:</i> (AHeyth, TA:) or <i>in a low, faint, gentle,</i> or <i>soft, manner,</i> (AHeyth, TA,) <i>so as to be hardly intelligible.</i> (TA.) It is said in a trad. <span class=\"ar\">فَجَعَلَ بَعْضُنَا يَهْمِسُ إِلَى بَعْضٍ</span> <i>And some of us began to speak to others in a low, faint, gentle,</i> or <i>soft, manner, so as to be hardly intelligible.</i> (TA.) And in another trad., <span class=\"ar\">كَانَ</span> <span class=\"ar\">ذَا إِصَلَّى العَصْرَ هَمَسَ بِشَىْءٍ لَا نَفْهَمُهُ</span> <i>He used, when he performed the afternoon-prayer, to utter something in a low, faint, gentle,</i> or <i>soft manner, we not understanding it.</i> (TA.) You say also, <span class=\"ar\">هَمَسَ إِلَىَّ بِحَدِيثِهِ</span> [<i>He uttered his discourse to me inaudibly:</i> or <i>in a low, faint, gentle,</i> or <i>soft, manner.</i>] (A.) And <span class=\"ar\">الشَّيْطَانُ يَهْمِسُ بِوَسْوَسَتِهِ صَدْرَ</span> <span class=\"ar\">الإِنْسَانِ</span> [<i>The devil speaks inaudibly in his suggesting vain</i> or <i>unprofitable things into the bosom of man</i>]. (A.) And <span class=\"ar\">هَمَسَ الشَّيْطَانُ فِى الصَّدْرِ</span> <i>The devil suggested vain,</i> or <i>unprofitable things in the bosom;</i> syn. <span class=\"ar\">وَسْوَسَ</span>. (TA.) See also <span class=\"ar\">هَمْسٌ</span> below. -b2- Also, aor. and inf. n. as above, <i>He made the faintest,</i> or <i>slightest, sound in treading.</i> So in the saying, <span class=\"ar\">إِهْمِسْ وَصَهْ</span> and <span class=\"ar\">هَمْسًا وَصَهْ</span> <i>Make thou the faintest,</i> or <i>slightest, sound in treading, and be thou silent:</i> addressed by a thief to his companion. (TA.) And hence the saying of the Rájiz, <span class=\"ar\">فَهُنَّ يَمْشِينَ بِهِ هَمِيسَا</span> <i>And they walk with him making the faintest,</i> or <i>slightest, sound in treading.</i> (S.) <span class=\"ar\">هَمِيسٌ</span> also signifies The <i>walking softly; with a soft-sounding tread:</i> (TA:) [and so <span class=\"ar\">هَمْسٌ</span>; as in the saying,] <span class=\"ar\">سَمِعْتُ هَمْسَ الأَخْفَافِ وَالأَقْدَامِ</span> [<i>I heard the soft-sounding treading of the feet of camels and of the feet of men</i>]. (A.) See also <span class=\"ar\">هَمْسٌ</span> below. -A2- <span class=\"ar\">هَمَسَ الصَّوْتَ</span>, aor. <b class=\"ar\">هَمِسَ</b> , inf. n. <span class=\"ar\">هَمْسٌ</span>, <i>He made the sound,</i> or <i>voice to be low, faint, gentle,</i> or <i>soft.</i> (Msb.) And <span class=\"ar\">هَمَسَ الكَلَامَ</span>, [aor. and] inf. n. as above, [<i>He spoke in a low, faint, gentle,</i> or <i>soft manner;</i> like <span class=\"ar\">هَمَسَ</span> alone; lit.,] <i>he made speech,</i> or <i>the speech to be low, faint, gentle,</i> or <i>soft.</i> (A, TA.) -A3- <span class=\"ar\">هَمَسَ الطَّعَامَ</span>, (TK), [aor. and] inf. n. as above, (AZ, K,) <i>He chewed the food with the mouth closed:</i> (AZ, K, TA:) or <i>without opening the mouth.</i> (TA.) You say, <span class=\"ar\">هُوَ يَْكُلُ هَمْسًا</span> <i>He eats without opening his mouth.</i> (A.) Hence, a toothless old woman's eating is termed <span class=\"ar\">هَمْسٌ</span>. (AHeyth.) <span class=\"ar\">هَمَسَهُ</span> also signifies [simply] <i>He chewed it.</i> (TA.)</p><p><b>3.</b> <b class=\"ar\">هامسهُ</b> , inf. n. <span class=\"ar\">مُهَامَسَةٌ</span>, <i>He spoke,</i> or <i>discoursed secretly to him,</i> or <i>with him.</i> (A.) You say also, <span class=\"ar\">هَامَسُوا</span>, (TK,) inf. n. as above, (K,) <i>They spoke,</i> or <i>discoursed, secretly together;</i> as also <span class=\"ar\"> <span class=\"ar\">تهامسوا</span></span>. (K, * TK.)</p><p><b>6.</b> <b class=\"ar\">تَهَاْمَسَ</b> see 3.</p><p><b class=\"ar\">هَمْسٌ</b> <i>A low, faint, gentle,</i> or <i>soft, sound.</i> (S, A, Msb, K.) So it has been explained as occurring in the words of the Kur, [xx. 107,] <span class=\"ar\">فَلَا</span> <span class=\"ar\">تَسْمَعُ إِلَّا هَمْسًا</span> [<i>So that thou shalt not hear</i> aught <i>save</i>] <i>a low, faint, gentle,</i> or <i>soft, sound,</i> arising from the shifting of the feet from place to place towards the scene of congregation [for the general judgment]: or, as Az thinks, the meaning here is, <i>the sound of the patting,</i> or <i>pattering, of the feet</i> (<span class=\"ar\">خَفْقَ الأَقْدَامِ</span>) <i>upon the ground.</i> (TA.) -b2- The <i>faint,</i> or <i>gentle, sound of the voice in the mouth, of such kind as has no mixture of the voice of the chest, nor loudness of utterance.</i> (Lth, K.) See also <span class=\"ar\">مَهْمُوسٌ</span>. -b3- And <i>Anything low, faint, gentle,</i> or <i>soft,</i> (<span class=\"ar\">كُلُّ خَفِىٍّ</span>, K, TA,) <i>of speech</i> and <i>the like:</i> (TA:) [see again, <span class=\"ar\">مَهْمُوسٌ</span>:] or the <i>faintest,</i> or <i>slightest, sound of the feet;</i> (S, K;) i. e., <i>of their tread upon the ground:</i> (TA:) so [accord. to J] in the instance in the Kur, [xx. 107,] mentioned above: (S:) and [in like manner] <span class=\"ar\"> <span class=\"ar\">هَمِيسٌ</span></span> signifies the <i>sound of the shifting from place to place of the feet of camels.</i> (K.) See also 1.</p><p><b class=\"ar\">هَمِيسٌ</b> : see 1: and see <span class=\"ar\">هَمْسٌ</span>.</p><p><b class=\"ar\">كَلَامٌ مَهْمُوسٌ</b> [<i>Speech spoken inaudibly:</i> or <i>in a low, faint, gentle,</i> or <i>soft manner, so as to be hardly intelligible:</i> see 1: or] <i>speech not spoken out</i> or <i>openly.</i> (A, * Msb.) -b2- <span class=\"ar\">حَرْفٌ مَهْمُوسٌ</span>, (Msb,) or <span class=\"ar\">حَرْفُ الهَمْسِ</span>, (IJ,) [<i>A letter which is pronounced with the breath only, without the voice; a non-vocal letter; a sound with which the breath passes forth, not from the voice of the chest, but passing forth gently;</i> (IJ;) <i>contr. of</i> <span class=\"ar\">مَجْهُورٌ</span>: (Msb:) <span class=\"ar\">الحُرُوفُ المَهْمُوسَةُ</span> are <i>the letters</i> (<i>ten in number,</i> S,) <i>which are comprised in the saying</i> <span class=\"ar\">حَثَّهُ شَخْصٌ فَسَكَتْ</span>: (S, K: *) so called [accord. to some] because the stress is made weak in the place where any one of them occurs until the breath has passed forth with it. (Sb, S.)</p>"},"هضم":{"mf":"الْهَضْمُ: شدخ ما فيه رخاوة، يقال: هَضَمْتُهُ فَانْهَضَمَ، وذلك كالقصبة الْمَهْضُومَةِ التي يزمّر بها، ومزمار مُهْضَمٌ. قال تعالى: وَنَخْلٍ طَلْعُها هَضِيمٌ<br>[الشعراء/ ١٤٨] أي: داخل بعضه في بعض كأنما شدخ، والْهَاضُومُ: ما يَهْضِمُ الطّعام وبطن هَضُومٌ، وكشح مِهْضَمٌ وامرأة هَضِيمَةٌ الكشحين، واستعير الْهَضْمُ للظّلم. قال تعالى: فَلا يَخافُ ظُلْماً وَلا هَضْماً<br>[طه/ ١١٢].<br>","mq":[["كسر وضغط وتداخل وهضمت الشي هضما: كسرته"],"الهاء والضاد والميم: أَصلٌ صحيح يدلُّ على كَسرٍ وضَغطٍ وتداخُل وهضَمت الشّئَ هضماً: كسرتُه. ومِزمارٌ مُهَضَّم، لأنَّه فيما يزعمون أكسارٌ يضمُّ بعضُها إلى بعض. والهاضوم: الذى يَهضِم الطَّعام، وأُراه مولَّدا. وكشحٌ مُهضَّم. وامرأةٌ هضيمة الكَشْحَين: لطيفَتُهما، كأنَّهما ضَغِطا. والهَضَم: انضمامُ أَعْل"],"ln":"<p><b>1.</b> <b class=\"ar\">هضَمَهُ</b> and <b class=\"ar\">اِهْتَضَمَهُ</b> : see <span class=\"ar\">تَخَوَّفَهُ</span>. -b2- <span class=\"ar\">هَضَمَ لَهُ</span> <span class=\"ar\">مِنْ مَالِهِ</span>: see <span class=\"ar\">خَضَمَ</span>.</p><p><b>5.</b> <b class=\"ar\">تَهَضَّمَ</b> see 7.</p><p><b>7.</b> <b class=\"ar\">اِنْهَضَمَ</b> <i>It</i> (a thing) <i>melted,</i> or <i>dissolved, after being congealed.</i> (JK.) -b2- <span class=\"ar\">اِنْهَضَمَتِ الثَّمَرَةُ</span>, and <span class=\"ar\"> <span class=\"ar\">تَهَضَّمَت</span></span>, <i>The fruit broke;</i> or <i>became broken,</i> or <i>crushed;</i> syn. <span class=\"ar\">تَشَدَّخَتْ</span>; (TA;) and <i>became mellow, so as to be easy of digestion.</i> See also <span class=\"ar\">بَوْعٌ</span> -b3- <span class=\"ar\">اِنْهَضَمَ</span>, said of food, (MA), <i>It was,</i> or <i>became, digestible,</i> or <i>easy of digestion.</i> (MA, KL.) -b4- <span class=\"ar\">اِنْهضَامٌ</span> of the <span class=\"ar\">زَوْر</span> [app. <i>Depression</i>]. (K in art. <span class=\"ar\">جنف</span>. [There coupled with <span class=\"ar\">دُخُولٌ</span>.]) See also <span class=\"ar\">صَقَلٌ</span>.</p><p><b>8.</b> <b class=\"ar\">إِهْتَضَمَ</b> see 1. -b2- <span class=\"ar\">اِهْتَضَمَ الشَّجَزَ مِنْ أَعَلاَهُ</span> (K voce <span class=\"ar\">شَعَبَ</span>) <i>He cropped the tops of the shrubs:</i> see <span class=\"ar\">شَعَبَ</span>.</p><p><b class=\"ar\">هَضَمٌ</b> <i>Contraction of the sides,</i> (S, K,) <i>and lankness of the belly, and smallness of the flank:</i> (K:) in a horse it is a fault. (S.)</p><p><b class=\"ar\">هَضُومٌ</b> : see <span class=\"ar\">هَاضُومٌ</span>.</p><p><b class=\"ar\">هَاضُومٌ</b> <i>Any medicine</i> [or <i>other thing</i> (see <span class=\"ar\">حَاطُومٌ</span>)] <i>that is a digestive of food;</i> as also <span class=\"ar\"> <span class=\"ar\">هَضُومٌ</span></span>; (K;) <i>i. q.</i> <span class=\"ar\">جَوَارِشٌ</span>. (S.)</p>"},"همد":{"mf":"يقال: هَمَدَتِ النّارُ: طفئت، ومنه: أرض هَامِدَةٌ: لا نبات فيها، ونبات هَامِدٌ: يابس. قال تعالى: وَتَرَى الْأَرْضَ هامِدَةً [الحج/ ٥] والإِهْمَادُ: الإقامة بالمكان كأنّه صار ذا هَمَدٍ، وقيل:<br>الإِهْمَادُ السّرعة، فإن يكن ذلك صحيحا فهو كالإشكاء في كونه تارة لإزالة الشكوى، وتارة لإثبات الشّكوى.","mq":[["خمود شي"],"الهاء والميم والدال: أصلٌ يدلُّ على خمودِ شئ. وهَمَدت النار:<br>طَفِئَتْ البَتّة. وأرضٌ هامدة: لا نباتَ بها (١)<br>. ونباتٌ هامد: يابس.<br>والإهماد: الإفامة بالمكان.<br>ومما شذَّ عن هذا الباب قول من قال: إنَّ الإهماد: السُّرعة فى المَشْى.<br>قال:<br>* ما كانَ إلاَّ طَلَقُ الإهمادِ (٢) *<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَمَدَتِ النَّارُ</b> , aor. <b class=\"ar\">هَمُدَ</b> , (S, A, L,) inf. n. <span class=\"ar\">هُمُودٌ</span>, (S, A, L, K,) <i>The fire became extinguished</i> (As, S, A, L, K) <i>entirely; went out entirely,</i> (As, S, A, L,) <i>none of it remaining:</i> (L:) or <i>lost its heat:</i> (L, K:) when [only] its flame has ceased, you say of it <span class=\"ar\">خَمَدَت</span>. (As, L.) -b2- <span class=\"ar\">هَمَدَ</span>, (M, A, L,) aor. <b class=\"ar\">هَمُدَ</b> , (M, L,) inf. n. <span class=\"ar\">هُمُودٌ</span>, (M, L, K,) (tropical:) <i>He died;</i> [<i>became extinct;</i>] (M, A, L, K;) <i>perished;</i> (TA;) like as did Thamood; (Lth, A, L;) as also <span class=\"ar\">خَمَدَ</span>. (A.) -b3- <span class=\"ar\">كَاد يَهَمْدُ مِنَ الجُوعِ</span> (tropical:) <i>He nearly perished of hunger.</i> (L.) -b4- <span class=\"ar\">هَمَدَ</span>, aor. <b class=\"ar\">هَمُدَ</b> , (S, A, L,) inf. n. <span class=\"ar\">هُمُودٌ</span> (S, L, K) and <span class=\"ar\">هَمْدٌ</span>, (L, K,) (tropical:) <i>It</i> (a garment, or piece of cloth,) <i>became dissundered</i> (L, K) <i>and worn-out,</i> (S, A, L, Msb,) <i>by being long folded,</i> (A, L, Msb, K,) <i>so that a person looking at it would imagine it sound, but, when he touched it, would find it fall to pieces.</i> (A, * L, Msb. *) -b5- <span class=\"ar\">هَمَدَت الرِّيحُ</span> (assumed tropical:) <i>The wind became still.</i> (Msb.) -b6- <span class=\"ar\">هَمَدَتِ الأَرْضُ</span>, inf. n. <span class=\"ar\">هُمُودٌ</span>, (tropical:) <i>The land became lifeless, without herbage, without wood, and without rain.</i> (L, K.) -b7- <span class=\"ar\">هَمَدَ شَجَرُ الأَرْضِ</span> (tropical:) <i>The trees of the land became worn-out,</i> or <i>wasted; and perished.</i> (L.) -b8- <span class=\"ar\">هَمَدَتْ أَصْوَاتُهُمْ</span> (assumed tropical:) <i>Their voices became silent.</i> (L.)</p><p><b>4.</b> <b class=\"ar\">اهمد</b> , inf. n. <span class=\"ar\">إِهَمَادٌ</span>, (assumed tropical:) <i>He stilled,</i> or <i>quieted.</i> (K.) -b2- <i>He</i> (God, and a man,) <i>killed,</i> or <i>destroyed,</i> a man, or men. (A.) -b3- <span class=\"ar\">اهمد الأَمْرَ</span> (tropical:) <i>He put an end to the affair.</i> (A.) -b4- <span class=\"ar\">اهمد القَحْطُ الأَرْضَ</span> (tropical:) <i>Drought rendered the land sterile, so that it contained no herbage but such as was dried up and broken.</i> (L.) -b5- <span class=\"ar\">اهمد</span>, (inf. n. <span class=\"ar\">إِهْمَادٌ</span>, K.) (assumed tropical:) <i>He kept silence in an unpleasant case.</i> (L, K.) -b6- <span class=\"ar\">اهمد</span>, (S, L,) inf. n. <span class=\"ar\">إِهْمَادٌ</span>, (L, K,) <i>He remained, continued, stayed, abode,</i> or <i>dwelt,</i> (S, L, K,) in a place: (S, L:) <i>he was still;</i> (K;) i. e., <i>did not move.</i> (TA.) -A2- <span class=\"ar\">اهمد</span>, (S, L) inf. n. <span class=\"ar\">إِهْمَادٌ</span>, (L, K,) <i>He hastened,</i> or <i>was quick,</i> (S, L, K,) in going along: (S, L:) thus it bears two contr. significations: (S, L, K:) <i>he</i> (a dog) <i>ran;</i> syn. <span class=\"ar\">أَحْضَرَ</span>. (L.) -A3- <span class=\"ar\">اهمدوا فِى الطَّعَامِ</span>, (inf. n. <span class=\"ar\">إِهْمَادٌ</span>, K,) <i>They fell to eating of the food.</i> (Ibn-Buzurj, L, K. *)</p><p><b class=\"ar\">هَمِدٌ</b> : see <span class=\"ar\">هَامِدٌ</span>.</p><p><b class=\"ar\">هَمْدَةٌ</b> (assumed tropical:) <i>Apoplexy: caros:</i> syn. <span class=\"ar\">سَكْتَةٌ</span>. (S, L.) -b2- [<i>A trance.</i> (See <span class=\"ar\">رَقْدَةٌ</span>.)]</p><p><b class=\"ar\">همِيدٌ</b> (tropical:) <i>Sheep</i> or <i>goats that have died:</i> (L:) or the <i>beasts</i> or <i>the like</i> (<span class=\"ar\">مال</span>) <i>that are registered in the government-accounts as due from a man.</i> (ISh, L, K.) You say, <span class=\"ar\">آخَذَنَا مالْهَمِيدِ</span> <i>He</i> (the collector) <i>exacted from us taking for the sheep</i> or <i>goats that had died:</i> (L:) or, <i>taking what was registered as due from us in the governmentaccounts.</i> (ISh, L.) -b2- See <span class=\"ar\">هَامِدٌ</span>.</p><p><b class=\"ar\">هَامِدٌ</b> and <span class=\"ar\"> <span class=\"ar\">هَمِدٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">هَمِيدٌ</span></span> (tropical:) <i>In a state of death,</i> or <i>extinction</i>]. (M, L.) -b2- <span class=\"ar\">هَامِدٌ</span> (tropical:) A garment, or piece of cloth, [<i>dissundered and</i>] <i>wornout by being long folded, so as, when touched, to fall to pieces:</i> (A:) or anything <i>old and wornout:</i> (L, Msb:) pl. <span class=\"ar\">هُمَّدٌ</span>. (A.) See 1. -b3- <span class=\"ar\">أَرْضٌ هَامِدَةٌ</span> (tropical:) <i>Land in which is no herbage:</i> (S:) and in the same sense <span class=\"ar\">هَامِدٌ</span> is applied to a place: (K:) or <i>sterile land,</i> (A, L,) <i>the herbage of which is dried up and broken,</i> (A,) or <i>containing no herbage except what is dried up and broken:</i> (L:) <i>dry and dusty:</i> pl. <span class=\"ar\">هَوَامِدُ</span>. (L.) -b4- <span class=\"ar\">هَامِدٌ</span> (tropical:) <i>Old and worn-out</i> or <i>wasted, blackened, and changed,</i> [<i>for the worse</i>]. (K.) -b5- (tropical:) A tree <i>black and wasted:</i> (L:) or <i>dried up;</i> (A;) as also herbage. (S, L, K.) -b6- (tropical:) Fruit <i>black and stinking.</i> (A, L.) -b7- (tropical:) A date just ripe, <i>thickskinned and yellow.</i> (TA.) <span class=\"ar\">رَمَادٌ هَامِدٌ</span> <i>Ashes</i> [<i>in a state of extinction</i> or] <i>wasted,</i> (L,) <i>and compacted together, and changed in appearance.</i> (A, L.)</p><p><b class=\"ar\">هَمْدَةٌ</b> <i>A trance:</i> so rendered voce <span class=\"ar\">رَقْدَةٌ</span>.</p>"},"هدم":{"mf":"الهدم: إسقاط البناء. يقال: هَدَمْتُهُ هَدْماً.<br>والهَدَمُ: ما يهدم، ومنه استعير: دم هَدْمٌ. أي:<br>هدر، والهِدْمُ بالكسر كذلك لكن اختصّ بالثّوب البالي، وجمعه: أهدام، وهدّمت البناء على التّكثير. قال تعالى: لَهُدِّمَتْ صَوامِعُ [الحج/ ٤٠].","mq":[["حط بناء"],"الهاء والدال والميم: أصلٌ يدلُّ على حَطِّ بناء، ثم يقاس عليه.<br>وهَدَمت الحائطَ أهدِمُه. والهَدَم: ما تهدَّم، بفتح الدال.<br>ومن الباب الهِدْم: الثَّوب البالى، والجمع أهْدام. ودماؤُهم هَدَم أى هَدَرٌ، كأنَّها قد هُدمَتْ فلم يُطلَب بها. و<br>قوله ﷺ<br>: «الدَّمُ الدَّمُ، والهَدَمُ الهَدَمُ»<br>. قيل إنَّ معناه: مَ"],"ln":"<p><b>1.</b> <b class=\"ar\">هَدَمَ</b> <i>He threw down,</i> or <i>pulled down,</i> a building; (Msb;) <i>pulled</i> it <i>to pieces; demolished</i> it; <i>destroyed</i> it: (K:) [the last two explanations are the most correct, as is shown by the phrase] <span class=\"ar\">نَقَضَ البِنَآءَ مِنْ عَيْرِ هَدْمِ</span> [<i>He took to pieces the building without demolishing,</i> or <i>destroying</i>]: (S, A, Msb, K, * in art. <span class=\"ar\">قوض</span>:) <i>he ruined</i> [a building, &amp;c.]; <i>reduced</i> [it] <i>to ruin.</i> (Ham, p. 31.)</p><p><b>6.</b> <b class=\"ar\">تَهَادَمَتِ الحِيطَانُ</b> [<i>The walls fell to ruin by degrees</i>]. (S, in art. <span class=\"ar\">دعو</span>.)</p><p><b>7.</b> <b class=\"ar\">اِنْهَدَمَ</b> <i>It became thrown down, pulled down, pulled to pieces, demolished,</i> or <i>destroyed:</i> and <i>it fell in ruins,</i> or <i>to pieces;</i> or <i>became a ruin.</i> -b2- <span class=\"ar\">اِنْهَدَمَ الحَائِطُ مِنْ مَكَانِهِ مِنْ غَيْرِ هَدْمٌ</span> [<i>The wall fell in ruins,</i> or <i>to pieces, from its place, without being pulled to pieces</i>]. (Lth, in TA, art. <span class=\"ar\">قيض</span>.)</p><p><b class=\"ar\">الدَّمُ الدَّمُ وَالهَدَْمُ الهَدَْمُ</b> : see <span class=\"ar\">دَمْ</span>.</p><p><b class=\"ar\">هَدَمٌ</b> <i>Earth that is dug from a pit</i> or <i>well:</i> see <span class=\"ar\">حَفَرٌ</span>.</p>"},"همز":{"mf":"الْهَمْزُ كالعصر. يقال: هَمَزْتُ الشيء في كفّي، ومنه: الْهَمْزُ في الحرف، وهَمْزُ الإنسان:<br>اغتيابه. قال تعالى: هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ<br>[القلم/ ١١] يقال: رجل هَامِزٌ، وهَمَّازٌ، وهُمَزَةٌ.<br>قال تعالى: وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ<br><strong>[الهمزة/ ١] وقال الشّاعر:</strong><br><span class=\"num\">٤٧١-</span><br>وإن اغتيب فأنت الْهَامِزُ اللُّمَزَهْ<br><strong>«١»</strong> وقال تعالى: وَقُلْ رَبِّ أَعُوذُ بِكَ مِنْ هَمَزاتِ الشَّياطِينِ<br>[المؤمنون/ ٩٧].","mq":[["ضغط وعصر"],"الهاء والميم والزاء كلمةٌ تدلُّ على ضَغْطٍ وعَصْر. وهَمزْت الشَّئَ فى كفِّى. ومنه الهَمز فى الكلام، كأنَّه يَضْغَط الحرف. ويقولون: همزَ بِهِ<br>الأرض (١)<br>. وقوسٌ هَمَزَى: شديدةُ الدَّفعِ للسَّهم. والهمَّاز: العَيَّاب، وكذا الهُمَزَة. قال:<br>تُدْلِى بوُدِّىَ إذْ لاقَيتَنِى كذِباً … وإنْ أُغيَّبْ فأنت الها"],"ln":"<p><b>1.</b> <b class=\"ar\">هَمَزَهُ</b> , (S, A, Msb, K,) aor. <b class=\"ar\">هَمِزَ</b> (S, Msb, K) and <b class=\"ar\">هَمُزَ</b> , (K,) inf. n. <span class=\"ar\">هَمْزٌ</span>, (S, Msb, K,) <i>He pressed it; squeezed it; pinched it;</i> (S, A, Msb, K,) as, for instance, a walnut, (A, TA,) or other thing, (S, TA,) in the hand; (S, A, TA,) and a man's head; (S, A, TA;) and a spearshaft, with the <span class=\"ar\">مَهَامِز</span>, to straighten it. (TA.) -b2- <i>He pushed, impelled,</i> or <i>repelled, him</i> or <i>it,</i> (S, K, TA,) meaning anything; as also <span class=\"ar\">لَمَزَهُ</span> &amp;c. (TA.) You say, <span class=\"ar\">هَمَزَتْهُ إِلَيْهِ الحَاجَةُ</span> <i>Want impelled,</i> or <i>drove, him to him</i> or <i>it.</i> (TA.) -b3- <i>He struck,</i> or <i>beat, him;</i> (S, K, TA;) as also <span class=\"ar\">لَمَزَهُ</span> &amp;c. (TA.) -b4- <i>He goaded,</i> or <i>spurred, him;</i> (K, TA;) <i>he urged him on</i> (namely a horse) <i>with the</i> <span class=\"ar\">مِهْمَاز</span>, <i>to make him run.</i> (Msb.) -b5- <i>He bit him.</i> (IAar, K.) -b6- <i>He broke it.</i> (K.) -A2- (tropical:) <i>He</i> (the devil) <i>suggested evil to his mind.</i> (JK, A, TA.) You say, <span class=\"ar\">أَعُوذُ بِٱللّٰهِ مِنْ هَمْزِهِ</span>; and <span class=\"ar\">مِنْ هَمَزَاتِ الشَّيَاطِينِ</span>; (tropical:) <i>I seek refuge in God from his</i> [the devil's] <i>evil suggestion;</i> and <i>from the evil suggestions of the devils.</i> (A.) -A3- (tropical:) <i>He blamed, upbraided,</i> or <i>reproached, him; he found fault with him;</i> syn. of the inf. n. <span class=\"ar\">عَيْبٌ</span>, (Fr, in TA, art. <span class=\"ar\">لمز</span>; and IAar, in TA, in the present art.) as also <span class=\"ar\">لَمْزٌ</span>: (Fr, in TA, art. <span class=\"ar\">لمز</span>; and S,) or <i>he spoke evil of him,</i> or <i>spoke of him in a manner that he disliked, mentioning vices</i> or <i>faults as chargeable to him, behind his back, though it might be with truth;</i> syn. <span class=\"ar\">إِغْتَابَهُ فِى</span> <span class=\"ar\">غَيْبَتِهِ</span>: (Msb:) and [so] <span class=\"ar\">هَمَزَهُ فِى قَفَاهُ</span> <i>he backbit him.</i> (JK, A.) -A4- <span class=\"ar\">هَمَزَ الحَرْفَ</span>, (S, O,) or <span class=\"ar\">الكَلِمَةَ</span>, aor. <b class=\"ar\">هَمِزَ</b> , inf. n. <span class=\"ar\">هَمْزٌ</span>, (Msb,) [<i>He pronounced the word with the sound termed</i> <span class=\"ar\">هَمْز</span>, or <span class=\"ar\">هَمْزَة</span>, <i>of which the sign is</i> <span class=\"ar\">ء</span>,] is from <span class=\"ar\">هَمَزَهُ</span> in the first of the senses explained above; (S, Msb,) because what is termed <span class=\"ar\">هَمْز</span> in speech, (S,) or <span class=\"ar\">هَمْزَة</span>, (Kh, TA,) [i. e. the sound so called,] is [as it were] pressed, or squeezed, (Kh, S, TA,) from its place of utterance [by a sudden emission of the voice forced out after a compression of the passage whereby it has been stopped]. (Kh, TA.) It was said to an Arab of the desert, <span class=\"ar\">أَتَهْمِزُ الفَأْرَةَ</span>, [meaning <i>Dost thou pronounce</i> <span class=\"ar\">الفَأْرَة</span> <i>with hemz,</i> or <i>hemzeh?</i>] and he said, [understanding the words to mean <i>dost thou squeeze the rat,</i> or <i>mouse?</i>] <span class=\"ar\">السِّنَّوْرُ يَهْمِزُهَا</span> [<i>The cat squeezes it</i>]. (S.) See <span class=\"ar\">هَمْزٌ</span>, below. [And see also <span class=\"ar\">نَبَرَ</span>.]</p><p><b>7.</b> <b class=\"ar\">انهمز</b> [quasi-pass. of <span class=\"ar\">هَمَزَهُ</span>; <i>It was pressed, squeezed,</i> or <i>pinched: he was pushed,</i> &amp;c. The first of these significations is indicated, or implied, in the JK and the TA.] -b2- <span class=\"ar\">انهمز الحَرْفُ</span> [<i>The word was pronounced with the sound termed</i> <span class=\"ar\">هَمْز</span>, or <span class=\"ar\">هَمْزَة</span>]. (S.)</p><p><b class=\"ar\">هَمْزُ الشَّيْطَانِ</b> was explained by Mohammad as meaning (tropical:) <i>Madness,</i> or <i>insanity;</i> syn. <span class=\"ar\">مُوتَةٌ</span>, i. e. <span class=\"ar\">جُنُونٌ</span>; because it arises from the goading and pressing or pinching of the devil. (A 'Obeyd, K.) See 1; and see also <span class=\"ar\">هَمَزَات</span>, voce <span class=\"ar\">هَمْزَةٌ</span>. -A2- <span class=\"ar\">هَمْزٌ</span>, (S,) and <span class=\"ar\">هَمْزَةٌ</span>, (Kh, TA,) [the former a gen. n., and the latter the n. un.,] The <i>sister of alif; one of the letters of the alphabet;</i> [<i>written thus</i>;] a genuine word, old, heard [from the Arabs of classical times], and well known; so called for a reason mentioned above: see 1, last signification: so says Kh; therefore no regard is due to what is said in certain of the expositions of the Keshsháf, that the term <span class=\"ar\">همزة</span> thus used has not been heard [from any of the Arabs of classical times], and that its name is <span class=\"ar\">أَلْفٌ</span>: (TA:) several persons say, that the term <span class=\"ar\">همزة</span> is mostly applied to the movent [alif], and <span class=\"ar\">الف</span> to the quiscent letter. (MF, TA.) See the letter <span class=\"ar\">ا</span>.</p><p><b class=\"ar\">هَمْزَةٌ</b> n. un. of <span class=\"ar\">هَمْزٌ</span>, q. v. -b2- <span class=\"ar\">هَمَزَاتُ الشَّيَاطِينِ</span> (tropical:) <i>The vain suggestions of the devils, which they inspire into the mind of a man.</i> (S, TA.) See also 1; and see <span class=\"ar\">هَمْزٌ</span>.</p><p><b class=\"ar\">هُمَزَةٌ</b> <i>i. q.</i> <span class=\"ar\">غَمَّازٌ</span>; (K;) i. e., (TA,) One <i>who blames, upbraids, reproaches,</i> or <i>finds fault with, others, much,</i> or <i>habitually;</i> (S, TA;) as also <span class=\"ar\"> <span class=\"ar\">هَمَّازٌ</span></span> (S, TA) and <span class=\"ar\"> <span class=\"ar\">هَامِزٌ</span></span>; (S, K;) and so <span class=\"ar\">لُمَزَةٌ</span>: (S, K, art. <span class=\"ar\">لمز</span>:) [or rather] the first and second are intensive epithets (TA) [but the third is not intensive]: or one <i>who backbites his brother;</i> as also <span class=\"ar\"> <span class=\"ar\">هَمَّازٌ</span></span>: (Lth, A, TA:) or one <i>who defames men</i> (<span class=\"ar\">يَخْلُفُهُمْ مِنْ وَرَائِهِمْ وَبَأْكُلُ</span> <span class=\"ar\">لُحُومَهُمْ</span>); and the action thus signified is like <span class=\"ar\">غِيبَةٌ</span>, and may be [<i>by making signs</i>] <i>with the side of the mouth,</i> and <i>with the eye,</i> and <i>with the head;</i> as also <span class=\"ar\"> <span class=\"ar\">هَمَّازٌ</span></span>: (TA:) or, conjointly with <span class=\"ar\">لُمَزَةٌ</span>, one <i>who speaks evil of men,</i> or <i>backbites them, and defames them:</i> (Aboo-Is-hák, TA:) or both together, one <i>who goes about much,</i> or <i>habitually, with calumny,</i> or <i>slander, separating companions and exciting enmity between friends:</i> (Abu-l-'Abbás, TA:) <span class=\"ar\">هُمَزَةٌ</span> is applied to a man and to a woman; (S, TA;) [like <span class=\"ar\">لَمُزَةٌ</span>;] for its <span class=\"ar\">ة</span> is to denote intensiveness, and not the fem. gender: (TA:) <span class=\"ar\"> <span class=\"ar\">هُمَّازٌ</span></span> [which is the pl. of <span class=\"ar\">هَامِزٌ</span>] signifies persons <i>who blame, upbraid, reproach,</i> or <i>find fault with, others behind their backs, much,</i> or <i>habitually:</i> (IAar, TA:) [or, more correctly, it has not an intensive signification.] See also <span class=\"ar\">لُمَزَةٌ</span>.</p><p><b class=\"ar\">هَمَّازٌ</b> : see <span class=\"ar\">هُمَزَةٌ</span>, throughout.</p><p><b class=\"ar\">هَامِزٌ</b> : see <span class=\"ar\">هُمَزَةٌ</span>, throughout.</p><p><b class=\"ar\">مِهْمَزٌ</b> : see <span class=\"ar\">مِهْمَازٌ</span>.</p><p><b class=\"ar\">مِهْمَزَةٌ</b> <i>An instrument for beating,</i> (<span class=\"ar\">مَقْرَعَةٌ</span>, AHeyth, K, TA,) <i>of copper</i> or <i>brass,</i> [app. meaning <i>a kind of spur,</i> or <i>a goad,</i>] <i>with which beasts of carriage are urged on:</i> pl. <span class=\"ar\">مَهَامِزُ</span>: (AHeyth, TA:) or <i>a staff</i> or <i>stick:</i> (K:) or <i>a staff,</i> or <i>stick, with an iron in its head, with which the ass is goaded,</i> or <i>urged on.</i> (Sh, K.) See also <span class=\"ar\">مِهْمَازٌ</span>. -b2- [The pl., <span class=\"ar\">مَهَامِزُ</span>, of this word or of <span class=\"ar\">مِهْمَزٌ</span>, is also applied to <i>An instrument,</i> or <i>instruments, with which spear-shafts are pinched and straightened:</i> see 1, first signification.]</p><p><b class=\"ar\">مِْهَمازٌ</b> and <span class=\"ar\"> <span class=\"ar\">مِهْمَزٌ</span></span> (S, Msb, K) <i>A well-known thing;</i> (Msb;) [namely, <i>a spur;</i>] <i>an iron which is</i> [<i>attached</i> or <i>fixed</i>] <i>in the kinder part of the boot of him who breaks,</i> or <i>trains, beasts of carriage:</i> (S, K:) pl. [of the former] <span class=\"ar\">مَهَامِيزُ</span> (K) and [of the latter] <span class=\"ar\">مَهَامِزُ</span>. (S, K.) See also <span class=\"ar\">مِهْمَزَة</span>.</p>"},"هيم":{"mf":"يقال: رجل هَيْمَانُ، وهَائِمٌ: شديد العطش، وهَامَ على وجهه: ذهب، وجمعه: هِيمٌ، قال تعالى: فَشارِبُونَ شُرْبَ الْهِيمِ [الواقعة/ ٥٥] والْهُيَامُ: داء يأخذ الإبل من العطش، ويضرب به المثل فيمن اشتدّ به العشق، قال:<br>أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وادٍ يَهِيمُونَ<br>[الشعراء/ ٢٢٥] أي: في كلّ نوع من الكلام يغلون في المدح والذّمّ، وسائر الأنواع المختلفات، ومنه: الْهَائِمُ على وجهه المخالف للقصد الذاهب على وجهه، وهَامَ: ذهب في الأرض، واشتدّ عشقه، وعطش، والْهِيمُ: الإبل العطاش، وكذلك الرّمال تبتلع الماء، والْهِيَامُ من الرمل:<br>اليابس، كأنّ به عطشا.","mq":[["عطش شديد"],"الهاء والياء والميم كلمةٌ تدلُّ على عطَشٍ شديد. فالهَيَمان:<br>العَطَش. والهِيمُ: الإبل العِطاش، والهِيمُ: الرِّمال التى تَبْتَلِع الماء. والهُيام:<br>داءٌ يأخذُ الإبلَ عند عطَشِها فتَهِيم فى الأرض لا تَرعَوِى. وبه سمِّى العاشق الهَيْمَانَ، كأنَّه جُنَّ من العِشْق فذَهَب على وجهه [على] غير قصد. والهَيْماء"],"ln":"<p><b>2.</b> <b class=\"ar\">هَيَّمَهُ</b> : see <span class=\"ar\">هُيُومٌ</span>.</p><p><b class=\"ar\">هَيَامٌ</b> : see an ex. in a verse of Lebeed, voce <span class=\"ar\">أَصْلٌ</span>.</p><p><b class=\"ar\">هُيَامٌ</b> : see <span class=\"ar\">هُبٌّ</span>.</p><p><b class=\"ar\">هُيُومٌ</b> [The <i>being bewildered,</i> or <i>distracted, by amorous desire;</i>] the <i>pursuing a heedless,</i> or <i>an inconsiderate course,</i> or <i>going at random, heedlessly,</i> or <i>without consideration,</i> or <i>certain aim, by reason of amorous desire:</i> and <span class=\"ar\">تَهْيَامٌ</span> the [<i>being so,</i> or] <i>doing so, much.</i> (TA.) You say, of love [or amorous desire], <span class=\"ar\"> <span class=\"ar\">هَيَّمَهُ</span></span>, inf. n. <span class=\"ar\">تَهْيِيمٌ</span>. (TA.) -b2- <i>An affection like insanity arising from amorous desire:</i> (JK:) <i>bewilderment,</i> or <i>distraction, by amorous desire.</i> (KL.)</p><p><b class=\"ar\">هَيْمَانُ</b> A man <i>loving intensely,</i> or <i>very passionately</i> or <i>fondly:</i> (TA:) and so applied to a heart: see <span class=\"ar\">شَنِقٌ</span>. -b2- <span class=\"ar\">هَيْمَانُ</span> <i>A thirsty</i> camel: fem. <span class=\"ar\">هَيْمَى</span>: pl. <span class=\"ar\">هِيمٌ</span>. (Jel, lvi. 55.)</p><p><b class=\"ar\">مَهْيُومٌ</b> : see voce <span class=\"ar\">قَتَّ</span>.</p>"},"هدهد":{"mq":[["كسر وهضم وهدم"],"الهاء والدال: أصلٌ صحيح يدلُّ على كَسْر وهَضْم وهدم.<br>وهَدَدْتُه هَدَّا: هَدَمتُه. ويرجع الباب كلُّه إلى هذا القياس. فالهَدُّ من الرِّجال:<br>الضَّعيف، كأنَّه هُدَّ. ورجال هَدُّونَ. وقد خُولف الأصمعىّ (٣) فخبّرنى علىُّ ابن إبراهيم القَطّان، عن ثعلبٍ عن ابن الأعرابى، وعن عمرو بن أبى عمرٍ وعن أبيه قالا (٤"],"ln":"<p><b>1.</b> <b class=\"ar\">هَدَّ</b> , aor. <b class=\"ar\">هَدُدَ</b> , (S, L, Msb,) inf. n. <span class=\"ar\">هَدٌّ</span> (S, L, Msb, K) and <span class=\"ar\">هُدُودٌ</span>, (L, K,) <i>He demolished</i> a a building; (As, S, A, L, K: *) <i>threw it down;</i> (TA;) <i>pulled</i> it <i>down to the ground:</i> (As, S, A, L:) <i>demolished</i> it <i>with violence:</i> (L, K: *) <i>demolished</i> it <i>at once, with a vehement noise.</i> (Msb.) -A2- [Hence you say,] <span class=\"ar\">مَا هَذُهُ كَذَا</span> (assumed tropical:) <i>Such a thing did not break him,</i> or <i>it.</i> (S, L.) -b2- <span class=\"ar\">هَدَّنِى الأَمْرُ</span>, and <span class=\"ar\">هَدَّ رُكْنى</span>, (assumed tropical:) <i>The thing distressed, and broke,</i> or <i>crashed, me.</i> And [in like manner] <span class=\"ar\">مَا هَدَّنِى مَوْتُ أَحَدٍ</span> (assumed tropical:) [<i>The death of any one has not distressed, nor broken,</i> or <i>crushed, me</i>]. (L.) And <span class=\"ar\">هَدَّتْهُ المُصِيبَةُ</span> <i>The</i> (tropical:) <i>calamity debilitated,</i> or <i>enervated, him.</i> (S, A, L.) -b3- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدَدَ</b> , and <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدٌّ</span>, <i>He</i> (a man) <i>was,</i> or <i>became, weak,</i> (L, K,) <i>in body;</i> (L:) <i>became extremely aged,</i> or <i>decrepit.</i> (TK.) -b4- See 7. -b5- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدِيدٌ</span>, <i>It</i> (a wall or the like, S, L, or a part of a mountain, L, by its falling, S, L) <i>made a noise;</i> (S;) or, <i>a violent noise.</i> (L.) -b6- <span class=\"ar\">هَدَّتْ</span> <i>It</i> (the sky) <i>sent forth a noise,</i> or <i>sound, occasioned by the falling of rain.</i> (L.) -b7- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدَدَ</b> , (L,) inf. n. <span class=\"ar\">هَدِيدٌ</span>, (S, L,) <i>It</i> (the sound called <span class=\"ar\">هَادّ</span>, from the sea,) <i>made a murmuring.</i> (S, * L.) -b8- <span class=\"ar\">هَدَّ</span>, aor. <b class=\"ar\">هَدِدَ</b> , inf. n. <span class=\"ar\">هَدٌّ</span>, <i>He</i> (a camel) <i>brayed.</i> (TK.) See also R. Q. 1. -A3- <span class=\"ar\">مَرَرْتُ بِرَجُلٍ هَدَّكَ مِنْ رَجُلٍ</span> <i>I passed by a man who is sufficient for they as a man;</i> (L, K:) as also <span class=\"ar\">هَدِّكَ</span>: (K.) an expression of praise (L:) or it means, <i>the description of whose good qualities would be burdensome to thee:</i> there are two dial. forms used in this case: some use <span class=\"ar\">هدّ</span> as an inf. n., [in the sense of an epithet, (marginal note in a copy of the S,) saying, in such a phrase as the above, <span class=\"ar\">هَدِّكَ</span>,] in which case, it has no fem. nor dual. nor pl. form; (S, L:) the sing and dual and pl. are the same: (K:) and some make it a verb, and give it [a fem. and] a dual and a pl, and say, <span class=\"ar\">مررت برجل</span> <span class=\"ar\">هَدَّكَ من رجل</span>, as above, (S, L,) and <span class=\"ar\">بٱمْرَأَةٍ</span> <span class=\"ar\">هَدَّنْكَ منِ ٱمْرَأَةٍ</span>, (S, L, K,) like as you say <span class=\"ar\">كَفّاكَ</span> and <span class=\"ar\">كَفَيْكَ</span>, (L.,) and <span class=\"ar\">بِرَجُلَيْنِ هَدَّاكَ</span>, and <span class=\"ar\">بِرِجَالٍ هَدُّوكَ</span>, and <span class=\"ar\">بِٱمْرَأَتَيْنِ هَدَّتَاكَ</span>, and <span class=\"ar\">بِنِسْوَةِ</span> <span class=\"ar\">هَدَدْتَكَ</span>. (S, L, K.) -b2- IAar also cites the following ex. [by El-Kattál El-Kilábee, (marginal note in a copy of the S)] <span class=\"ar\">وَلِى صَاحِبٌ فِى الغَارِ هَدَّكَ صَاحِبًا</span> as meaning. [<i>And I have a companion in the race;</i>] <i>of how great estimation, and how ingenious, and how knowing, is he</i> [<i>as a companion</i>] describing a wolf: (L:) in which he who reads <span class=\"ar\">هَدَّكَ</span> makes <span class=\"ar\">هَدَّ</span> a verb; and as such it has a dual and pl. and fem. but some read <span class=\"ar\">هَدُّكَ</span>. making it an inf. n. used as an epithet; and as such it has no dual nor pl. nor fem. (Marginal note in a copy of the S.) -b3- <span class=\"ar\">هَدَّ الرَّجُلُ</span> also signifies <i>Excellent is the man;</i> (ISd, L:) and <span class=\"ar\">إِنّهُ لَهَدَّ الرَّجُلُ</span> <i>Verily, excellent is the man</i> (L, K) <i>in hardiness and strength:</i> (L:) and <span class=\"ar\">لَهَدَّ</span> <span class=\"ar\">الرَّجُلُ</span> <i>How hardy is the man!</i> (L.) -b4- In a trad., Aboo Lahab is related to have said, <span class=\"ar\">لَهَدَّ مَا سَخَرَكُمْ صَاحِبُكُمْ</span>, [meaning <i>How greatly hath your companion enchanted you!</i>): <span class=\"ar\">لَهَدَّ</span> is an expression of wonder. (L.) -b5- <span class=\"ar\">فُلَانٌ يُهَدُّ</span> <i>Such a one is praiseworthy for hardiness</i> (S, L, K) <i>and strength.</i> (S, L.)</p><p><b>2.</b> <b class=\"ar\">هدّدهُ</b> , (Msb, K,) inf. n. <span class=\"ar\">تَهْدِيدٌ</span> (S, L) and <span class=\"ar\">تَهْدَادٌ</span>; (L:) and <span class=\"ar\"> <span class=\"ar\">تهدّدهُ</span></span>: (S, L, Msb;) <i>He threatened him;</i> (L;) <i>threatened him with punishment;</i> (Msb;) <i>frightened,</i> or <i>terrified, him.</i> (S, L, K.)</p><p><b>5.</b> <b class=\"ar\">تَهَدَّدَ</b> see 2.</p><p><b>7.</b> <b class=\"ar\">انهدّ</b> <i>It</i> (a building) [<i>fell down:</i> or] <i>became demolished at once, with a vehement noise:</i> (Msb:) and <span class=\"ar\"> <span class=\"ar\">هَدَّ</span></span>, aor. <b class=\"ar\">هَدِدَ</b> , <i>it</i> (a wall) <i>fell down;</i> mentioned by AHei; and also by Es-Semeen, who concedes it; (MF;) but this form of the verb is commonly known only as transitive. (TA.) -b2- <i>It</i> (a mountain) <i>broke down.</i> (S, L.)</p><p><b>10.</b> <b class=\"ar\">استهدّهُ</b> <i>He regarded him as weak.</i> (L.)</p><p><b>R. Q. 1.</b> <b class=\"ar\">هَدْهَدَ</b> , (S, L, K,) inf. n. <span class=\"ar\">هدْهَدَةٌ</span>, (S, L,) <i>He</i> (a bird) <i>cooed;</i> syn. <span class=\"ar\">قَرْقَرَ</span>: (L, K, TA [in the CK, <span class=\"ar\">فَرْفَرَ</span>]:) <i>he</i> (a pigeon) <i>cooed</i> syn. <span class=\"ar\">هَدَرَ</span>, and <span class=\"ar\">هَدَلَ</span>: (TA:) or <i>made a murmuring</i> or <i>confused noise</i> in cooing: (S, L, accord to the explanation of <span class=\"ar\">هَدْهَدَةٌ</span>:) and <i>he</i> (a camel, S, L) <i>brayed:</i> syn. <span class=\"ar\">هَدَرَ</span>: (K:) or <i>made a murmuring</i> or <i>confused noise</i> in braying (S, L,) See also 1. -b2- <span class=\"ar\">هَدْهَدَتْ</span>, (inf. n. <span class=\"ar\">هَدْهَدةٌ</span>, L.) <i>She</i> (a woman, S, L) <i>shook,</i> or <i>rocked,</i> a child (S, L, K) in its cradle, (L,) <i>in order that it might sleep.</i> (S, L, K.) -A2- <span class=\"ar\">هَدْهَدَ</span> <i>He sent,</i> or <i>threw,</i> a thing <i>down,</i> from a high place to a low one, (L, K.)</p><p><b class=\"ar\">هَدٌّ</b> A <i>weak</i> man; (As, S, L, K;) i. e., <i>weak in body;</i> (L;) as also <span class=\"ar\"> <span class=\"ar\">هِدٌّ</span></span>: (K:) or, accord. to IAar, the latter only, meaning <i>cowardly and weak:</i> (S, L:) or <span class=\"ar\">هَدٌّ</span> (Sh, L) and <span class=\"ar\"> <span class=\"ar\">أَهدُّ</span></span> (L, K) and <span class=\"ar\"> <span class=\"ar\">هَدَادَةٌ</span></span> (Sh, L, K) signify a <i>cowardly</i> (<i>and weak,</i> TA) man: (Sh, L, K:) and <span class=\"ar\">قَوْمٌ <span class=\"ar\">هَدَادٌ</span></span> <i>a cowardly people:</i> (Sh, L:) pl. of <span class=\"ar\">هَدٌّ</span>, <span class=\"ar\">هَدُّونَ</span>: (L, K:) it has no broken pl. (L:) and of <span class=\"ar\">هِدٌّ</span>, <span class=\"ar\">هِدّٰونَ</span>. (K.) A man says to another, in threatening him, <span class=\"ar\">إِنِّى لَعَيْرُ هَدٍّ</span> <i>Verily I am not weak.</i> (S, L.) -b2- <span class=\"ar\">هَدٌّ</span> <i>Extreme odd age; decrepitude.</i> (K, TA.) See 1. -A2- <span class=\"ar\">هَدٌّ</span> <i>A cough,</i> or <i>harsh, sound;</i> as also <span class=\"ar\"> <span class=\"ar\">هَدَدٌ</span></span>. (L, K.) -b2- <span class=\"ar\">هَدٌّ</span> The <i>braying</i> of a camel. (Lh, L, K.) See 1. -A3- <span class=\"ar\">هَدٌّ</span> <i>A generous, liberal. beautiful</i> man. (IAar. S, L, K. *) -b2- A <i>strong</i> man. (IAar. L.) -b3- <span class=\"ar\">لِى صَاحِبٌ هَدُّكَ صَاحِبًا</span>, and <span class=\"ar\">مَرَرْتُ بِرَجُلٍ هَدِّكَ مِنْ</span> <span class=\"ar\">رَجُلٍ</span>: see 1.</p><p><b class=\"ar\">هِدٌّ</b> and <span class=\"ar\">هَدَرٌ</span>: see <span class=\"ar\">هَدٌّ</span>.</p><p><b class=\"ar\">هَدَّةٌ</b> The <i>sound of the fall of a wall</i> or <i>the like:</i> (S:) or <i>a violent sound occasional thereby,</i> or <i>by the fall of a part of a mountain.</i> (L.) -b2- The <i>sound of rain falling from the sky.</i> (L.) -b3- <i>A sinking, and falling in, of the ground.</i> (L.)</p><p><b class=\"ar\">هَدْهَدٌ</b> The <i>voices,</i> or <i>cries, of jinn,</i> or <i>genii:</i> without a singular. (L, K)</p><p><b class=\"ar\">هُدْهُدٌ</b> <i>A certain bird,</i> (S, L, Msb, K,) <i>well known;</i> (L, Msb, K;) [namely, the <i>hoopee,</i> or <i>upupa</i> of Linnæus; so this bird is called in the present day; and this, accord. to a common tradition, is the bird mentioned in the Kur, xxvii. 20;] as also <span class=\"ar\">هُدَهِدٌ</span> (K) and <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (S, L, K:) or the last, <i>a certain bird resembling the pigeon:</i> (Lth, Az, L:) or (in the K, and) <span class=\"ar\">هُدْهُدٌ</span> signifies <i>a pigeon that cooes much;</i> (IDrd in explanation of v. 20 of ch. xxvii. of the Kur., and AHn, L K;) as also <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (IDrd, AHn, L:) and <i>any bird that cooes; that utters the cry called</i> <span class=\"ar\">قَرْقَرَة</span>; (L, K, TA [in the CK, <span class=\"ar\">يُفَرْفِرُ</span> is put for <span class=\"ar\">يُقَرْقِرُ</span>]) as also <span class=\"ar\"> <span class=\"ar\">هُدَاهِدٌ</span></span>: (As, L:) pl. (of all, K) <span class=\"ar\">هَدَاهِدُ</span> (S, L, K) and <span class=\"ar\">هَدَاهِيدُ</span>: (Kr, L, K:) but ISd says of the latter, I know not how this is, unless the sing. be <span class=\"ar\">هَدْهَادٌ</span>. (L.) Er-Rá'ee says, <span class=\"ar\">كَهُدَاهِدٍ كَسَرَ الرُّمَاةُ جَنَاحَهُ</span> [<i>Like a</i> <span class=\"ar\">هداهد</span> <i>whose wing the shooters have broken</i>]: (S, L:) As says, he means the <span class=\"ar\">فَاخِتَة</span>, or the <span class=\"ar\">دُبْسِىّ</span>, or the <span class=\"ar\">وَرَشَان</span>, or the <span class=\"ar\">هُدْهُد</span>, or a man, or camels: and Lh says, that Ks asserts him to mean, by <span class=\"ar\">هداهد</span>, the dim. of <span class=\"ar\">هُدْهُدٌ</span>: but As disapproves of this; and so does ISd; but the latter adds, that it may perhaps be for <span class=\"ar\">هُدَيْهِدٌ</span>; as some of the Arabs say <span class=\"ar\">دُوَابَّةٌ</span> and <span class=\"ar\">شُوَابَّةٌ</span> for <span class=\"ar\">دُويْبَّةٌ</span> and <span class=\"ar\">شُوَيْبَّةٌ</span>; though they are only known to change the <span class=\"ar\">ى</span> into <span class=\"ar\">ا</span> before a double consonant. (L.)</p><p><b class=\"ar\">هَدْهَدَةٌ</b> [an inf. n. used as a simple subst.] The <i>murmuring</i> or <i>confused sound of</i> the <i>cooing</i> of pigeons, and <i>of</i> the <i>braying</i> of a camel [and of thunder (see <span class=\"ar\">زَمْزَمَةٌ</span>)]: pl. <span class=\"ar\">هَدَاهِدُ</span>. (S, L.)</p><p><b class=\"ar\">هَدَادٌ</b> and <span class=\"ar\">هَدَادَةٌ</span>: see <span class=\"ar\">هَدٌّ</span>.</p><p><b class=\"ar\">هُدَاهِدٌ</b> A stallion-camel <i>that brays much among the she-camels but does not cover them.</i> (L.) -b2- See <span class=\"ar\">هُدْهُدٌ</span>.</p><p><b class=\"ar\">هَدِيدٌ</b> <i>A voice, cry, sound,</i> or <i>noise.</i> (L.) See also 1. -b2- <i>A threatening from behind one.</i> (As, L.)</p><p><b class=\"ar\">هَادٌّ</b> <i>A certain murmuring sound from the sea;</i> (K;) <i>a sound which is heard by people inhabiting the sea-shore, coming to them from the direction of the sea, murmuring over the land, and sometimes followed by an earthquake.</i> (S, L.)</p><p><b class=\"ar\">هَادَّةٌ</b> <i>Thunder.</i> (L, K.) Ex. <span class=\"ar\">مَا سَمِعْنَا العَامَ هَادَّةً</span> <i>We have not heard this year thunder.</i> (L.)</p><p><b class=\"ar\">أَهَدُّ</b> : see <span class=\"ar\">هَدٌّ</span>.</p>"},"هجع":{"mf":"الهُجُوع: النّوم ليلا. قال تعالى: كانُوا قَلِيلًا مِنَ اللَّيْلِ ما يَهْجَعُونَ<br>[الذاريات/ ١٧] وذلك يصحّ أن يكون معناه: كان هُجُوعهم قليلا من أوقات الليل، ويجوز أن يكون معناه: لم يكونوا يهجعون. والقليل يعبّر به عن النّفي والمشارف لنفيه لقلّته، ولقيته بعد هَجْعَةٍ. أي:<br>بعد نومة، وقولهم: رجل هُجَعٌ كقولك: نوم للمستنيم إلى كل شيء.","mq":[["نوم وهجع هجوعا: نام ليلا"],"الهاء والجيم والعين: كلمةٌ تدلُّ على نَوم وهَجَع هُجوعاً:<br>نام ليلاً. ولقيتُه بعد هَجعةٍ.<br>ومما قِيسَ على هذا: رجلٌ هجع (٥)<br>، أى أحمقُ مُستَنِيمٌ إلى كُلٍّ.<br>"],"ln":"<p><b>5.</b> <b class=\"ar\">تَهَجَّعَ</b> <i>He slept.</i> (1001 Nights, ii. 321.)</p><p><b class=\"ar\">هَجْعَةٌ</b> (assumed tropical:) The <i>setting</i> of a star. (Sgh in TA, art. <span class=\"ar\">شرط</span>.) See <span class=\"ar\">شَرَطٌ</span>. -b2- <i>A light sleep in the first part of the night.</i> (S.)</p>"},"همر":{"mf":"الهَمْرُ: صبّ الدّمع والماء، يقال: هَمَرَهُ فَانْهَمَرَ. قال تعالى: فَفَتَحْنا أَبْوابَ السَّماءِ بِماءٍ مُنْهَمِرٍ<br><strong>[القمر/ ١١] وهَمَرَ ما في الضّرع:</strong><br>حلبه كلّه، وهَمَرَ الرجل في الكلام، وفلان يُهَامِرُ<br><br>الشيء أي: يجرفه، ومنه: هَمَرَ له من ماله:<br>أعطاه، والهَمِيرَةُ: العجوز.","mq":[["صب وانصباب"],"الهاء والميم والراء: أصلٌ يدلُّ على صَبٍّ وانصباب. وهَمَر دمْعه. وهَمَرَ الدّمعُ وانهمَرَ: سالَ. وفلانٌ يُهامِر الشَّئ، إذا أخذه جَرْفا.<br>وهَمَر فى كلامِهِ: أكثرَ. وهو مِهمارٌ، أى كثير الكلام. وهَمَر له من مالِه، كأنَّه صَبّه له صَبَّا.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَمَرَهُ</b> , (S, A, K,) aor. <b class=\"ar\">هَمُرَ</b> (S, K) and <b class=\"ar\">هَمِرَ</b> , (K,) inf. n. <span class=\"ar\">هَمْرٌ</span>, (S,) <i>He,</i> or <i>it, poured it; out</i> or <i>forth;</i> (S, A, K;) namely, water, (S, TA,) and tears, and rain, and the like. (TA.) -b2- <span class=\"ar\">هَمَرَ مَا فِى الضَّرْعِ</span> <i>He drew forth all the milk that was in the udder.</i> (S, K.) -b3- <span class=\"ar\">هَمَرَ لَهُ مِنْ مَالِهِ</span> (assumed tropical:) <i>He gave to him of his property.</i> (S, K.) -b4- <span class=\"ar\">هَمَرَ الكَلَامَ</span>, (K,) or <span class=\"ar\">فى كَلَامِهِ</span>, (A,) aor. <b class=\"ar\">هَمُرَ</b> , inf. n. <span class=\"ar\">هَمْرٌ</span>: (TA;) and <span class=\"ar\"> <span class=\"ar\">إِنْهَمَرَ</span>بِالكَلَامِ</span>; (S;) (tropical:) <i>He talked much.</i> (K.) -A2- <span class=\"ar\">هَمَرَ</span>, intrans.: see 7. in two places.</p><p><b>7.</b> <b class=\"ar\">انهمر</b> <i>It poured; poured out</i> or <i>forth;</i> (K;) said of rain, and of tears; (TA;) as also <span class=\"ar\"> <span class=\"ar\">هَمَرَ</span></span>, (K,) aor. <b class=\"ar\">هَمِرَ</b> , inf. n. <span class=\"ar\">هُمُورٌ</span>; (TA;) [and so, app., <span class=\"ar\"> <span class=\"ar\">اهتمر</span></span>, q. v.:] <i>it flowed;</i> said of water, (S, K,) of rain, and of tears; like <span class=\"ar\">انهمل</span>: (TA:) and in like manner, <span class=\"ar\"> <span class=\"ar\">هَمَرَتْ</span>عَيْنُهُ بِالدَّمْعِ</span> <i>His eye flowed with tears;</i> as also <span class=\"ar\">هَمَلَتْ</span>. (A.) -b2- <span class=\"ar\">انهمر بالكلام</span>: see 1.</p><p><b>8.</b> <b class=\"ar\">اهتمر</b> : see 7. -b2- (tropical:) <i>He</i> (a horse) <i>ran</i> (S, K, TA) <i>like a torrent.</i> (TA.)</p><p><b class=\"ar\">هَمِرٌ</b> <i>Much sand;</i> as also <span class=\"ar\"> <span class=\"ar\">يَهْمُورٌ</span></span>. (K.)</p><p><b class=\"ar\">هَمْرَةٌ</b> <i>A fall of rain.</i> (K.) -b2- (tropical:) <i>Angry speech.</i> (Sgh, L, K.)</p><p><b class=\"ar\">هَمَرَى</b> : see <span class=\"ar\">هَمَّارٌ</span>.</p><p><b class=\"ar\">هَمَّارٌ</b> A cloud <i>pouring forth much rain;</i> as also <span class=\"ar\"> <span class=\"ar\">هَامِرٌ</span></span>. (K.) -b2- Applied to a man, (S,) (tropical:) <i>Loquacious, garrulous; babbling; a great talker; a babbler;</i> or <i>nonsensical, irrational, foolish,</i> or <i>delirious, in his talk;</i> as also <span class=\"ar\"> <span class=\"ar\">مِهْمَرٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مِهْمَارٌ</span></span> (S, K) and <span class=\"ar\"> <span class=\"ar\">يَهْمُورٌ</span></span>. (Sgh, K.) And <span class=\"ar\"> <span class=\"ar\">خَطِيبٌ</span>مِهْمَرٌ</span> (tropical:) <i>An orator copious in speech.</i> (A, TA) And <span class=\"ar\"> <span class=\"ar\">هَمَرَى</span></span>, applied to a woman, (tropical:) <i>Clamorous;</i> (K, TA:) <i>abounding in talk</i> or <i>speech, like a pouring torrent.</i> (TA.)</p><p><b class=\"ar\">هَامِرٌ</b> <i>Pouring</i> rain, and tears; as also <span class=\"ar\"> <span class=\"ar\">مُنْهَمِرٌ</span></span>. (TA.) See also <span class=\"ar\">هَمَّارٌ</span>.</p><p><b class=\"ar\">مِهْمَرٌ</b> : see <span class=\"ar\">هَمَّارٌ</span>; the former, in two places.</p><p><b class=\"ar\">مِهْمَارٌ</b> : see <span class=\"ar\">هَمَّارٌ</span>; the former, in two places.</p><p><b class=\"ar\">مُنْهَمِرٌ</b> : see <span class=\"ar\">هَامِرٌ</span>.</p><p><b class=\"ar\">يَهْمُورٌ</b> : see <span class=\"ar\">هَمِرٌ</span>: -A2- and see also <span class=\"ar\">هَمَّارٌ</span>.</p>"},"هلع":{"mq":[["سرعة وحدة"],"الهاء واللام والعين: يدلُّ على سُرعةٍ وحِدَّة. وناقة هِلْوَاعٌ:<br>حديدة سريعة. ونعامةٌ هالِعٌ كذلك. ومنه الهَلَعُ فى الإنسان: شِبْه الحِرْص.<br>ورجلٌ هَلِعٌ وهَلُوع.<br>قال ابن السِّكِّيت: رجلٌ هُلَعَة يَهْلَعُ ويَجْزَع سريعاً. ويقال: ما لَهُ هِلَّعٌ ولا هِلَّمة، أى جَدْىٌ ولا عَنَاق، وسمِّيا بذلك لنَزقِهما"]},"هرب":{"mq":[[],"الهاء والراء والباء كلمةٌ واحدة، هي هَرَب، إذا فَرّ. وما له هاربٌ ولا قاربٌ، أى صادرٌ عن الماء ولا وارد، أى لا شئَ له.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَرَبَ</b> , (S, K,) aor. <b class=\"ar\">هَرُبَ</b> ; not <b class=\"ar\">هَرَبَ</b> , as some have imagined on account of the measure of the first of the following inf. ns., imagining thence also that the pret. is <span class=\"ar\">هَرِبَ</span>; nor <b class=\"ar\">هَرَبَ</b> with the pret. <span class=\"ar\">هَرَبَ</span>, as some have supposed because of the guttural letter; for a guttural letter, when it is the first, is not reckoned as having any influence on the form of the aor.; nor <b class=\"ar\">هَرِبَ</b> , as some have thought; (TA;) inf. n. <span class=\"ar\">هَرَبٌ</span> (S, K) and <span class=\"ar\">مَهْرَبٌ</span> and <span class=\"ar\">هَرَبَانٌ</span>; (K;) <i>He</i> (a man, or any animal, TA) <i>fled; ran away.</i> (S, K.) -b2- <span class=\"ar\">إِلَيْكَ مِنْكَ المَهْرَبُ</span> [<i>To Thee I flee for refuge from Thee;</i> i. e., from thy punishment: addressed to God]. (TA.) -b3- <span class=\"ar\">هَرَبَ مِنَ الوَتَدِ</span> <span class=\"ar\">نِصْفُهُ</span> <i>Half of the wooden pin, peg,</i> or <i>stake, disappeared</i> [<i>in the ground</i>]. (K.) -A2- <span class=\"ar\">هَرِبَ</span>, aor. <b class=\"ar\">هَرَبَ</b> , <i>He became extremely aged, old and weak,</i> or <i>decrepit; i. q.</i> <span class=\"ar\">هَرِمَ</span>; (K;) of which it is a dial. form. (TA.)</p><p><b>2.</b> <b class=\"ar\">هرّبه</b> , inf. n. <span class=\"ar\">تَهْرِيبُ</span>, <i>He made,</i> or <i>caused, him to flee,</i> or <i>run away.</i> (S, K.) See also 4.</p><p><b>4.</b> <b class=\"ar\">اهربه</b> <i>He forced,</i> or <i>compelled, him to flee,</i> or <i>run away.</i> (K.) See also 2. -b2- <span class=\"ar\">اهربتِ الرِّيحُ</span> <i>The wind raised and carried away the dust,</i> (K,) <i>causing dust and dry herbage &amp;c. to accumulate on the ground.</i> (TA.) -b3- <span class=\"ar\">اهرب</span> <i>He</i> (a horse, or other animal that runs, Lh) <i>strove,</i> or <i>exerted himself, in going away,</i> or <i>in flight, being frightened,</i> (ISk, S, K,) or <i>not being frightened.</i> (TA.) See <span class=\"ar\">جَاءَ مُهْرِبًا</span>. -b4- <span class=\"ar\">اهرب</span> <i>He went,</i> or <i>travelled, far into,</i> or <i>through, the land.</i> (TA.) [<span class=\"ar\"> <span class=\"ar\">هَرَبَ</span>فى الأَرْضِ</span>, mentioned also in the TA, seems to signify the same.] -b5- <span class=\"ar\">اهرب فِى الأَمْرِ</span> <i>He immersed himself in the affair; took extraordinary pains in it.</i> (K.) See <span class=\"ar\">جَاءَ مُهْرِبًا</span>.</p><p><b>6.</b> <b class=\"ar\">تهاربوا</b> (S, O, K, art. <span class=\"ar\">فر</span>,) <i>They fled, one from another.</i> (TK.)</p><p><b class=\"ar\">هُرْبٌ</b> The <i>thin integument of fat that covers the stomach and intestines:</i> or the <i>fat</i> [or <i>caul</i>] <i>that is spread over the intestines: i. q.</i> <span class=\"ar\">ثَرْبُ البَطْنِ</span>: (K:) a word of the dial. of El-Yemen. (TA.)</p><p><b class=\"ar\">مَا لَهُ هَارِبٌ وَلَا قَارِبٌ</b> <i>He has not</i> [of camels &amp;c.] <i>any that returns from water, nor any that comes to it;</i> i. e., <i>he has not anything;</i> (Kh, S, K;) or, <i>he has not anything, nor has he any people;</i> an expression similar to <span class=\"ar\">مَا لَهُ سَعْنَةٌ وَلَا مَعْنَةٌ</span>: (Lh:) accord. to IAar, <span class=\"ar\">هَارِبٌ</span> signifies <i>one who returns from water;</i> and <span class=\"ar\">قَارِبٌ</span>, <i>one who seeks,</i> or <i>journeys to, water:</i> (TA:) or the meaning is <i>no one flees from him, nor does any one approach him;</i> i. e., <i>he is a person of no account.</i> (As, K.) [In the TA a trad. is quoted which confirms the former signification.] See also art. <span class=\"ar\">قرب</span>.</p><p><b class=\"ar\">مَهْرَبٌ</b> <i>A place to which one flees; a place of refuge.</i> (Msb.) -b2- <span class=\"ar\">فُلَانٌ لَنَا مَهْرَبٌ</span> (assumed tropical:) <i>Such a one is a refuge to us.</i> (TA.)</p><p><b class=\"ar\">جَاءَ مُهْرِبًا</b> <i>He came striving,</i> or <i>exerting himself, in the affair:</i> (Lh:) or, as some say, <i>he came fleeing and in fright.</i> (TA.)</p><p><b class=\"ar\">مِهْرَبٌ</b> <i>A piece of wood,</i> or <i>wooden implement, which the sower,</i> or <i>ploughman, draws forward and backward</i> [<i>over the ground</i>]. (K.) [A piece of the trunk of a tree, or of a thick branch, is thus drawn over the soil after sowing.]</p>"},"هيل":{"mq":[["دفع شي يمكن كيله دفعا من غير كيل"],"الهاء والياء واللام كلمةٌ واحدةٌ تَدُلُّ على دَفْعِ شئٍ يمكن كَيْلُه دفعاً من غير كَيْل. وهِلْتُ الطَّعامَ أَهِيلُه هَيْلاً: أرسَلْتُه. قال اللّه سبحانه:<br>﴿وَكانَتِ اَلْجِبالُ كَثِيباً مَهِيلاً﴾. ومنه قولُهم: «جاءَ بالهَيْل والهَيْلَمُاَن»<br>، أى الشَّئ الكثير.<br>"],"ln":"<p><b>7.</b> <b class=\"ar\">اِنْهَالَ</b> <i>It</i> (sand, &amp;c.) <i>poured down.</i> (S, K.) -b2- <span class=\"ar\">اِنْهَدَمَ الجِدَارُ وَآنْهَالَ</span> [<i>The wall fell in ruins,</i> or <i>to pieces,</i> or <i>became a ruin, and broke,</i> or <i>crumbled down</i>]. (K in art. <span class=\"ar\">قيض</span>.) So rendered voce <span class=\"ar\">اِنْقَاضَ</span>, art. <span class=\"ar\">فيض</span>.</p><p><b class=\"ar\">هَيْلٌ</b> inf. n. of <span class=\"ar\">هَالَ</span>: see <span class=\"ar\">حَثَا</span>. -b2- <span class=\"ar\">هَيْلٌ</span> and <span class=\"ar\"> <span class=\"ar\">هَائِلٌ</span></span> Sand <i>that will not remain steady in its place, but falls down.</i> (JK.)</p><p><b class=\"ar\">هَيُولُى</b> and <span class=\"ar\">هَيُّولَى</span>: wrongly mentioned in art. <span class=\"ar\">هول</span>. See <span class=\"ar\">مَادَّةٌ</span>.</p><p><b class=\"ar\">مَهِيلٌ</b> : see <span class=\"ar\">كَثِيبٌ</span>.</p>"},"هزل":{"mf":"قال تعالى: إِنَّهُ لَقَوْلٌ فَصْلٌ وَما هُوَ بِالْهَزْلِ<br>[الطارق/ ١٣- ١٤] الْهَزْلُ: كلّ كلام لا تحصيل له، ولا ريع تشبيها بِالهُزَالِ.","mq":[["قياس واحد"],"الهاء والزاء واللام كلمتانِ فى قياسٍ واحد، يدُلاّنِ على.<br>ضَعف. فالهَزْل: نقيض الجِدّ. والهُزَال: خِلَاف السِّمَن. يقال: هَزَلْتُ دابّتى وقد هُزِلت. وهَزَلَ فى مَنطِقِه. وأهْزَل: وقع فى ماله الهُزَال.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">هَزْلٌ</b> is <i>contr. of</i> <span class=\"ar\">جِدٌّ</span>. (S, Mgh, K.) You say, <span class=\"ar\">هَزَلَ</span>, aor. <b class=\"ar\">هَزِلَ</b> , inf. n. <span class=\"ar\">هَزْلٌ</span>; (S, Msb, K;) and <span class=\"ar\">هَزِلَ</span>, aor. <b class=\"ar\">هَزَلَ</b> , (K,) inf. n. as above; (TA;) and <span class=\"ar\"> <span class=\"ar\">هَازَلَ</span></span>; (K;) <i>He jested,</i> or <i>joked;</i> (Msb;) or <i>was not serious,</i> or <i>in earnest;</i> (TA;) <span class=\"ar\">فِى كَلاَمِهِ</span> <i>in his speech;</i> (Msb, TA;) and <span class=\"ar\">فِى الأَمْرِ</span> <i>in the affair.</i> (TA.)</p><p><b>3.</b> <b class=\"ar\">هَازَلَ</b> <i>He jested,</i> or <i>joked.</i> (K.) See 1.</p><p><b class=\"ar\">هُزاَلٌ</b> <i>Leanness, meagreness, emaciation: contr. of fatness.</i> (S, K.)</p><p><b class=\"ar\">هَزْلَى</b> , pl. of <span class=\"ar\">هَزِيلٌ</span> <i>Lean, meagre, emaciated.</i> (K, voce <span class=\"ar\">خَشَبٌ</span>.)</p><p><b class=\"ar\">مَهْزُولٌ</b> : see two exs. in a verse cited voce <span class=\"ar\">عِرْضٌ</span>.</p>"}});
